/* 平成16年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h16.committeeSessions.push(...[{"id":"h16-20040310-3","meetingId":"h16-c-budget","date":"2004年3月10日","dateIso":"2004-03-10","committee":"予算特別委員会","time":"午前１０時０５分～午後６時４１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を173件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"私は今日お伺いするのは、１９９ページのかかりつけ医・歯科医定着促進事業についてお伺いをしたいと思います。この１６人という数字の根拠といいますか、どういうところから１６人という増員がなされたのかご説明願いたいと思います。","respondent":"日下部障害者福祉課長","answer":"実は民生委員につきましては３年に一遍、一斉改選ということで実施をしておりますけれども、その時期が今年の１２月にまいります。私ども先ほど申し上げましたように、東京都のほうと協議をいたしまして、全体で１６人の増員ということで合意に達したです。","id":"exchange-001"},{"speaker":"大沢委員","kind":"意見","question":"先ほど１２月ということですが、１２月の何日に改正があるのか、お答えをお願いしたいと思いますとの意見を述べました。","respondent":"日下部障害者福祉課長","answer":"１２月１日付です。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"１２月１日に増員されるということですけれども、数といいますか、東京都と協議をしながら１６人ということを決められたということですが、品川区としては民生委員１人が担当する対象者の適当な数というのは、大体どのぐらいかご見解をお伺いしたいと思います。","respondent":"日下部障害者福祉課長","answer":"実は２３区につきましては、２２０世帯から４４０世帯というちょっと幅があり過ぎるんですけれども、そういう基準が出てあります。つまり、そういった点もありますので、なかなか一概にどのぐらいが適当かというのは難しい面があろうかというふうに考えております。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"５８０世帯ぐらいで、担当する側において民生委員が５８０世帯ということですけれども、何か基準みたいなものがあるんでしょうか。民生委員が動き得るに耐えるだけの半径といいますか面積という、そのような具体的なものというのは、基準というのはお持ちなのか尋ねました。","respondent":"日下部障害者福祉課長","answer":"特に、距離的にどのぐらいかだとか、そういう基準はございません。都の一つの考え方でもありますけれども、いろいろな地形上の問題等もありますけれども、その辺が一つの考え方の基本になっているという面があります。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"今、課長がおっしゃったように、生活保護世帯の方、高齢者の方、いろいろといるわけですけれども、広さの部分は質問させていただきました。どういう対象者の方であればこの民生委員に任せよう、この民生委員に任せようというような、そういう対象者の基準みたいなものはあるんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"区と地域との一種のパイプ役を担っていくということでございまして、そういった意味では幅広く相談に対応するということが基本になってあります。そういった点からいきますと、ほかの区以上に重点を置いて民生委員の活動の中に位置づけをしていると、そんな特徴もあります。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"今、課長のほうで高齢者相談員、見守り。思うには、１町会を担当する民生委員の地区割みたいなものができてもいいような気がするんですが、どんなふうにお考えか尋ねました。","respondent":"日下部障害者福祉課長","answer":"私どもとしましても民生委員の活動を円滑に進めていくためには、これが一番望ましいんではないかと、このように考えております。やはりいろんな心配もあるとか、いろいろそういう事情もありまして、一気に解消することがなかなか難しいという現状です。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"最初に、事務事業概要によりますと、「区民が身近で気軽に適切な医療サービスを受けられるよう」と書いてあります。これは広く区民を指しているんでしょうか、それとも区民という文言に何か意味合いというのはあるんでしょうか、お伺いしたいと思います。","respondent":"田中健康課長","answer":"区民といいますか、あるいは転入等で品川区に入ってきた場合、まだかかりつけ医を持たない方もいらっしゃいます。そういう方を含めて、かかりつけのお医者さんにもっと身近に相談事ができるようにというのが、この制度の基本の考え方というふうに考えております。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"広く区民ということで、理解をします。内科とありますが、事務事業概要には四つ区分がありますけれども、この四つの区分で網羅なくかかりつけ医としての紹介窓口になっているんか尋ねました。","respondent":"田中健康課長","answer":"そういう方に対して対応できるところ、耳鼻科、皮膚科等々の専門という形です。その地域等、通いやすいところにこういう病院がありますよというのを、それぞれ二つの医師会の事務局から紹介をするシステムになってあります。","id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"１９９ページにかかりつけ医・歯科医定着促進と書いてあるんですが、歯科医は今まで入っていなかったんか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"１９９ページに記載しています、一層促進を進めようということで、主なものはＰＲの経費です。平成１２年から年次計画でそれぞれポスター、効果的なＰＲを進めていこうということで、健康課と協力連携をしながら進めているというものです。","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"今度は受ける側からの質問なんですけれども、かかりつけ医調整委員会という委員会がありますけれども、この委員会では患者に対して自分たちが施した医術に関して満足度という、そんなような部分をＰＲとして考えて議論する委員会なのでしょうか、お伺いしたいと思います。","respondent":"田中健康課長","answer":"それから、福祉施設関係も含まれてあります。診療所で新たに病院の紹介ですとか、病院からの逆紹介ですとか、そういう内容を含んでいる調整の場です。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問・要望","question":"区民の声をフィードバックできるような、そしてさらにサービスに役立てるようなシステムづくりをお願いしたいと、制度にしてほしいと求めました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"嶋委員","kind":"質問・要望","question":"三つ目に、２０１ページの障害児の地域での自立支援策についてお伺いいたします。それから、２１７ページ、児童センター運営費について、もしお時間があれば２１３ページ、保育園の園庭についてお伺いをいたします。","respondent":"早津高齢福祉課長、島袋品川区保健所衛生課長","answer":"一定の身体が弱まっている方については自立支援のホームヘルプ制度というものもありますので、実質的に何とかできないかというふうに思います。そういった形でも実施しておりますので… コインランドリーの設置につきましては、保健所に申請していただいて要件を満たせば許可できるです。八潮地区でも同じことです。","id":"exchange-012"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう意味ではやっぱり下りが大変厳しいということで、今後高齢化が進む、時間差でぜひお考えをいただきたいと考えています。それについてお考えを。","respondent":"日下部障害者福祉課長","answer":"コインランドリーの品川総合福祉センターへの設置の件ですけれども、この辺につきましては、そういうような地元の声もあるということで、品川総合福祉センターのほうに伝えまして、その辺の可能性についても検討を進めていくということにさせていただきたいと思います。","id":"exchange-013"},{"speaker":"嶋委員","kind":"質問・要望","question":"介護予防の手引きということも、ぜひお考えをいただきたいと考えていますので、よろしくお願いいたします。二つ目、１９７ページの緊急通報システムのことについてお伺いをいたします。","respondent":"早津高齢福祉課長","answer":"大きく分けまして、二つの種類があります。消防庁直結型のほうが平成１５年度１月時点ですが２３９人の利用、それから民間の直結型のほうが１２８人のご利用という状況です。","id":"exchange-014"},{"speaker":"嶋委員","kind":"質問","question":"今、火災で高齢者の方が命を落とされるというニュースが大分出てきておりまして、何とかならないのかなという思いがいっぱいです。火災発生時に消防庁に自動的に通報できるような火災報知機などの設置を考えておりますが、いかがでしょうか、お考えを聞かせていただきます。","respondent":"早津高齢福祉課長","answer":"火災報知機につきましても、対象者を同じくしての制度はあるんですが、あまり利用されていないという実態があります。今後の火災報知機についての考えについては、必要性等も含めまして、ちょっと検討させていただきたいというふうに思います。","id":"exchange-015"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひご配慮をいただきたいと、積極的に高齢者の安全を確保してほしいと求めましたので、どうぞよろしくお願いいたします。このことについて詳しくご説明をいただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"嶋委員","kind":"質問・要望","question":"家庭あんしんセンターが１２歳まで、また１２歳以上１８歳までが昨年４月から品川総合福祉センターで見ていただけるということで、その辺をお聞かせほしいと求めました。","respondent":"日下部障害者福祉課長","answer":"７日ではとても対応仕切れないということで、今まで区では大島のほうにミドルステイ用ということで２床ほどベッドを持ってございました。","id":"exchange-017"},{"speaker":"嶋委員","kind":"確認","question":"そういう意味では、今までは就労もいけなかったんです。今回の内容も就労もだめということなのか、確認をしたいと思います。","respondent":"日下部障害者福祉課長","answer":"この要望が強く出ておりますのは就労していらっしゃる方ですので、当然のことながら、こういった皆さん方をまず対象にして事業を組み立てたものです。","id":"exchange-018"},{"speaker":"嶋委員","kind":"質問・要望","question":"今回、図書館が全館８時までということになります。７時のところもあるかと思いますが、中高生からの要望がありますが、いかがか尋ねました。","respondent":"辻田児童課長","answer":"そういう中で、私どものほうも児童センターのあり方検討委員会というのを設置して、その中で検討してまいりました。その中で、平成１８年度本格的試行に向けてやっていこうです。","id":"exchange-019"},{"speaker":"嶋委員","kind":"質問・要望","question":"園庭の砂塵で大変地域が困っているということで、家の中まで入り込んで、お掃除をしてもだめです。特に、日曜、祭日の保育園が休園のときにご配慮をお願いしたいという地域の要望がありますが、そういう点でお考えお聞かせほしいと求めました。","respondent":"金子保育課長","answer":"近隣のお宅のほうにご迷惑がかかるということは、私どもも連絡をいただいて、対応については苦慮しています。平日におきましては委員ご指摘のとおり、現場でかなり散水をして対応しているところですが、対応仕切れないというのが現実にはあります。","id":"exchange-020"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういうところもお考えをいただいて、ご配慮ほしいと求めました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１９９ページの障害者福祉手当、あと１９７ページ、２０１ページの高齢者そして障害者の緊急通報システムと火災安全システムについてお伺いをします。難病手当のところでは、若干特殊疾病の医療費の助成のほうにも連動してお伺いしますが、お許しをほしいと求めました。","respondent":"日下部障害者福祉課長","answer":"この中の重い方については１種の手当ということですが、それ以外の方については２種の手当ということで、そういうような中身です。この中に難病の医療費の助成を受けている方も含まれておりまして、現在のところ難病の方を対象にした手当といたしましては１,０５０人ほどです。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域の方からぜひ難病手当を増やしてほしいという声をいただいていますので、聞いてほしいと求めました。いかがか尋ねました。","respondent":"日下部障害者福祉課長","answer":"確かに、難病でいろいろお困りの方、生活面でもいろいろ大変かと思います。ただ、そういった点では現状の月当たり１万円ということで給付をしていますが、これを増額するということは考えてございません。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問","question":"私のような福祉の谷間にいるような者はどうやって生きていけばよいのでしょうか」という、たくさんの病気の方が。いかがか尋ねました。","respondent":"日下部障害者福祉課長","answer":"それから、最近では在宅のサービス等につきましても、以前にも増して充実の方向性にあると。ただその金額だけで判断するというわけにはいかないというふうに考えておりますし、金額については現行どおりということで考えてあります。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"総合的にそれは判断するとは思うんですけれども、私はちょっと控えめに言ったんですが、品川区の難病手当はあまりにも低過ぎるのではないか。品川区より低いところがあるのでしょうか、金額的なところでの評価というのはどうか尋ねました。","respondent":"日下部障害者福祉課長","answer":"２３区全体を見ますと、確かにご指摘のように品川区は１万円ということで、これにつきましては中野区と並びまして一番低い金額ではあります。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"支援というのは低いほうに揃えるんじゃなくて、やはり少しでも努力をして高いほうに引き上げていただきたいなと思います。難病手当の仕組みを知らなくて受けていらっしゃらない方がいるので、この辺のお互いの連携プレーのところがどうなっているか説明を求めました。","respondent":"日下部障害者福祉課長","answer":"ただ、難病の方々がまずは医療費の助成の関係でご相談に見えるというのが、まず基本ですけれども、医療費の助成で手続をされる。じゃ、難病の方々に対して非常に不便な仕組みですので、お互いが連携を取りまして窓口の体制をしっかり進めているという状況です。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成元年からですか、実際に去年のところで、難病手当のところが漏れている方がいらっしゃったんです。やっぱり、こういう姿勢が大事だと思いますが、いかがか尋ねました。","respondent":"日下部障害者福祉課長","answer":"通常の窓口の対応でも、その辺はしっかりとさらに連携を取りまして、見落としのないようにしっかりやっていきたいと思います。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"申請をしないと受けられないというところでは、ぜひ申請をしやすい、また漏れがない、優しい周知をよろしくお願い申し上げます。緊急通報システム、先ほども質問が出ていましたけれども、消防庁直結と民間のほうに委託している違いを教えていただきたいんですけれども。","respondent":"早津高齢福祉課長","answer":"消防庁直結型と申しますのは、ボタンを押したときに消防庁に連絡が行く一方、近隣の方で３名の協力員という方をお願いしています。一方、民間型につきましては、民間の事業者に連絡が行き、巡回パトロールカーが駆けつけると、こういうようなシステムの違いです。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"消防庁直結のほうは近隣の方とのネットワークがとても重視されていて、いい制度だと思うんですけれども、これを利用したいという方から、消防庁直結のほうが受けにくくて、民間のほうを紹介されるようなお話を伺ったんですけれども、資格要件でこれが違う部分があるんか尋ねました。","respondent":"早津高齢福祉課長","answer":"消防庁直結方式の場合は、協力員が３名必要というようなことで、そういう点がなかなか難しい方がいらっしゃるのではないか。そういうような方の場合ですと、協力員の要件もございませんので、民間のほうをお薦めしているという状況です。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この辺は、すごく基準があいまいであるなと思うんです。協力員３名の方がしっかり確保できて、ぜひ申請を受理していただきたいんですけれども、いかがか尋ねました。","respondent":"早津高齢福祉課長","answer":"先ほどご答弁申し上げましたように、糖尿病ですとか、入院歴があるというようなことを総合的に判断しています。具体的には、個別的な内容につきましては、ケアマネージャーのほうと遠慮なくご相談いただければというふうに考えてあります。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"安心のシステムなので、できるだけたくさんの方にご利用をいただいて、安心してほしいと求めました。だから、申請にあたってはハードルを高くしないで、ぜひ希望する多くの方が利用できる制度にしていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"高星委員","kind":"質問・要望","question":"だから、こういうこともありますものですから、基本的な考え方をお聞かせいただきたい。こちらのほうは３園というふうになっていて、２０９ページのほうは１園となっているので、この違いを教えていただきたいなというふうに思います。","respondent":"黒田生活福祉課長、金子保育課長","answer":"２３区では路上生活者自立支援事業ということで、就労による自立ということで、都区共同事業で取り組んでまいりました。行政も取り組む中で、継続的にやっていく中で… 公立が３園やっていまして、これが２１５ページの保育園運営費で３園と書いてあります部分の経費として計上しているものです。","id":"exchange-032"},{"speaker":"高星委員","kind":"質問・要望","question":"昔からあるじゃないですか、これはまさに保育の原点というか、人間としての本能なんだろうというふうに。やっぱり会社とかを説得して、そういうときに休みを取らせるような制度の問題だというふうに思うんですが、どうか尋ねました。","respondent":"金子保育課長","answer":"予定によれば平成１６年度については全施設とも認証保育所のＢ型移行が完了するということで、Ｂという評価で載せているものです。そういう意味ではこれを奨励していくつもりはありませんが、この事業については運営していきたいというふうに考えてあります。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"どう考えるべきかということ。各個室というのは、最低基準よりも広いのか、あれが基準なのか、今後のことも考えた上で、その辺を教えてほしいと求めました。","respondent":"日下部障害者福祉課長、早津高齢福祉課長","answer":"それから、そういった意味では、知的障害者の方の入所施設のあり方が大きな転換期を迎えているというふうに私ども認識をしています。施設解体と、大変センセーショナルに取り上げられておりますけれども… これが先ほど申しましたように、この基準になりますと居室は１５.６３m2ということで、６m2ほど狭くてもよろしいと。その分、目の前にあるリビングが役に立っているという、こういう形に変更になってあります。","id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それと同時に、その辺の考え方はどうなっていくのか、その２点をお願いいたしたいと思います。その辺のところを、もう一遍答えをお願いしたいと思います。","respondent":"日下部障害者福祉課長、早津高齢福祉課長","answer":"６年、９年ということで、それぞれの状況に応じた形で地域移行を実現できるように進めていきたいというふうに考えております。第１かもめ園につきましても地域移行と… ケアホームを今後建てるとした場合ですが、先ほどご答弁申し上げましたように、居室については６m2小さくなるというようなことも含めまして、ケアホーム西五反田と比べますとコンパクトな施設というのは十分可能です。","id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それから、次の質問に入ります。品川区の中の現状と、これによって今後の運営自体、支援費制度自体そのものが移行することはないんでしょうねという確認です。","respondent":"日下部障害者福祉課長","answer":"ですから、そういった流れも含めて、今後グループホームの整備にはしっかりと取り組んでまいりたいと、このように考えております。確かにスタートして１年でこれですから、今後ともしっかりと進めてまいりたいと、このように考えております。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"意見","question":"当然、内容がかわるということだと思いますけれども。サービスを受けている方の問題が多いのか、サービスを提供する方の問題が出ているのか、その辺も含めてお答えをほしいと求めました。","respondent":"高橋介護保険担当課長","answer":"１４年と３年間におきまして、在宅系のサービスを中心にサービス評価してまいりましたが、その中で仕組みを検討しながら構築してきたです。いろいろな苦情についてはやはり介護保険制度が始まったというところでの説明とか、今後構築して実施してまいりたいと思っていますので。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"補正の段階では２億８,０００万円ぐらいあったのが、逆に基金の繰り入れが出てしまった。今後の基金の運用について、十分検討していただきたいということで、その２点を簡単ですが。","respondent":"辻田児童課長、早津高齢福祉課長","answer":"確かに、高額所得者の方からは、そういうようなご意見をいただいております。ただ、私どものほうは粘り強く、この制度の福祉的な性格をご説明しながら納得していただいているという、そういうような状況です。 基金につきましては、１号保険料によって積み立てたものです。十分に大事にして運用をしていきたいと、このように考えてあります。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"私は、初めに２１５ページの家庭あんしんセンター、２１７ページのぷりすくーる西五反田、２１３ページの保育園運営費についてお伺いします。家庭あんしんセンターについてお伺いしますが、一昨年の９月にオープンしまして、障害者の施設からなっております。","respondent":"辻田児童課長","answer":"こういうような施設の利用増加に伴いまして、相談事業につきましても、一般的な相談につきまして約３００件を超える相談に対応している。それからもう一つ、大事な機能ですファミリーサポートも、相互援助活動を１,３２６件というような形で実施することができております。","id":"exchange-039"},{"speaker":"藤原委員","kind":"意見","question":"これからの課題について２点ぐらい出たと思うんですけれども、その問題点を踏まえて、今後どのような施策を展開していくか、お考えがありましたらお知らせくださいとの意見を述べました。","respondent":"辻田児童課長","answer":"特に、地域の民生委員、児童委員の方々、主任児童委員の方々、児童関係の方々にぜひそういう形で見ていただきたいということで進めてまいります。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問・要望","question":"１番目は二葉すこやか園、２番目はぷりすくーる西五反田と進んできたんですけれども、この次の３番目は考えているでしょうか。確か、国が平成１８年から、幼稚園でもない保育園でもないという施設をつくるやに伺っております。","respondent":"金子保育課長","answer":"幼保一元化あるいは一体化の施設の問題ですが、これらの施設の検証をしながら、今後については検討してまいりたいと思います。まだ詳細な情報を得ておりませんけれども、早期に情報を収集して、対応については慎重に検討してまいりたいと考えております。","id":"exchange-041"},{"speaker":"藤原委員","kind":"質問","question":"次に、待機児童についてお伺いしますが、２月２４日に第一次の結果が通知されたと思います。ずっと住んでいらっしゃる方が入れないというのはちょっと、えっと思う気持ちがあるんですが、その辺の対策について何かありますか尋ねました。","respondent":"金子保育課長","answer":"委員のお話の途中にありましたとおり、どちらも区民であるという点から、私どもとしては同列の扱いを現在のところしております。国のほうも入所要件については検討しているところでもありますので、この辺の動向も見ながら、検討していきたいと考えております。","id":"exchange-042"},{"speaker":"藤原委員","kind":"質問","question":"１点伺います。保育園と私立幼稚園の窓口が一体化になるんですけれども、公立との窓口も一本化になりませんか尋ねました。","respondent":"林（宏）委員長","answer":"行財政改革担当課長ですけれども、時間の関係でお答えできる時間がありませんから、後ほど個人的に聞いてください。次に、武内委員。","id":"exchange-043"},{"speaker":"武内委員","kind":"質問","question":"それから２０１ページの視覚障害者用触地図、４２１ページの「大江戸温泉物語」利用助成金、４点についてお伺いしたいと思います。初めに、１９３ページですけれども、品川区聴覚障害者協会に対しての助成を行っておりますけれども、内訳を説明するよう求めました。","respondent":"日下部障害者福祉課長","answer":"品川区聴覚障害者協会に対して補助を行っておりますけれども、これにつきましては全体の活動経費に対して年額トータルで３０万円を助成させていただいているということで、特段内訳等については、何に幾らというような形で定まっているものではございません。","id":"exchange-044"},{"speaker":"武内委員","kind":"質問","question":"主に活動費ということで、お伺いしました。品川区において耳マークのバッチをつけて窓口に来られる方というのはいらっしゃいますか尋ねました。","respondent":"日下部障害者福祉課長","answer":"ただ私ども窓口で対応させていただいている限りにおきましては、現在の段階では耳マークをつけた方がお見えになっているケースは、私自身は承知してございません。","id":"exchange-045"},{"speaker":"武内委員","kind":"質問","question":"個々の対応にあるのかもしれないですけれども、窓口に行かれてちょっと不自由されたようなこともお聞きしております。今後、耳が不自由な方がスムーズにいろんなサービスを受けられるような対応を区として考えられるかどうか、方向性だけお伺いいたします。","respondent":"日下部障害者福祉課長","answer":"その手話通訳者が同行するということで、特定の曜日ではありますけれども、聴覚障害者の方に適切な対応ができるようにということでやってあります。今、ご指摘の点も踏まえまして、より一層聴覚障害の方が窓口対応に困らないように配慮していきたいと、このように考えます。","id":"exchange-046"},{"speaker":"武内委員","kind":"意見","question":"ぜひ、取り組みのほう、よろしくお願いいたします。続きまして、１９９ページの高齢者住宅対策の住宅あっせんについてですけれども、この内容をどのような対応をされていらっしゃるかお教えくださいとの意見を述べました。","respondent":"蓼沼高齢事業課長","answer":"住宅あっせんについてのお尋ねですけれども、この予算につきましてはあっせんの成立したときの助成金、それから宅建品川支部に協力をお願いしておりますけれども、そのデータ登録整理等の委託料という中身です。","id":"exchange-047"},{"speaker":"武内委員","kind":"質問","question":"１４件の方があっせんを受けて入居されたというふうにお聞きしていますけれども、残りの残念ながらだめだった２３件の方の主な事情というか、どういった理由でだめだったのかというのがわかりましたら、主なところで結構ですけれども説明するよう求めました。","respondent":"蓼沼高齢事業課長","answer":"主に希望される内容で物件が見つからないということで、家賃等の問題ですとか、あるいは地域的な問題、住宅の設備の問題等々といった状況で、成立が見ないというようなケースが主なものかと思います。","id":"exchange-048"},{"speaker":"武内委員","kind":"意見","question":"ところで、確か最近新聞に載りましたけれども、品川区が他区とまた東京都と協力して住宅あっせんを考えているような記事が載ったような気がしたんですけれども、その辺もし、おわかりでしたらお教えくださいとの意見を述べました。","respondent":"蓼沼高齢事業課長","answer":"この住宅あっせん事業につきましては、宅建品川支部と区と協定を結びまして、そこに情報を密に流していくというような形の協定を結んだです。そして、あっせんの促進を図っていくということで、今取り組みを進めているところです。","id":"exchange-049"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、この予算の金額の中には、その取り組みのものは入っていないということでよろしいんか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"一部につきましては協力店の表示をするということでステッカーの作成を、これは年度内の予算で措置をいたしております。来年度につきましては、もろもろの登録に関するデータ関係の収集整理等の委託ということで、若干予算を組んです。","id":"exchange-050"},{"speaker":"武内委員","kind":"質問","question":"続きまして、２０１ページの視覚障害者用触地図についてお伺いしたいと思います。プレス発表も見まして、大体の内容は理解したんですけれども、もう一度大まかなところの概要を説明するよう求めました。","respondent":"日下部障害者福祉課長","answer":"そういったところに安心して行くことができるようにということで、最新の技術を使っておりまして地図に立体感を持たせてあるんですね。位置関係がわかってくるというものを、視覚障害者の団体の皆さん方のご意見等も伺いながらつくって活用していただくと、そういうことです。","id":"exchange-051"},{"speaker":"武内委員","kind":"意見","question":"約１,０００部マップをつくられる予定になっておりますけれども、４００人の対象者で１,０００部なので、その残りの６００部に関してはどのような使われ方をする予定でございましょうかとの意見を述べました。","respondent":"日下部障害者福祉課長","answer":"実は１枚の地図で１,０００部ということではなくて、対象の施設をどうするか、方向性をはっきりさせていきたいというふうに思っております。５カ所であれば１カ所につい２００部程度をつくって、いずれにしろ平成１６年度につきましては、このようなことです。","id":"exchange-052"},{"speaker":"武内委員","kind":"意見","question":"まだ始まっていないのであれですけれども、今後ガイドマップに組み込んだ施設が移転等で変わることも考えられると思うんですけれども、そうした場合に。","respondent":"日下部障害者福祉課長","answer":"実際にどんな形で進めていくのかということで、先へ進めてみないとなかなか具体的な課題等についてもはっきりしてまいりませんので、このように考えております。","id":"exchange-053"},{"speaker":"武内委員","kind":"意見","question":"非常にいい取り組みだと思いますので、ぜひよろしくお願いいたします。最後になりますけれども、４２１ページの「大江戸温泉物語」の国民健康保険利用者に対して、また大体の主な目的と概要をご説明をお願いいたしますとの意見を述べました。","respondent":"太田保険年金課長","answer":"今、保険事業ということで、日帰りのところで気楽に行ける温泉施設等がないということでいろいろ検討してきたわけです。長期的に医療費の削減にもつながっていくんじゃないかということで、今回企画をしたものです。","id":"exchange-054"},{"speaker":"武内委員","kind":"質問","question":"単純に計算しますと１人当たり３３３円ぐらいの利用なんですけれども、割り引きを見ると大人は９００円とか、その辺はどのようなお考えがあるのか説明を求めました。","respondent":"太田保険年金課長","answer":"１２万人という被保険者のマーケットを考えてありますので、そうしますと２００万円ですから約１６円ぐらいの単価、それは交渉の結果でその値段が決まったです。","id":"exchange-055"},{"speaker":"三村委員","kind":"質問・要望","question":"２０９ページの認証保育園について、２１５ページのファミリーサポート、２１７ページの児童センターについてお聞きしていきたいと思います。そして、認証保育園についても同じく平均的な保育料はどの程度なのか、最高幾らぐらい払っているのか、もしわかれば教えてほしいと求めました。","respondent":"金子保育課長","answer":"それから、平均的な額というお尋ねですが、すべての年齢とすべての階層を平均しますと、大体月当たり約１万７,３００円が保育料の平均であるです。","id":"exchange-056"},{"speaker":"三村委員","kind":"質問","question":"どうしてこのような質問をしたかといいますと、対象者の５％の家庭で月８万円以上保育料を払っているという実態があります。そういった現状に対して、品川区としてはどのように認識をされているのかお聞きしたいと思います。","respondent":"金子保育課長","answer":"大方の場合は月曜日から金曜日までの中で保育料を定めてきているというのが認証保育所の多数だというふうに考えております。私ども何回もご説明申し上げてはおりますが、所得の低い階層には十分な配慮をしているものというふうに考えているところです。","id":"exchange-057"},{"speaker":"三村委員","kind":"質問","question":"認可保育園については応能負担ということがあるんですけれども、先ほどの認証保育園ですと応能負担の仕組みがないといったこと。子育て支援として考えていただければと思うんですけれども、お考えをお聞きしたいと思います。","respondent":"金子保育課長","answer":"私ども認証保育所に関しましては、いろいろな経営主体が経営できるような形で、新しい取り組みとして動かしているものだというふうに思っています。認可保育所の応能負担という部分について、現在のところは維持していこうというふうに考えているところです。","id":"exchange-058"},{"speaker":"三村委員","kind":"意見","question":"細切れの預かり保育と１日のスケジュールに沿った、そういった時間帯のみの受け入れとか、そういったことが出てくるかと思うんです。そういったところの調整等は、どういうふうにお考えなのかお聞かせ願いたいと思いますとの意見を述べました。","respondent":"金子保育課長","answer":"私ども今回初めてこの制度を実施しようかと考えておりますが、１時間単位ですから、どの時間帯に来られるかによって活動の内容も違ってきます。０歳児ですと、また個別的に対応することも含めて考えていきたいというふうに、今現在考えているところです。","id":"exchange-059"},{"speaker":"三村委員","kind":"質問","question":"ファミリーサポートの研修について、今まで何人の方が受講されましたでしょうか。現在の提供会員と利用会員の数を教えていただけますか尋ねました。","respondent":"辻田児童課長","answer":"ファミリーサポートは、現在まで９回の養成講座を実施しております。ただ、両方の会員になっている方も、それぞれの中にカウントされているという状況です。","id":"exchange-060"},{"speaker":"三村委員","kind":"質問","question":"受講者の中で提供会員になっていない方はどの程度いらっしゃるのでしょうか、またその理由についてどのように分析されているのでしょうか、お答えをお願いいたします。","respondent":"辻田児童課長","answer":"自分ではなかなかできないというようなこともありますでしょうし、それから家庭状況の中で不十分であるというようなこともあると思います。それから、養成講座自体を、子育て講座というような考え方で受講されている方もいるのではないかなという具合に考えております。","id":"exchange-061"},{"speaker":"三村委員","kind":"質問","question":"先日の一般質問におきまして、子育て支援センターは区内に平塚と西五反田にありますけれども、大井地区にはございません。異世代交流の場となるような施設、多様な区民の意見を反映させるような形の施設の検討をお願いしたいと思いますけれども、お考えをお願いいたします。","respondent":"辻田児童課長","answer":"そういう意味では、家庭あんしんセンター等を使って、提供会員の方々の活動を少しずつ実施していただくような形を今後考えてまいりたいと思います。品川区内の中には２５カ所の児童センターがありますので、さらに拡大していくということが必要かなという具合に考えております。","id":"exchange-062"},{"speaker":"三村委員","kind":"質問","question":"児童センターについてお伺いをしていきたいんですけれども、子どもたちの放課後の居場所としてきた児童センターの役割を今後どのように考えられていくのか、今後の方向性についてお伺いしていきたいと思います。","respondent":"辻田児童課長","answer":"児童センターの役割、次世代育成支援というものを考えた、私どもは平成１４年１０月から児童センターのあり方検討委員会等も実施しています。決してこれを少なくするとか、なくしていくというようなことではございませんので、ご理解をいただきたいと思います。","id":"exchange-063"},{"speaker":"三村委員","kind":"意見","question":"減らしていくということではないということで安心するんですけれども、今までの児童センターとしては小学生対象の事業がとても多かったかと思います。小学生対象の事業について、今後どのようにされていくのか、お考えのほうをお願いいたしますとの意見を述べました。","respondent":"辻田児童課長","answer":"そういうところと連携して、児童センターで何ができるかという形で、今後具体的な事業を考えていかなければならないという具合に考えております。","id":"exchange-064"},{"speaker":"三村委員","kind":"意見","question":"ちょっと時間がないので、中高生になってから突然来館し活発に活動することは考えがたいことから、小学校から児童センターに足を……。〔時間切れにより答弁なし〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"菊地委員","kind":"質問・要望","question":"自立支援センター、どういう方向で指導されるのかというのを、もう少し具体的に教えていただきたいというふうに思います。大田寮ができたのが平成１３年頃でしょうか、１５年は途中ですけれども、この辺がわかりましたら教えてほしいと求めました。","respondent":"黒田生活福祉課長","answer":"本当に自立のために何をしたいかという、ご本人の意向に沿いながら、こちらができることにこたえていくというのが今の路上生活者の対応です。","id":"exchange-066"},{"speaker":"菊地委員","kind":"質問","question":"ですから、こういう皆さんが実際に品川の窓口に来たときに、どんな対応をされるのかというのを具体的な事例でお聞きしたいんですけれども。都営住宅の入居は困難でしょうか、これが区に相談に来たときには、どんな対応をされるのかというのを説明するよう求めました。","respondent":"黒田生活福祉課長","answer":"ＩＴ関連で、どうしても家賃滞納をして出ざるを得ないとなると、やはり路上生活という対応ではないとは思います。その中で、どのような仕事ができるかというのを探っていただくというのが基本かと存じます。","id":"exchange-067"},{"speaker":"菊地委員","kind":"質問","question":"お話ししたのは路上生活になる前の話ですから、こういう視点に立つことが、まず必要なんじゃないかというふうに思うんです。どうして品川区の見解と他の地方自治体の実際が違うのか、これがよくわからないんですけれども、この辺をお答えをいただくよう求めました。","respondent":"黒田生活福祉課長","answer":"私もよくわかりませんが、やはり生活保護というのは基本がありますので、その基本にのっとってこちらは対応しています。だれが見ても、この方には生活保護が必要だという方に関しては、こちらのほうも対応しています。","id":"exchange-068"},{"speaker":"菊地委員","kind":"質問","question":"ですから、実際に路上生活者になる前にどうするか、絶対にこれはなくならない問題であるというふうに思います。品川区ではこういうことも行わないんでしょうかね、この辺もちょっと説明を求めました。","respondent":"黒田生活福祉課長","answer":"働けないんだったら、働けないという証明を出していただくしかないです。離職者支援の貸し付けですが、これは社会福祉協議会でやってありますので、当然相談窓口ではご紹介しています。","id":"exchange-069"},{"speaker":"菊地委員","kind":"質問・要望","question":"少なくとも品川区として区民を路上生活者にはしない、こういう姿勢がまず何よりも求められるものだと思います。若者でさえ仕事がない時代ですので、ぜひとも必要な支援を思い切って広げていただきたいなというふうにお願いをして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"須藤委員","kind":"質問・要望","question":"障害者のほうが７６３万円ですか、障害者のほうの構築するというのがかなり数字的には上がって、両方書いてあるのに数字的にちょっと少ないのと。そのあたりで、それから今後のその辺とのコントロールがどうなっているのか教えてほしいと求めました。","respondent":"高橋介護保険担当課長、日下部障害者福祉課長、辻田児童課長、金子保育課長、山岡保健高齢事業部副参事、早津高齢福祉課長","answer":"本格的実施ですが、やはり介護保険が始まって３年間どうであったかということの検証の中では、３年間いろいろ検討してまいりました。まず実施して… それから、措置制度時代におきましては生活支援ということで、非常に保護的な色彩が強かったんですが、支援費制度に移行しました。そういった意味で… 国の制度で実施しておりまして、家庭生活における生活の安定と次世代社会を担う児童の健全育成ということを目的に実施しております。… ぷりすくーる西五反田の理念です。","id":"exchange-071"},{"speaker":"須藤委員","kind":"提案","question":"長期基本計画でこうなっているよというのはわかるけれども、説明してくるときに、今、事業部制を敷いていろいろやってきて提案してくる。いわゆる新しい障害を分類して、２００１年にＷＨＯが国際生活機能分類というのをされていますけれども、そのあたりをご存じだったら説明を求めました。","respondent":"日下部障害者福祉課長、田中健康課長","answer":"確かにＷＨＯで障害についての具体的な定義が規定されておりまして、それがベースになって障害者の施策について、日本の一つの基準に沿ってサービスの体系化がされているということで承知しております。保健所等で精神保健の分野を持っていたわけですけれども、平成１４年度からは精神福祉という形で区市町村の義務ということになってあります。","id":"exchange-072"},{"speaker":"本間委員","kind":"質問","question":"それから最後に１９５ページは高齢者生きがいづくり事業、いきいきカラオケ広場等についてお尋ねしたいと思います。品川介護福祉専門学校は、最近は人数が少ない形での卒業生になっているようですけれども、平成７年以降今日までの卒業生の総数をお尋ねします。","respondent":"早津高齢福祉課長、山岡保健高齢事業部副参事","answer":"したがいまして、年間の授業料が６０万円ですので、２年間で１２０万円の授業料相当分を貸し付けるというものです。この奨学金については、区内の社会福祉法人等に就職した場合については… ４１人、昨年が３０人と、これは退学の方あるいは休学の方が出た関係で少なくなっております。今年は４１人の予定をしています。","id":"exchange-073"},{"speaker":"本間委員","kind":"質問","question":"その件で、そのことに満たない形の返還をされていないような人がいるのかどうかというのと、それから３年以降の品川区における定着の度合い。ざっとでいいです。","respondent":"早津高齢福祉課長、山岡保健高齢事業部副参事","answer":"３年で免除になったからやめるというのは、私どものほうにはほとんど耳に届いておりません。逆に就職をした後も、この制度を活用して免除まで行き、その後、中堅職員として働いているという人間は数多くいるというような実態です。ただ、今の答弁にもありましたように、３年経ってすぐにやめるということではなくて、３年経つとかなりそこの職場の中堅になってあります。","id":"exchange-074"},{"speaker":"本間委員","kind":"質問・要望","question":"シルバー人材センター支援事業の件ですが、合わせまして新就業システム推進事業の２点についてお尋ねします。新就業システムにつきましては、５５歳以上から６４歳までという中身ですけれども、その着実に成果が上がっている中身についてお伝えいただくよう求めました。","respondent":"蓼沼高齢事業課長","answer":"９月に完全オープンしたということで、現役とは異なる多様な高齢期の働き方を実現するということで実施してまいりました。実績につきましては、昨年度７１件マッチングがございましたけれども、今年度につきましても昨年実績を上回るような状況で推移をしています。","id":"exchange-075"},{"speaker":"本間委員","kind":"意見","question":"時間がありませんので、次に移りたいと思います。お酒を飲まない、お金をかけない等々の三原則でやっておりますが、この件について時間がありませんのでメリットだけ一言との意見を述べました。","respondent":"蓼沼高齢事業課長","answer":"ご指摘のとおりです。健康増進、生きがいづくり、仲間づくりということで、今、事業を進めているところです。","id":"exchange-076"},{"speaker":"若林委員","kind":"意見","question":"２０１ページの障害を持った方へのさまざまな社会参加支援、この中に下のほうになりますか緊急通報システムというのがあります。中身をお示しくださいとの意見を述べました。","respondent":"日下部障害者福祉課長","answer":"高齢者の緊急通報システムについてご質疑をいただいた経緯がありますけれども、基本的にはその内容と同じです。それからもう一つは民間の事業者に委託した形での通報システムということで、いずれかの選択という形で事業を実施しています。","id":"exchange-077"},{"speaker":"若林委員","kind":"質問","question":"単価という言い方があたっているのかどうかわかりませんが、１人当たりどのぐらいお金がかかるのか、今あえて聞きませんけれども。これが１通何円という非常に安価なツールでございまして、携帯電話の助成の考え方とかあればお答え願えますか尋ねました。","respondent":"日下部障害者福祉課長","answer":"私どもはそれを基本にして、聴覚障害者の方にも災害時の安全性を高めていただくということで、区のほうとしてもいろいろなご案内をしています。それが基本でございまして、現在のところ具体的な助成等の措置については考えてございません。","id":"exchange-078"},{"speaker":"若林委員","kind":"質問","question":"続きまして、痴呆性高齢者グループホーム、合わせて知的障害者入所更正施設、この２点を並行してご質問します。どのような厚生労働省に対して納得をしていただいたのか、どういう言い方をして厚生労働省を「うん」と言わせたのか、この辺の考え方を。","respondent":"早津高齢福祉課長、日下部障害者福祉課長","answer":"こうした中で、痴呆介護というものを今後真剣に考える必要があるのではないかというふうに言われております。痴呆性高齢者の増加を背景に、痴呆性高齢者のためのグループホーム整備が現時点では必要であろうという、こういう考え方です。国のほうとしましては、新たな施設建設についての補助を打ち切ることを打ち出したのはごく最近でございまして、平成１６年度からは廃止をすると。","id":"exchange-079"},{"speaker":"若林委員","kind":"意見","question":"いわゆる地域で自立を、ノーマライゼーションに向かっての支援をしていくということが、第一のポイントになっていると私は思っています。２０年なのか、最低１年ぐらいで、この辺の組み立て方をお教え願いますとの意見を述べました。","respondent":"早津高齢福祉課長、日下部障害者福祉課長","answer":"私の先ほどの説明が二つの施設の違いをはっきりとさせるために、それぞれの特別養護老人ホームの中ではさまざまな工夫をしております。七、八割の方は入所者の中で痴呆症状は見られると、こういうような事実はあります。 そういうものが必要ですので、今、私どもの障害者福祉課と受託先の福栄会でいろいろ検討チームをつくって検討しています。その中で具体的な詰めを行っていくです。","id":"exchange-080"},{"speaker":"若林委員","kind":"質問・要望","question":"その人が大工さんというんでしょうか、独自に創造して、トイレ一つにしてもすごく思いのこもるものをつくっておられました。ぜひ、。","respondent":"早津高齢福祉課長","answer":"そういったことで差はあるんですが、都内ですと大体のところ１カ月十七、八万円ぐらいの自己負担ということになります。介護報酬の１割負担も含めて、大体そのぐらいの費用ではないかというふうに言われているところです。","id":"exchange-081"},{"speaker":"若林委員","kind":"質問・要望","question":"そこを何とかもう少し低くという、これからそういうご要望も多々来ると思いますので、また最大限のご努力をお願いしたいなと思います。サービスが上がったのか、保ったのか、その辺の考え方をお願いいたします。","respondent":"辻田児童課長","answer":"それから、１,２９１件の部分が平成１５年度１月現在での数です。この中では、言語、理学、作業療法等を実施しているということで、きちっと引き継いで実施してきているという状況です。","id":"exchange-082"},{"speaker":"若林委員","kind":"質問","question":"家庭あんしんセンターの中には、なかなかそういうサービスが受けられないんだという、そういう保護者の方の声がありました。この辺はいかがか尋ねました。","respondent":"辻田児童課長","answer":"私どものほうは、家庭あんしんセンターに移しまして、療育指導等もきちっとやっているです。決して前のところで受けられた方が、私どものほうは聞いていないんですけれども、きちっとその辺はやられているという具合に把握しております。","id":"exchange-083"},{"speaker":"若林委員","kind":"意見","question":"具体的に大井倉田の子育て相談センターのときはどのような頻度でやっていのか、現在の家庭あんしんセンターではどういう頻度でやっておられるのかお教え願いますとの意見を述べました。","respondent":"辻田児童課長","answer":"平成１３年度の実績等がここにありませんので、平成１４年度でいきますと、合わせて子育て支援センターが９月から始めております。それと比べますと、今回１,２９１件ということで少し少なくなっているという状況です。","id":"exchange-084"},{"speaker":"若林委員","kind":"確認","question":"それを一つご確認を願います。この辺、もう１回ご説明を願いますか尋ねました。","respondent":"辻田児童課長","answer":"平成１５年度は１月段階で１,２９１件、１,３００件弱ですので、２月、３月の中では約１,５００件ちょっとという数になってまいります。場所的な変更があって、その辺につきましては、その数に多少反映されているのではないかなという具合に考えております。","id":"exchange-085"},{"speaker":"西本委員","kind":"質問・要望","question":"それから２０９ページの認証保育所関係、それから３点目には２１３ページから２１５ページにかけました保育園運営費について質問をします。借りているというところがありますので、その辺の大きな方向性としては、どういう形になるのか教えてほしいと求めました。","respondent":"辻田児童課長","answer":"ただ予想としましては、この中の約６から７ぐらいの学童保育クラブにつきましては、休止状態にしなければならないかなという具合に考えております。","id":"exchange-086"},{"speaker":"西本委員","kind":"質問・要望","question":"いずれ２年後には学童保育クラブが空くという状況になりますので、いろいろな使い方、あり方ということを検討されていると思うんです。もっと広い意味で、児童センターがこれからどういう方向で、位置づけとして発展していくのだろうかというところをお答えほしいと求めました。","respondent":"辻田児童課長","answer":"児童センターの新たな方向性ですけれども、これは平成１４年１０月から児童センターのあり方検討委員会で検討してまいりました。地域との連携というのが必要になってまいりますので、今後、児童センター自体の運営も今後考えていかなければならないという具合に考えております。","id":"exchange-087"},{"speaker":"西本委員","kind":"質問・要望","question":"児童センターの今後のあり方の中で非常に大切だなと思っている点は、地域の中でどういう位置づけになっていくのかというところにあると思うんです。そこはこの１年間、２年間、その辺はいかがか尋ねました。","respondent":"辻田児童課長","answer":"そのためには、今ある１３ブロックの地域センターや何かとの連携を今後強くしていくというようなことも含めて、具体的な取り組みを今検討しています。お手伝いをしていくというようなことを、今、具体的にどうするかということで検討しています。","id":"exchange-088"},{"speaker":"西本委員","kind":"質問","question":"ぜひ、具体的な行動、提起をお願いしたいと思います。その違いによって、実際に運営する側の影響、もしくはメリットはいかがなものか、その辺を説明するよう求めました。","respondent":"金子保育課長","answer":"ただ、もう少し前になりますと、そういった１人当たりの単価で掛けるわけではなくて、さまざまな項目ですね。認可外の保育施設が４月から定員どおり埋まっているかというと、充足率も従来の数から算出していきますと、私どもの試算結果でございました。","id":"exchange-089"},{"speaker":"西本委員","kind":"質問・要望","question":"要望がいろいろ出てくると思うんですが、もう一つ保育料を上げていくという一つの方法ですね、そういうのでも使われるという見方もあります。ですから、認可に入れなかった人に対する助成というのは、何か考えることはありませんか尋ねました。","respondent":"金子保育課長","answer":"例えば私どもよく聞くんですけれども、１歳児の頃から英語をやるとか、その意味ではさまざまな選択があり得るのかなと考えています。現在のところ、私どもとしては認可保育園と同じような助成の方法というのは、認証保育所に関しては考えてございません。","id":"exchange-090"},{"speaker":"西本委員","kind":"意見","question":"認可保育園に入りたいという形への希望を、なるべく取っていただけるような施策の展開をお願いしたいところです。いろいろ見ますと保険の業務委託とか、これはどういう考えのもとで、実態はどういうふうになっているのかお答え願いたいと思いますとの意見を述べました。","respondent":"金子保育課長","answer":"もう一方、これは私どもは過去０歳児園に看護師を配置しておりましたが、看護師については現在事実上退職後新たに採用してございません。この部分について看護師の仕事をお願いするということで、この保険業務委託を昨年度から始めてあります。","id":"exchange-091"},{"speaker":"西本委員","kind":"意見","question":"影響のないように、民間活力をともに考えて保育園運営をよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"石田委員","kind":"質問・要望","question":"８時半から１０時の部分が平成１６年度９園ということになると考えていますが、それと今後の考え方を教えていただきたい。現実的には今やっているところは何人ぐらいまでは受け入れられるとお考えになっていらっしゃるか、その辺のところを教えてほしいと求めました。","respondent":"金子保育課長","answer":"委員ご指摘のとおり、平成１６年度は９園目の１０時までの園を開設する予定にしております。今後についてはこれからの推移を見ながら考えていくつもりではありますが、基本的には拡大する方針は持ってございません。","id":"exchange-093"},{"speaker":"石田委員","kind":"質問・要望","question":"先に進んだ話までいただいたような気がしますが、そうなってくると現実問題、今何人ぐらい８時半から１０時を使っているかというところの平均値を教えていただきたいのと、一つの園でどれぐらいまで受け入れられる体制があるのか教えていただきたい。","respondent":"金子保育課長","answer":"１０時まで開設している園で８時半以降の子どもは、１園当たり平均で４.１人というデータになっております。必要な方の区民のニーズにはこたえるという形で実施しているものですので、人数に応じて職員を配置していくというふうに考えているところです。","id":"exchange-094"},{"speaker":"石田委員","kind":"質問","question":"ただ、今お伺いすると４.１人の平均だということであれば、よく品川区の中で。８人ぐらいのところだったら、それでまとめてどうしてもニーズのある方はそこへ行ってくださいと、その考え方について説明を求めました。","respondent":"金子保育課長","answer":"あくまでもこの事業そのものがベストだというふうに考えているわけではないですが、つまり二重保育、三重保育をする。委員のご指摘、そういった私どものスタートの精神も含めて考えて、今後検討する余地があれば検討していきたいというふうには考えております。","id":"exchange-095"},{"speaker":"石田委員","kind":"質問・要望","question":"その方たちのニーズをしっかりとらえれば、この方はどうしても１０時だとかわかるわけですよね。その方たちに、待機者の人がもっと多く保育園に入っていけるということもあるわけで、その辺の点はもう一度ご答弁をいただきたい。","respondent":"金子保育課長","answer":"あらゆる点から考えて、現在は確かに１０時園を９園まで拡大してきたという経過がありますが、今後はこういったメニューを再編成していく。利用者の利用度というのはどう変化していくか、こういったことも検証しながら考えていきたいというふうに考えております。","id":"exchange-096"},{"speaker":"石田委員","kind":"意見","question":"先ほどの保育園で全体で９.４％の負担というのがありましたが、受益者の考えで１日２,０００円だということであります。そういう方から受益者負担を考えれば、これで年間８,０２２万円かかるとなると、１人当たり１７０万円ぐらいかかる計算になるわけですとの意見を述べました。","respondent":"金子保育課長","answer":"この辺は今後検討する余地があるのかなというふうには、私は考えておりますが、全体的な費用としての二千何がしという費用ですね。年間の費用としては委託費として支払うのは６６８万円余ということで考えておりますので、その辺はご理解をいただければと考えています。","id":"exchange-097"},{"speaker":"川西委員","kind":"質問・要望","question":"それからこれは介護保険に入るんでしょうか、それから児童センターのこれからの再構築について１点だけ、要望も含めて。平成１６年度の予算の中のケア事業の検討、その他の中でどういうふうにお考えか、最初に伺いたいと思います。","respondent":"早津高齢福祉課長","answer":"痴呆の原因としてのアルツハイマーにかかっていらっしゃる方のケアというのは、委員ご指摘のとおり大変難しいというふうに私どもも考えてあります。","id":"exchange-098"},{"speaker":"川西委員","kind":"質問","question":"後ほど住宅扶助の費用のことで伺えばそうなんですけれども、この金額と、先ほどから出ています年金ですね。やはり全然考えないというわけにはいかないと思いますが、平成１６年度予算の中で方向の検討ぐらいはされていくんでしょうか、伺います。","respondent":"蓼沼高齢事業課長","answer":"高齢者住宅についてのお尋ねですけれども、２２０戸のストックを抱えてございまして、区としては一定程度の水準にあるというふうに考えてあります。民間との連携、当面はそことのマッチングといいますか、あっせんでニーズを吸収していきたいというふうに考えてあります。","id":"exchange-099"},{"speaker":"川西委員","kind":"質問・要望","question":"年金で暮らしている方は、何％ぐらいの人がそういうものを求めているかというのを、ぜひ調査をしていただきたいというふうに思います。次に、非常勤徴収員のことですけれども、この徴収員の方々を予算化しまして、どのぐらいの収納率を見込んでいらっしゃるのか伺います。","respondent":"太田保険年金課長","answer":"介護保険の部分ですけれども、予算に見合った上限ということでは、滞納繰越分で換算いたしますと約２名で７％ということで換算をしています。","id":"exchange-100"},{"speaker":"川西委員","kind":"質問・要望","question":"ぜひ、介護保険の理解を求めて、徴収に努力していただきたいと、これはお願いで結構です。産休等の代替職員の単価より人材派遣は少々高めだというふうに認識しておりますが、それでも人材派遣がよいのかどうか、この辺について伺います。","respondent":"金子保育課長","answer":"一般的なアルバイトとして考えた賃金、産休雇上の場合のアルバイトとして考えた賃金と、資格と経験を問うております。その辺が違ってくるがために単価も違ってくるというふうなことでご理解いただきたいと思います。","id":"exchange-101"},{"speaker":"川西委員","kind":"質問・要望","question":"あるいはアルバイトとしての要望が区民の保育士有資格者の中にないのかどうかの分析もしながら、こういう制度の活用をお願いしたいと思います。この休館日の開設を考えていただけるかどうか、この辺について伺います。","respondent":"辻田児童課長","answer":"児童センターあり方検討委員会の中でも、その点につきましては検討しておりまして、今後考えてまいりたいというふうに考えております。","id":"exchange-102"},{"speaker":"沢田委員","kind":"質問・要望","question":"２１３ページの保育園運営費に関連して、子育て支援の問題と保育料値上げ問題を中心に聞かせてほしいと求めました。予算のトップにこれを据えた理由は何なんでしょうか、説明願いたいと思います。","respondent":"榎本行財政改革担当課長","answer":"去年の次世代育成支援対策推進法ができた段階で、国を挙げての子育て支援をどういうふうに進めていくかということを早急にやらないと。その中で品川区として平成１６年度の３本柱の一つとして子育て支援を挙げまして。","id":"exchange-103"},{"speaker":"沢田委員","kind":"質問","question":"立派なことだというふうに思います。これは何が目的でやったんか尋ねました。","respondent":"辻田児童課長","answer":"強力な次世代支援の具体的な形として、この事業を立ち上げました。そういう意味で経済的支援というような、私どものほうは６年生という部分まで引き延ばして区の独自性を出したものです。","id":"exchange-104"},{"speaker":"沢田委員","kind":"質問","question":"保育料の値上げについては受益者負担が出てくるけれども、医療費無料化のところになると、子育ての楽しさが実感できるものに。ここの場では、受益者負担の原則はどうなっているんか尋ねました。","respondent":"辻田児童課長","answer":"私どものほうは経済的支援を与える場合、福祉的側面がありますので、いわゆる適正な形での負担というのをお願いしております。少なくとも福祉を今後継続していくためには、今後長く継続できないという具合に考えております。","id":"exchange-105"},{"speaker":"沢田委員","kind":"質問","question":"ですから、この立場がなければ、先ほどの医療費の無料制という根拠が出てこない。区、それから保護者の負担、どんな関係になっているのかちょっと説明願いたいんです。","respondent":"金子保育課長","answer":"制度がただいま変更の過程にあるというのは委員も承知していらっしゃるとは思いますが、簡単に言いますと家計に与える影響を考慮して保育の実施にかかる児童の年齢等に応じて定める額を徴収することができると、これに基づいて私どもは保育料をいただいているものです。","id":"exchange-106"},{"speaker":"沢田委員","kind":"意見","question":"そして保育料として取るべき２０％は１７億４,０００万円、区が同じく４億２,９００万円、国の決めた最低基準の中で半分は保育料として取りなさい。その辺の考え方をお尋ねしたいと思いますとの意見を述べました。","respondent":"金子保育課長","answer":"今、品川区として独自に判断して、委員ご指摘のとおり５２億５,６００万円余というのを運営費として支出しているものです。当然のことながら、さまざまな特別保育事業もここに入りながら、保育のサービスメニューを充実してきているというふうな現実があります。","id":"exchange-107"},{"speaker":"沢田委員","kind":"意見","question":"ところが、国はどうかといいますと、１９８４年までは全体にかかった運営費、措置費の８０％は国が負担していたんです。保育園運営費の国庫負担を削るなんていうのは、とんでない話だと私は思うんですけれども、その辺の基本姿勢についてお答え願いたいと思いますとの意見を述べました。","respondent":"金子保育課長","answer":"それは、私どもの特別区長会のほうで実施しているものです。何回も申しますが、これはあまりにも低い割合ではないかというふうに考えて、今回の改定の提案を申し上げたところです。","id":"exchange-108"},{"speaker":"沢田委員","kind":"質問","question":"国だってぜひやってほしい、援助してほしいということを要求するのは、私は話にならないというふうに思います。５６条の第３項、家計の影響を考慮すべきことが書いてあるんだけれども、その辺をもう少し説明してもらえないか尋ねました。","respondent":"金子保育課長","answer":"児童福祉法の第５６条３項は、これらの者から徴収した場合における家計に与える影響を考慮して保育の実施にかかる児童の年齢等に応じて定める額を徴収することができる」と、このような規定になってあります。","id":"exchange-109"},{"speaker":"沢田委員","kind":"質問","question":"マンションだとかは大体子育てを１人、２人やれば、２ＤＫ、３ＤＫ借りれば１３万円、１５万円というお金がかかっちゃう。これはたびたび代表質問でも私言いましたけれども、少子化に対する区民調査の中で実施してほしい施策、それはどれぐらいになっていますか。","respondent":"金子保育課長","answer":"Ｃ階層についても、私どもとしましては所得の階層に応じて、十分配慮した引き上げの内容になっているというふうに考えているところです。第１子選択の問題ではないですが、住居の問題等々のところが、非常に大きな悩みや問題として出されているところだというふうに考えます。","id":"exchange-110"},{"speaker":"沢田委員","kind":"質問","question":"そこに今度は保育料をこんなに上げようとするんですから、家計の調査をするといったけれども何を調査したのか、大変これは首を傾げるところです。だけど、来年、再来年は決めたのか決めていないのか、そこをちょっとお答え願いたいと思います。","respondent":"金子保育課長","answer":"私ども平成１６年第１回定例会にご提案申し上げているのは、あくまでも平均９％の引き上げということでご提案申し上げ、ご判断をお願いしています。","id":"exchange-111"},{"speaker":"沢田委員","kind":"質問","question":"時間がないので、私の質問に答えてほしいんですよ。政策目標だということは、意思決定していないということか尋ねました。","respondent":"小沼福祉事業部長","answer":"これも再三申し上げますけれども、０歳児で上げた後が６万２,８００円、これに対しまして受ける対価というのは換算しますと５３万５,０００円。１万円払って８万５,０００円のものが出てくると、こういうこともご賢察の上、私どものことをご理解いただければと思います。","id":"exchange-112"},{"speaker":"沢田委員","kind":"意見","question":"Ｄ１０階層で６０万円、それも含めて約７０万円近い年間の負担になりますし、それがまた全体に還元される。働くことは、非常に大きな意味を持っているということを言いたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"},{"speaker":"木下委員","kind":"質問","question":"第１に、民生委員経費のことについてお聞きしたいと思うんです。そこで、民生委員の現状についてお聞きしたいと思うんですけれども、大体平均年齢はおいくつなんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"具体的な条件としましては６５歳未満、ただ再任ということになりますと７３歳未満ということで、若干緩やかになってまいります。それから、平均の在職期間ですけれども、民生委員につきましては大体２.７期ですから、１期が３年ということで約８年ということになってあります。","id":"exchange-114"},{"speaker":"木下委員","kind":"質問","question":"それに加えて民生委員といいますと高齢者相談員ですとか、児童委員ですとか、民生委員の仕事プラスほかの仕事も横並びでやっていかなきゃならない。高齢者相談員ですけれども、これは高齢者の方を大体何人ぐらいを担当されていらっしゃるんか尋ねました。","respondent":"早津高齢福祉課長","answer":"対象としては、主にひとり暮らしの高齢者並びに高齢者世帯が該当ということになります。世帯数で申しますと、９,６００世帯ぐらいというのが対象件数になろうかと思います。","id":"exchange-115"},{"speaker":"木下委員","kind":"質問・要望","question":"ですからこそ「やめたい」という民生委員の声が私ども議員のところに届いてくるというのが現状ですので、もう決まっちゃったことで変えられないのか。変えられるんだったら、もっと多くの増員で１人当たりの負担を減らすという考え方についてはいかがか尋ねました。","respondent":"日下部障害者福祉課長","answer":"今後とも機会をとらえまして、定数増については一生懸命取り組んでまいりたいと、それが１点です。例えば、「これからも積極的に取り組んでいきたい」という回答をいただいた方が約半数、今後頑張っていきたいというふうに思っております。","id":"exchange-116"},{"speaker":"木下委員","kind":"質問・要望","question":"民生委員法第４条で、市町村長の意見を聞いてこれを定めるとなっているわけですから、要望として都に対して強く働きかけをお願いしたいと思います。品川区内は今まで指定取り消し処分を受けた事業者があるのかどうなのか、お教え願いますか尋ねました。","respondent":"早津高齢福祉課長","answer":"したがいまして、サービスも虚偽のものをすると、それは結果的に一致しますので通ってしまって不正受給が起こるというようなことになっております。ケアプランを作成するのが在宅介護支援センターという、サービス事業者とは独立した組織ということで、構造的にいいますと。","id":"exchange-117"},{"speaker":"木下委員","kind":"質問","question":"品川区としては不正がないというふうにお聞きしましたので、これからもそういうのをきちっと監視していただきたく、お願いしまして終わらします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"田中委員","kind":"質問・要望","question":"私は２０９ページ、十分な時間があれば １９９ページの高齢者医療関係事業に関連して質問をしたいと思います。この背景としては住宅施策、０歳から９歳児が増えたことで少子化対策の観点からすると、その辺も含めましてお考えをお聞かせほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"実際には、１０歳から１４歳の部分というのは、そこの部分がいかに歯止めがかけられるかというような観点もあります。今回の乳幼児医療費につきましても１２歳まで広げるという部分、長く品川区に子育て世代がいられるような形にもっていくという考えです。","id":"exchange-119"},{"speaker":"田中委員","kind":"質問・要望","question":"その分、さらなる学力の定着を行っていただきたいと思っているんですが、そして行く行くは少子化対策につながる。手当があるなしという観点だけではなくて、総合的な視点から施策を遂行すべきだと思っているんですが、お聞かせをほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"まさに、これからの課題である次世代育成支援の行動計画の中で、自治体に与えられた課題だというふうに考えております。それから雇い主である自治体、次世代育成をするために役立つのかというものを、十分検討して進めてまいりたいというふうに考えております。","id":"exchange-120"},{"speaker":"田中委員","kind":"質問・要望","question":"徐々に成長していくにあたって病院にかかる率は低下しているという中で、なぜ今回小学校６年生まで広げたのか。そういうことに対して経済的支援をするんだということでございましたが、さらなる強いポリシー、理念をお聞かせほしいと求めました。","respondent":"辻田児童課長","answer":"そういう中で、さらに私どものほうは、品川区として特色のある事業を打ち出すということを考えて、小学校６年生まで延ばします。そういう中で、私どものほうとしてはそこの部分で小学校６年生まで手厚くしていくということは、私どものほうは今回６年生まで延ばしたわけです。","id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"平成１６年の小学生の受診者の予想として１万６５２人というふうに予算書に書かれておりますが、その点をどう予測されているのかということ。この医療費が下がる分、また浮いた分をどういったものに回してもらいたいと期待をされているのか、その辺の考え方をお聞かせほしいと求めました。","respondent":"辻田児童課長","answer":"どのぐらいの流入があるかということは、２３区市部も含めて初めての試みなので、なかなかその予測はできないところがあります。今後、来年の１月から実施するわけですけれども、その状況をつぶさに私どもは見ていきたいという具合に考えております。","id":"exchange-122"},{"speaker":"田中委員","kind":"質問・要望","question":"人口がどういう形で増減があるのか、定着がどうあるのか、今回の補助金のあり方の検証を引き続きしていただきたい。所得制限も含めて、検証してほしいと求めましたが、今後の姿勢をお聞かせほしいと求めました。","respondent":"高橋区長","answer":"そういうような観点から、教育費の削減が少しでもあるようにというふうなことで、すまいるスクールを各学校全部でやるような予定にしているわけです。そういうことを考えまして、これからもこの問題に対してより努力をしていく所存です。","id":"exchange-123"},{"speaker":"山路委員","kind":"質問・要望","question":"これを一緒に合わせてもっと何かできないかなということも考えるんですけれども、それが１点。今年の１月１５日に臨海斎場がオープンしまして、その葬祭用品というんですか、その辺についての現在の状況を聞かせてほしいと求めました。","respondent":"中川原福祉事業部副参事、日下部障害者福祉課長","answer":"だんだん売り上げが落ちてまいりまして、とうとう３２０万円という、開設当時の半分に落ち込みました。そして、自分たちで売って生活費を稼ぐという、作業訓練の域を出まして… おかげさまでいろいろ関係各方面のご理解、それからご支援をいただきまして、昨年の１２月から福祉工場の製陶工場が竣工し、本格稼働いたしました。","id":"exchange-124"},{"speaker":"山路委員","kind":"質問・要望","question":"授産施設の品物を売ることも、ここは可能であると。こういう相談があったんですけれども、何かいいアドバイスがあったら教えてほしいと求めました。","respondent":"中川原福祉事業部副参事","answer":"そして今年補正で２,０００万円の寄附をいただいたりとか、ある部分を寄せ合って、こういうのを使ってほしいというお話が寄せられます。双発的な活動の仕事をさせていただきたいということで考えてありますので、どうぞそういうお話をお寄せいただきたいと考えています。","id":"exchange-125"},{"speaker":"山路委員","kind":"質問・要望","question":"産業振興課も係わるかなと思ったんですが、強いて障害福祉者課長が障害者の立場でということでしたので、ここで相談をさせていただきました。非常に厳しい道かと思うんですが、ＩＴのソフト開発の道まで何とか頑張ってほしいと求めましたが、その後の検討はどうか尋ねました。","respondent":"日下部障害者福祉課長","answer":"検討の俎上には上っておりましたけれども、失敗は許されないということもありますので、こちらに全力を傾注してきた経緯があります。その辺で一定の目処が立った段階でＩＴの開発等についても検討を進めていきたいと、このように考えております。","id":"exchange-126"},{"speaker":"山路委員","kind":"質問","question":"どうぞよろしくお願いいたします。何件ぐらい相談があって、成立したといいますか、そういうのは幾つぐらいあるか聞かせていただきますか尋ねました。","respondent":"中川原福祉事業部副参事","answer":"相談件数ですが、現在、月平均１６５件ほどの電話、来所相談があります。そのうち、いろいろ高齢福祉課に相談しまして後見に結びついたのが、今申立て決定したのが１４件で、申立て済みが９件です。","id":"exchange-127"},{"speaker":"山路委員","kind":"質問","question":"法的問題が非常に難しい面もあると思いますが、相談者がこれから増えると思いますので、どうぞ対応のほう、今後よろしくお願い申し上げます。平成１６年のプレス発表にも載っておりますが、これから課題になってくるんじゃないかと思いますが、その辺についてはどのようにお考えか尋ねました。","respondent":"早津高齢福祉課長","answer":"どちらも身近なところでリハビリを続けられるということで、まさに会場の適地を探しています。２カ所につきましては新年度に入ってから、適地等について検討を進めていきたいというふうに考えてあります。","id":"exchange-128"},{"speaker":"山路委員","kind":"質問・要望","question":"今、決まっているのは承知しているわけですが、きめ細かにもっともっと会場を増やして、地域の中でできるような体制を要望しておきます。非常に今話題になっておりますが、これについてのご見解を先ほど聞きませんでしたので、ここでご見解をちょっと聞かせてほしいと求めました。","respondent":"日下部障害者福祉課長","answer":"私どもも調べましたところ、確かに最新の機器として骨伝導方式の携帯電話が大手のメーカーからも発売されるようになってあります。その辺の点も含めまして、今後の検討課題とさせていただきたいと、このように考えております。","id":"exchange-129"},{"speaker":"山路委員","kind":"質問","question":"これは日常生活用具に入っているのかどうか、教えていただけますか尋ねました。","respondent":"日下部障害者福祉課長","answer":"残念ながら、まだ機器の開発ができて間もないということもございまして、日常生活用具の指定対象にはなってございません。","id":"exchange-130"},{"speaker":"山路委員","kind":"質問・要望","question":"今後、よろしくお願いいたします。私も非常に医療と福祉の谷間にある制度で一般質問でお願いしたわけなんですが、斜視、まず認識を聞かせてほしいと求めました。","respondent":"日下部障害者福祉課長","answer":"つまり、どの程度の範囲で見ることが可能なのか、その視力と視野を合わせまして、国の定める障害等級の基準があります。当然手帳交付の対象になってまいりますけれども、当然のことながら手帳の交付対象にはなっていないと、そういう現状です。","id":"exchange-131"},{"speaker":"山路委員","kind":"質問","question":"これは注射を打ったり、薬を飲んだりするよりも、矯正眼鏡で治りやすいんだそうです。これに対する支援、これも今後考えてもいいんじゃないかと思いますけれども、どのようにお考えか尋ねました。","respondent":"日下部障害者福祉課長","answer":"今回弱視、斜視ということで初めてお伺いしましたので、今後の検討課題とします。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問・要望","question":"こんなところから、今日特養ホームを利用している方から、生涯このホームで暮らしたいという要望の人がかなり出ているというお話を聞いております。こういう事業の考え方としてどうなんだろうかということを、また働きかけられるのかという、その実情のところをご答弁をお願いいたします。","respondent":"早津高齢福祉課長","answer":"特養ホームにおける最後の看取りに関するお尋ねです。最後まで頑張るというような形での運営に努めているところですが、あるいは介護体制、そのような形での努力はしているという状況であると思います。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"痴呆もあるかと思いますけれども、肉体的に。最後まで看取るという特養ホームというのは、何箇所ぐらいあるんか尋ねました。","respondent":"早津高齢福祉課長","answer":"これは各法人が運営しておりまして、その運営法人の中でのケアに対する考え方というものがかなり出てきているのもあろうかと思います。すべてのものがどうかとか、特養という施設の性格上、そういうわけになっていないという現状はあるです。","id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"二つお伺いしたいと思います。はこのシステムの手続等を、行政のほうでもっと積極的に取り入れられるように動いていただけないか、この２点についてお伺いしたいと思います。","respondent":"新美保健高齢事業部長","answer":"その範囲での対応が可能なところは、例えば特定施設ですとか、在宅の医療が入るところで工夫していくのが介護保険の施設類型かと存じます。これからさらに充実していきたいと考えていますので、大きな方向としては、そういうことで対応してまいりたいと思います。","id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"先ほどの特養ホームですか、これもやはり今後２４時間医療が係われるような仕組みを国のほうに要請していただいて、それが第１点。第３点、乳幼児・小学生医療費助成事業なんですけれども、先ほどから何人かの委員からお話しがありますけれども、所得制限か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"本多委員","kind":"質問・要望","question":"２１３ページの保育園運営費について、保育料の改定につきましてご質問いたします。」となっておりますけれども、この「全部または一部」の範囲につきまして、例えば政令指定都市など例を挙げて教えてほしいと求めました。","respondent":"金子保育課長","answer":"その意味で、やはり特別区あるいはそのあたりで非常に低い保育料を設定してきたという経過があると考えています。私どもはそういう経過を踏まえた上で、今回９％の引き上げという改定案をご提案を申し上げているわけです。","id":"exchange-137"},{"speaker":"本多委員","kind":"質問・要望","question":"現行の階層区分の２６そのものの考え方と、Ｂは変わりませんけれども、２６のそれぞれのアップ率に対してご説明ほしいと求めました。第２子以降の基準についても教えてほしいと求めました。","respondent":"金子保育課長","answer":"第２子以降の保育料についてですが、第２子以降に関しましては、おおむねこの保育料の２分の１から１０分の７ぐらいまでですね。階層によって若干違いますけれども、そのような形で保育料を減額しています。","id":"exchange-138"},{"speaker":"本多委員","kind":"質問・要望","question":"平均で ９.２％ということなんですけれども、受益者全体の公平性というところではどうなのかなと思うんですけれども、改めてその点について教えてほしいと求めました。","respondent":"金子保育課長","answer":"先ほども答弁で申し上げましたとおり、児童福祉法で規定しています保育料の考え方でも、家計に与える影響を考慮してというふうにあります。高いところには総体的に影響が大きくというふうな形に、所得階層に配慮したものとしておりますので、ご理解をいただきたいと思います。","id":"exchange-139"},{"speaker":"本多委員","kind":"質問","question":"次に納付が困難な場合というところで、状況に応じて保育料の減額という制度が今までありました。災害に遭った方ですとか、５項目ぐらいあると思うんですけれども、その制度はそのままということでよろしいか尋ねました。","respondent":"金子保育課長","answer":"委員ご指摘のとおり、納付が困難な場合、主なもので５項目、ほかにも若干ありますが、この制度については変わりなくそのまま維持する考えです。","id":"exchange-140"},{"speaker":"本多委員","kind":"質問・要望","question":"そのためには１０月までの間の周知については、本当にご努力をしていただきたいなと思います。１０分の１０で来る委託のものとか、その辺につきまして、周知というところについて教えてほしいと求めました。","respondent":"金子保育課長","answer":"なかなか保育料の仕組み、また保育の運営費全体における区の持ち出し部分というのが、なかなかご理解いただけていない現実があろうかと思います。","id":"exchange-141"},{"speaker":"本多委員","kind":"質問・要望","question":"昭和４０年に三ツ木保育園が開園しましてから、やはり料金改定というものですから、区役所から発行した資料をちょっと見ているんです。銭湯の入浴料が約１０倍と、これを３倍上がったから食べられないという方はまずいないわけで、ちょっと感想をほしいと求めました。","respondent":"小沼福祉事業部長","answer":"それが確か総合指数で６５.５が、平成 １１年の段階で１０２.２というようなことで、４０から上がってあります。今回は子育て支援、一方で進めますけれども、今申し上げた点でよろしくご理解のほどをお願いしたいと思います。","id":"exchange-142"},{"speaker":"本多委員","kind":"質問・要望","question":"保育のニーズの多様化、就学前児童教育、福祉のさらなる充実を図りつつ、園整備の適正配置などを視野に入れまして、園の運営は受益者負担の方向ということなんですけれども、経営主体の多様化につきまして、今後の方針などはどのような方向なのか教えてほしいと求めました。","respondent":"金子保育課長","answer":"今年の６月にぷりすくーる西五反田をオープンいたしますが、例えばそれのミックスとか、いろんな形態があり得ると思います。そういう意味では、個別のケースに応じて、さまざま検討していきたいというふうに考えてあります。","id":"exchange-143"},{"speaker":"本多委員","kind":"質問・要望","question":"しかし、ある高齢者クラブのお話を伺いました。というのは、やはり世話焼きさんと言うんですか、会長ですとか、世話焼きさんが相当いろいろとご苦労されていると思うんです。","respondent":"蓼沼高齢事業課長","answer":"新たな方にかわっていただくということもあろうかと思いますし、いずれにいたしましても私どものほうの窓口に来てご相談等もお受けしています。","id":"exchange-144"},{"speaker":"山村委員","kind":"質問","question":"お金を自分のために使いたい若者が多いものですから、お金がかかると言っている若者もいるということをまず頭の中に入れていだければと思います。いろいろと児童福祉に関しての質問がありまして、どうか私の勉強のために区長にお答えしてほしいと求めました。","respondent":"金子保育課長","answer":"子育て支援、さまざまな事業があります。そういった事業の性格、受益者の負担をどの程度設定するのが適切かと、個々的に判断するのが一番肝要なところではないかというふうに考えてあります。","id":"exchange-145"},{"speaker":"山村委員","kind":"質問","question":"次に１９８ページの心身障害者福祉費のことについてご質問したいと思います。障害児童と普通児童との交流は、現在どのようなふうになっているのか教えていただけますか尋ねました。","respondent":"日下部障害者福祉課長","answer":"一般的に申し上げますと、例えば学校に上がれば学校において障害児の皆さん方も普通学級に入っていらっしゃるケースもある。だから、そういったところにつきまして、いろいろな形での交流がなされているという状況です。","id":"exchange-146"},{"speaker":"山村委員","kind":"質問","question":"今後はもっと増やしていただければと思うんですが、最近は２０人に１人ぐらいが学習障害、ＬＤですか。４０人に１人がＡＤＨＤ、そういう児童を受け入れるために、一般の学校の教室とかで工夫されていることがあるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"山村委員","kind":"質問","question":"かかりつけ医ということなんですが、薬剤師とか薬局、薬のことに関しては、これとどういうふうに絡んでいく予定があるのか、考えられているのか教えてほしいと求めました。","respondent":"田中健康課長","answer":"いわゆるかかりつけ薬局といいますか、そういうお話というのは先日の一般質問でもいただいておりますけれども、品川区においてまだかかりつけの薬局という部分までは、そういう意味での考え方としてしっかりしたものがないのが状況です。","id":"exchange-148"},{"speaker":"山村委員","kind":"質問","question":"飲み合わせ等ですとか、皆様が思っているよりも薬というものは、特に１カ所でやられたほうがいいというのが現状だと思う部分があるんです。かかりつけの薬局ですとか、そういう考えもあるんじゃないかと思うんですが、どうか尋ねました。","respondent":"田中健康課長","answer":"それから、これから十分私どもは取り組むべきフィールドとしては考えられるというふうに思ってあります。そことどういうつなぎをして、どういう機能を持っていただくかをこれから必要に応じて薬剤師会とも相談をしていきたいというふうに考えてあります。","id":"exchange-149"},{"speaker":"山村委員","kind":"質問・要望","question":"とりあえず、これは要望ということで、よろしくお願いいたします。次は、１９５ページのしながわ出会いの湯事業について、どのようなことをやられているのか教えてほしいと求めました。","respondent":"蓼沼高齢事業課長","answer":"これにつきましては区内の公衆浴場を活用して、６５歳以上の高齢者の方が毎週木曜日にお楽しみプログラムと言っておりますけれども、カラオケですとか健康体操を楽しんだ後に無料で入浴をしていただくという事業です。","id":"exchange-150"},{"speaker":"山村委員","kind":"質問","question":"そうしますとこの事業に対する補助だと思うんですが、今後もこのほかに銭湯を地域のふれあいの場というか健康面において、どのように活用していくかお考えがあったら教えてほしいと求めました。","respondent":"蓼沼高齢事業課長","answer":"今現在、区内の公衆浴場をこういう形でご理解ご協力をいただいて、しながわ出会いの湯事業を実施しています。例年何回か浴場組合の方との懇談会等を設けましていろいろ検討していますけれども、それにつきましては今後の課題というふうに考えてあります。","id":"exchange-151"},{"speaker":"山村委員","kind":"意見","question":"千代田区では銭湯が四つぐらいしかなくなってしまって、わざわざ区がつくったそうです。鋭意活用していただいて補助をしていただければと思うんですが、今後どのように活用していくか、よろしいでしょかとの意見を述べました。","respondent":"田中健康課長","answer":"それから設備の資金の、これは大規模のほうの資金ですけれども、実施補助という制度を持ってあります。ここのところ事実上、もっとにぎやかになる方法論も、こういうベーシックなものと組み合わせてやっていく必要があるというふうに考えてあります。","id":"exchange-152"},{"speaker":"山村委員","kind":"質問","question":"次は、２０２ページの社会福祉施設費のことでお聞かせほしいと求めました。そういう場合だと区営住宅に入れないでのでしょうか、無理なんだとは思うんですが、その辺を教えてほしいと求めました。","respondent":"市岡企画財政課長","answer":"公営住宅法等の規定では世帯が単位になっておりまして、そういう任意のグループというのは対象になっておりませんので、現状ではそういう対象にはなりません。","id":"exchange-153"},{"speaker":"山村委員","kind":"質問","question":"グループリビングということは、住宅を確保するのが一番難しいそうなんですよ。そういう意味で、これからは一つのあり方としてあるんじゃないかと思うんですが、どのように思いますか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"高齢者の住宅の問題ですけれども、今、公営住宅、区営住宅に組み込めないかというご指摘ですけれども、現状では難しいです。今後そういうような選択肢が可能なのかどうか、総合的な高齢者住宅施策の中で、一つの課題として検討していきたいというふうに思います。","id":"exchange-154"},{"speaker":"宮崎委員","kind":"質問","question":"私は３８５ページ、４３３ページ、４５３ページ、国保、老健、介護について伺いたいと思います。こういうケースは、何か対応というのはできないものなんか尋ねました。","respondent":"早津高齢福祉課長","answer":"極めて個別的なケースですし、その例では生活保護のケースワーカーとの連携の中で相談しつつ、対応しているというようなものがありました。お尋ねのケースと一致しているかどうかわかりませんけれども、そういうような事例はあったです。","id":"exchange-155"},{"speaker":"宮崎委員","kind":"質問・要望","question":"どういうふうになったのかお聞かせほしいと求めました。回ったというお話だったんですけれども、その結果というのは、回したら知らないということなんか尋ねました。","respondent":"早津高齢福祉課長","answer":"個別のケースですので、似たようなケースかもしれないし、正しいか正しくないかということはわかりかねるところでございまして、詳細なお答えというのはしかねるものです。","id":"exchange-156"},{"speaker":"宮崎委員","kind":"質問","question":"ところがケアマネージャーは「大家さんに言ってくれ」の一点張りだったということなんですよね。ですから、私は結果どうなったのかということを聞いているんです。","respondent":"早津高齢福祉課長","answer":"再三になりますけれども、個別のケースのことで、またいろいろ当事者の情報というのもあろうかと思います。委員からのご発言を受けて、こうであるというようなことは誤解を招きかねないと思いますし、この場での発言は控えさせていただきたいと思います。","id":"exchange-157"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ショートステイとか、どういう負担を求めていくことなのかも含めて、どういうふうに考えているのかも含めてお伺いしたいというふうに思います。併せて、どの程度の施設を考えておられるのかお伺いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-158"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、非常にこれについては怒っています。跡地の利用については、最初に聞いたように、いつどういうふうに決めるのかというところを併せてもう１回お伺いしたい。","respondent":"高橋区長","answer":"ああ、なるほどなという思いをいたしました。そういう方向をこれからも在宅介護をより伸ばせていくように、またそれをより補完をさせていかれるような施策に重点を置いていきたいと考えています。","id":"exchange-159"},{"speaker":"宮崎委員","kind":"質問・要望","question":"このぐらい利用が拡大できるんじゃないかという目標があれば教えていただきたいというふうに言ったんですけれども、もし今あればと思います。そして、私どもの計算では２３区で計画も含めて大体１８番目というふうに思っておりますけれども、お伺いしたいと思います。","respondent":"高橋区長、早津高齢福祉課長","answer":"都南病院の問題について、具体的な計画はですけれども、今、あの土地が買えるか買えないかわからないわけですから、買える見通しが立ちましたら、具体的な計画を立てていきたいと思っています。 ケアマネージャーの権限としては、ノーです。","id":"exchange-160"},{"speaker":"宮崎委員","kind":"質問・要望","question":"例えば、１０年前はどうだったのかと、同じモデル世帯で三つの収入区分のところの保険料を教えていただきたいというふうに思います。これは本当におかしいし、この値上げが区民の暮らしにどういうふうな影響を与えるのか、この辺の基本的な認識をお聞かせほしいと求めました。","respondent":"太田保険年金課長","answer":"次年度の医療費の総額に対してどう見込むか、それに対して国庫負担等の補助がどう見込まれるか、そういうことから言えば。ただ、国民健康保険に加入されている方だけが厳しい状況であるということではないというふうに認識をしています。","id":"exchange-161"},{"speaker":"宮崎委員","kind":"質問","question":"昨年も伺いましたけれども、倒産だとか、そういう経済的な理由による滞納が非常に増えてきているというふうに思います。今短期証はどういうふうに発行されてきているのか、四、五年にわたっての数がわかったら教えていただければというふうに思います。","respondent":"太田保険年金課長","answer":"平成１３年１０月で ３,５００件、平成１４年４月で２,７００件、平成１４年１０月で２,１００件です。去年の１０月で２年証の更新時期を迎えましたので、４月で６,８００件ほど、昨年の１０月で５,７００件です。","id":"exchange-162"},{"speaker":"宮崎委員","kind":"質問","question":"国庫補助も８４年には確か４５％だったものが、現在は３８.５％というふうになっております。最後に伺いたいのは、ぜひ増やせというふうに言ってほしいんですけれども、その辺の考え方を最後に聞いておきたいと思います。","respondent":"太田保険年金課長","answer":"国庫負担の問題については、従来から私ども区長会から国に対して５０％の補助をしてほしいということでの要請はしています。なお、東京都につきましては、東京都が独自に施策を展開している部分のペナルティの項目補助ですので、一般的な補助ではございません。","id":"exchange-163"},{"speaker":"堺委員","kind":"質問・要望","question":"一つは、１,８１０万５,０００円計上されておりますが、まずこの経費の中身について教えてほしいと求めました。７,０５１万２,０００円計上されておりますが、先般要望してきたところですが、簡単に教えてほしいと求めました。","respondent":"蓼沼高齢事業課長、辻田児童課長","answer":"主なものといたしましては、まず人件費で、１人当たり３６０万円の４人分です。それと事業費が３６０万円が主な内容です。私どものこの金額では実施施設３４、児童センター、その他の複合施設９カ所すべてで３４カ所です。","id":"exchange-164"},{"speaker":"堺委員","kind":"質問","question":"先ほど人件費で３６０万円で４人、例えばそういう方はどういう経歴の持ち主なのか、参考までに教えていただけますか。これは事業内容あるいは事業目的に沿った形で実施されるわけですが、実施時期は大体いつ頃を想定しているんか尋ねました。","respondent":"蓼沼高齢事業課長、辻田児童課長","answer":"職員の方たちの経歴等ですけれども、中にはシルバー人材センターの会員の方であったり、あるいは区内の企業所のＯＢの方であったりという方たちです。 実施ですけれども、大体６月から始まりまして、何とか８月末までに終わらせたいという具合に考えているところです。","id":"exchange-165"},{"speaker":"堺委員","kind":"質問・要望","question":"今からそれに耐え得るというんですか、こんな気がするんですが、その辺はどのようにお考えになっているのか教えてほしいと求めました。もう一つお尋ねしたいのは、３４カ所を約７,０００万円ですから、もう１回教えていただけますか。","respondent":"蓼沼高齢事業課長、辻田児童課長","answer":"これにつきましてはサポしながわの事業そのものがそういった要請に先見的にこたえている事業ではないかというふうに考えてあります。雇用者の雇用安定法の改正も予定されているですので、シルバー人材センターと含めて… ３４施設を２カ月でできるかですけれども、そういうことで可能かなという具合に考えて、なるべく短期間にあげていきたいという具合に考えております。","id":"exchange-166"},{"speaker":"堺委員","kind":"質問・要望","question":"やはり小さい子どもがお使いになる児童福祉施設ですから、何かあってからでは遅いわけでありますから、そういう面では早急にお願いしたい。来年度当初予算でやるのか、その辺の今後のスケジュールはどうお考えになっているのか、ちょっと教えていただけますか。","respondent":"市岡企画財政課長","answer":"本当に緊急性があるのであれば、時期を問わずに着手すべきだと考えております。短期間でできるもの、いろいろな手法がありますので、その辺も十分研究して対応していきたいというふうに考えてあります。","id":"exchange-167"},{"speaker":"堺委員","kind":"質問・要望","question":"最後に、今お話しがございましたので安心をしたんですが、結果が確かに出ないとわかりませんが、緊急性のあるものについては、補正予算を組んででも速やかに対処していただきたい、このことを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-168"},{"speaker":"伊藤委員","kind":"確認","question":"まず先に確認の質問でありますが、そのほかの子どものみに施策が集中してはいけないと思いますが、いかがでしょうかというのが一つ。素晴らしい保育行政を展開してきたと思うんですが、いかがでしょうか、その確認をまずお願いします。","respondent":"金子保育課長","answer":"子育て支援策ですが、全体的に考えていくもの、実施していくべきものというふうに考えてあります。独自のサービスメニューを考えて展開してきた結果が、今の充実した保育サービスであろうというふうに考えてあります。","id":"exchange-169"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今回の保育料の改定が９％の改定でも１億１,０００万円ですから、そのことの確認を一つ。平成１６年度のみで結構ですから教えていただきたいんですが、いかがか尋ねました。","respondent":"金子保育課長","answer":"非常に難しいものでありますが、延長夜間保育についてのみは職員の増配置をしていますので、その分だけは計算できるかと思います。先ほど、委員がご指摘した事務事業評価の部分については、あたっているかなというふうに考えるところです。","id":"exchange-170"},{"speaker":"伊藤委員","kind":"確認","question":"予算ベースは ５,４１７万円ですけれども、コストがかかっていることは事実、そのことを確認させていただきました。うちの公費が７８億９,５００万円でありますが、確認したいのは現行の保育料、今いただいている保育料はこの運営費全体の何％であるのかということ。","respondent":"金子保育課長","answer":"それから、国徴収金基準額に基づいて区がその保育料の負担部分を肩代わりしている、これを金額にしますと９億２,２００万円ほどになります。さらに、運営費の加算部分として区が負担している部分は５１億５,８００万円というふうな数字になってあります。","id":"exchange-171"},{"speaker":"伊藤委員","kind":"質問・要望","question":"やっぱり、これはこの情報化の時代ですから、これから利用する保護者の皆さんに端的に教えていただきたい。９.４％の負担をいただいていることは事実ですけれども、そのかわり残りの九十何％ですか、それはきちんとご説明していただきたいんです。","respondent":"金子保育課長","answer":"つまり９.４％ほどですけれども、区民全体にわかりやすく周知していかなければならないものと考えて、周知を図っていきたいというふうに考えております。","id":"exchange-172"},{"speaker":"伊藤委員","kind":"質問・要望","question":"できれば、品川区のホームページもあるわけですから、ぜひご説明いただきたいと考えています。結果として負担を求めていくんだという姿勢で、品川区の自己決定、それからこれからの行政をどう担っていくかということをご答弁をお願いします。","respondent":"高橋区長","answer":"やはりこれだけ充実した保育をしていく中で、値上げはやむを得ないというような考え方で値上げを実施させていただきました。そういうものを勘案しながら、２３区が統一でなくて実施できるものにつきましては、品川区なりの行政をこれからも続けてまいりたいと考えています。","id":"exchange-173"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/906948?Template=document&Id=826#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":127588,"voices":409}},{"id":"h16-20040311-3","meetingId":"h16-c-budget","date":"2004年3月11日","dateIso":"2004-03-11","committee":"予算特別委員会","time":"午前１０時０５分～午後６時２３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を162件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"商工費のうち２６１ページの都市型観光推進事業、２３３ページのあたりを時間があれば、お伺いしたいと思います。構築をするためにはどのように区がかかわっていらっしゃるのか、本年度からの新しい事業なので、まずそれをお伺いしたいと思います。","respondent":"市川産業振興課長","answer":"これまでも実際にいろいろ品川区の観光ということについては情報発信なり事業が展開されてまいりました。それから関係事業者が一体となってネットワークというものを、まずその中心核をどうやってつくっていこうかということを手始めに仕掛けていこうです。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"意識的に、自発的に、またスポット的にということなんですが、この基本調査を行う上において、今三つ述べられました意識的、自発的、スポット的、そのようなものをもとにネットワークを構築できるような体制をつくるための基本調査がなされるのでしょうか、お答え願います。","respondent":"市川産業振興課長","answer":"今回私どもで予定しております基本調査は、今、委員にご指摘していただいたような点を踏まえて、余り総花的にならないような、ある種具体的な事業を想定したようなネットワークづくりをしつつ、また事業の基本調査を行っていく、こういった考え方でおります。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"観点を移します。本区の地域資源はどのようなものが観光資源と言えるのでしょうか、ちょっと具体的にお答え願えますか尋ねました。","respondent":"市川産業振興課長","answer":"営々と今まで築いてまいりました商店街なり、あるいはさまざまな産業の蓄積、こういったことも観光資源になろうかと思います。もう一つは、区のさまざまな行政施策による評価と申しましょうか、そういったものも一つ観光資源になろうかと考えています。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"１０５でよかったでしょうか、失礼いたしました。１０５ということで私は心得ておりましたけれども、どのように商店街に対して方策がなされるのか、ちょっとお伺いいたします。","respondent":"市川産業振興課長","answer":"一つ具体例をお示しして説明しますと、戸越銀座銀六商店街という商店街があります。こういった仕掛けを仕掛けていくことによって、今までの近隣型商店街といえども、新しい展開ができるのではないかというふうに考えてあります。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"そうしますと、新しい展開ということで、その展開という意味合いにしますと、今まで商店街に対する事業が、また別の方向あるいは事業に対して施策の多少なりとも方向修正または転換、追加があると思われるんですが、いかがなことか尋ねました。","respondent":"市川産業振興課長","answer":"こういった皆さんとネットワークを組むことによって、今まで商店街が持っていた隠れた能力と申しましょうか、そういうものが発揮できる場面があろうかと思ってあります。","id":"exchange-005"},{"speaker":"大沢委員","kind":"意見","question":"隠れた能力を引き出すということで、これがまさに一つの都市型観光推進事業のうちの一つの要素ということで私は受けとめさせていただきました。これからなされる事業でありますけれども、方向性といいますか、お考えがありましたら説明を求めました。","respondent":"市川産業振興課長","answer":"今ご指摘いただいた点が、実は大きな課題であると私どもも認識をしています。一つはやはり共通のポイントカードシステム、こういったものも有効な手段ではないかというふうに考えてあります。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"先ほどの衛生費のうちの環境衛生についてですけれども、鳥インフルエンザについて、入り口だけなんですが、ちょっとお伺いしたいと思います。カラスを含めた野鳥に対してどのような取り組みをされるのか、本区独自のものがありましたら、説明を求めました。","respondent":"島袋品川区保健所衛生課長","answer":"現在のところは、区独自の政策というよりも、都と連携しまして情報を集めて、例えば区の保健所にカラスの死骸があったか、鳥の死骸があったか、そういう情報を集めている段階です。","id":"exchange-007"},{"speaker":"大沢委員","kind":"意見","question":"聞くところによりますと埼玉県のほうでも１１０羽、１０７羽ぐらいが、受難の時代になってしまったなということだと思います。そのときには安心するような方法でひとつご対処のほうをお願いいたしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"今の質疑、引き続きますが、鳥インフルエンザ、まずこの鳥インフルエンザというものはどういうものでしょうか。ちょっとまとめて皆さんにお知らせ願えればと思います。","respondent":"寺西品川区保健所保健サービス課長","answer":"この昨年末に韓国で大流行いたしまして、そしてこの２月２８日に京都で実際に感染した鳥が流通したということで、今大問題になっているところです。ただ、鳥同士であれば、非常に強力な病原性を持ったインフルエンザというご理解でよろしいかと思います。","id":"exchange-009"},{"speaker":"若林委員","kind":"意見","question":"ＳＡＲＳのときでも問題になりましたが、その症状、どういう見分け方をしたらいいのか、あったらお願いいたします。こういうふうなネットワークをさらに強化をしていきますよとか、そういう重点的なものがあれば、お知らせを願いますとの意見を述べました。","respondent":"寺西品川区保健所保健サービス課長、島袋品川区保健所衛生課長","answer":"そういうキットで簡単に簡易検査ができます。血液中の抗体検査であるとか、一々非常に細かい検査を進めていかないことには、これが鳥インフルエンザかどうかというのはわからないという状態です。 ３月１日号の広報しながわで、感染症についてということなんですけれども、鳥インフルエンザに関することも載っております。ただ、これから情報等を集めまして、ホームページ等の活用も考えていきたいなと考えているところです。","id":"exchange-010"},{"speaker":"若林委員","kind":"意見","question":"その内容と、それに対する対処の仕方、これを最後にお願いいたします。どう対処をされたのかとの意見を述べました。","respondent":"島袋品川区保健所衛生課長、谷田部学務課長","answer":"は、なるべくだったら直接さわるようなことはしないでください、そういう相談はございました。詳しいところにつきましては、我々で対応できない場合には家畜保健衛生所が都にありますので… 中学校、幼稚園も含めまして、調査をいたしました。私ども緊急に消毒をするということで現在準備を進めてありますし、そういうようなことを徹底するということは、私どもから指導しています。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問","question":"これは、足し算をすれば全体ということでよろしゅうありますか。それと、例えば品川区におきましては、山手通り、そこら辺の周囲の、例えば西五反田周辺の集中度合い、数というのはわかりますか尋ねました。","respondent":"田中健康課長","answer":"それから、お尋ねの山手通り沿線といいますか、そういう形での地域的なところというのは特に見当たらないというのが私どもの今の把握です。品川区全般にこういう形で患者がいらっしゃるというふうに私どもは認識しています。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"ある西五反田地域の幼稚園では、非常に不確かな数字ですけれども、こういうことがあるように聞いております。調べていただければなと、これは一つ要望をしますので、どうぞよろしくお願いをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区には保健所や保健センターが３カ所あると伺いました。この３カ所ありますけれども、特に虐待の実態についての相談の件数や相談の内容の傾向について可能な限りご説明してほしいと求めました。","respondent":"小林品川区保健センター保健サービス課長","answer":"現在のところは虐待とまではいきませんけれども、虐待の関連のご相談というふうで上げしますと、今のところ今年度３４件というふうになっております。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"どのような体制で全体の把握をしているのか、虐待の統計などありましたら教えてほしいと求めました。平成４年度と平成１４年度の統計と、あと、何倍ぐらい相談の件数が増えているのか説明してほしいと求めました。","respondent":"辻田児童課長","answer":"それから平成１４年度には３０件、平成１５年度、これは１月現在ですけれども４４件という形で推移しております。相談がなくてもそういう事例を何とか発見しようということで、各児童施設ではそれぞれの子どもたちの見守りをしているという状況があります。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただいま件数の報告がありましたけれども、これは品川の児童相談所に寄せられた件数なのでしょうか。２００１年だと２万３,２７４件と増えている傾向があるんで、品川区はどういう状況をつかんでいるのか、もう一度説明してほしいと求めました。","respondent":"辻田児童課長","answer":"虐待の事例であるか事例でないかというのは非常に判断が難しいという状況が一つあります。そういう中で、大体４０件程度の虐待の話ではないかという形でのご相談は受けているということです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"その体制といいますか、いろんなところから相談を寄せられますので、それぞれの事業部にまたがると思うんですね。ぜひその実態をつかむ体制の整備、またどこが中心になって行っていくのか、今後のお考えがございましたら教えてほしいと求めました。","respondent":"辻田児童課長","answer":"この虐待の事例の対応につきましては、今ちょうど過渡期にあるのかなというぐあいに考えております。さらに昨年平成１５年１月に発足しました児童虐待防止協議会、今後区の中のものはまとめていくという形になってくるというぐあいに考えております。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどの説明で、品川区の三つの現場で働く保健師の数というのはどのような傾向になっているのか、ちょっと教えてほしいと求めました。厚生労働省の調査がちょうど平成４年度に始まっているんで、それぞれ平成４年と平成１４年、説明してほしいと求めました。","respondent":"田中健康課長","answer":"それで、今申し上げたのは平成４年４月１日当時がこういう形になってあります。現状は、本年度３３名が保健高齢事業部に配置をされております。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"事態が日々深刻になっているので、きちんと配置をして充実をすべきでないのかなと思います。現場ではなかなか苦労もあるとは思いますけれども、ぜひ保健師の充実をすべきではないかと思いますけれども、お考えを示してほしいと求めました。","respondent":"田中健康課長","answer":"健診系は一応医師会等への委託等に移してまいりまして、あるいは高齢福祉課等を通じまして、いろいろな中で現状やってあります。私ども昨年定数の見直し等も再度いたしまして、これからの業務に関しての必要な定数ということで、現在設定をしています。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"区民にとっては身近な窓口であり、健康診断を直接行うべきところですから、より充実したことが必要ではないかなと思っています。子どもの地域でのネットワークづくりですか、この虐待についての認識を区民に広げていく、こういう活動なんかも必要ではないかと。","respondent":"小林品川区保健センター保健サービス課長","answer":"さまざまな区民の方への健康の支援、ご相談、健康に関するすべての活動を行っております。子育ての支援、虐待にならないような取り組みということで、区民の方々に期待される保健所にしていきたいと考えております。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"１人が１年間に大体２０件ぐらい、人口がおよそ２倍である日本の数はどうかというと、１,６２７人しかいないということがわかりました。職員は８分の１というのが現状ではないかと思いますけれども、現状のままでいいのかという区のお考えがありましたら、教えてほしいと求めました。","respondent":"辻田児童課長","answer":"昨年児童福祉法の一部改正を行い、療育の対応、今後平成１６年度に向けていろいろな動きがあるのではないかなというぐあいに考えております。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"そもそもの児童福祉士を増やす方向で国のほうにも働きかけていく、大切なことではないかと思いますので、これは要望しておきたいと思います。通告者に虐待かどうかの確定判断は求められているわけではなくて、当然ですけれども児童相談所や家庭裁判所が行うことですから、当然。","respondent":"辻田児童課長","answer":"昨年１月に発足しました児童虐待防止協議会、いわゆる区の職員、そういうような方々にこの発見の大切さというのは会議などを開いて周知しております。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"なかなか上手に質問できないんですけれども、直接この区の職員に対しては、どういう研修が行われているのかというのが伺えればと思います。いろいろなケースで相談が寄せられていると思うんで、職員全体の何か研修が今行われていたら、最後にこれだけ教えてほしいと求めました。","respondent":"辻田児童課長","answer":"幾つかの、基本的には要するに仕事の中、ＯＪＴの中で実際に周知していくというのが原則だと思います。いろいろな機関が集まりまして、年に１回そういうような会議を持っている、そういう中で周知をしているということがあります。","id":"exchange-023"},{"speaker":"土井委員","kind":"質問・要望","question":"それらを含めた、焼く問題があるわけですから、その辺の状況等をどう検討されていくのかということをまず１点伺いたいこと。どういうノウハウをどこから聞いてくるのか、大崎の駅前に近いわけですから非常に便利なんで、お聞かせをほしいと求めました。","respondent":"島袋品川区保健所衛生課長、中山清掃リサイクル課長、市川産業振興課長","answer":"私ども区内に２３の動物病院がありますけれども、それをまず送ったのと、厚生労働省の通知を送った。これは法律上でも決められておりますので… もう一つ、現在これは助役会の検討部会という中ですけれども、鋭意検討を開始している。ごみのそういう減量も分担金の中に折り込まれるような仕組みが考え… 製造業に関する１点目ですが、この数年、特に成形加工という分野の方が多かったもので非常に厳しい経営環境をくぐってまいりました。","id":"exchange-024"},{"speaker":"土井委員","kind":"質問・要望","question":"これはもう燃えるごみに入れましょうということでやっていけるわけですから、もう一度お伺いいたします。コンサルタントみたいな方がいいのかどうかわかりませんが、ぜひとも立派なものをつくっていただきたいと考えていますので、説明を求めました。","respondent":"中山清掃リサイクル課長、市川産業振興課長","answer":"その分別を具体的に変えるのかどうかということと、その後そのまま処理をしないで埋めるということとの切りわけが必要かと思います。それから、現在… この大崎図書館での事業の支援スタッフの件ですけれども、そのＮＰＯの共同作業、コラボレーションという形でこのビジネス支援図書館の事業を遂行していきたいというふうに考えてあります。","id":"exchange-025"},{"speaker":"土井委員","kind":"質問","question":"ですから、そこら辺はきっちり決めていただかなきゃいけませんよ、早急に決めてくださいよ、こういうことを申し上げているんですよ。どうですか、ちょっと説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"確かに工場の炉のカロリー能力というものも、従来のような傷むであるとか、いわゆる排ガスの問題もなくなってきている、こういうことも踏まえて、今ご指摘のとおり、これからの適正な処理の中で、資源の有効利用という中で考えていくべきというふうに考えております。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それが２５０ページですか、それと産業経済費の中の２５９ページ、それともう１点が製造業マンパワー強化支援事業。もう一歩戻っていくと、現状で行っているインターンシップ、そこら辺の流れもちょっと先にご説明ほしいと求めました。","respondent":"中山清掃リサイクル課長、市川産業振興課長","answer":"現在約４万３,０００世帯ほどのエリアに広がっておりますが、１０月までに７万世帯を拡大して、区内７割という予定で拡大しています。ご指摘があったように… 平成１１年度から今年度まで５年間にわたりましてインターンシップの推進事業ということで、一定の助成を行って支援をしている、こういう事業を展開してまいりました。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、その方は一般に町会の人だと思って話していた中で、すごく責任を持ってやっていたんです。その部分に対する対策、区の中でどう考えているのか、それをもう１点お聞きしたいと思います。","respondent":"中山清掃リサイクル課長、市川産業振興課長","answer":"なかなか根絶が難しいという中で、もう少し区への排出の意思表示ととりにくさを明確にする仕掛けを考えていきたいとご説明いたしました。恐らく古紙の回収… 具体的に区内の中小企業からそういった希望が出るなり、あるいは私どもが産学連携事業の中で提携している大学に対して、それなりのあっせんのようなことができれば十分に可能なことだと思ってあります。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"袋にどのくらい、１戸当たり何枚ぐらい配られるのかというのは非常に疑問もあって、あっと言う間に新聞社から来るのがなくなっちゃうんですよね。なるべく産学連携事業で増やしていただきたいのもあるんですけれども、もう一つは、その辺ももう１回ご説明ほしいと求めました。","respondent":"中山清掃リサイクル課長、市川産業振興課長","answer":"当面５万世帯分ぐらいをつくって町会への配付と、施設においてお配りするということを併用してやっていきたいというふうに考えております。表示の中で考えておりますのは、それ以外のものは禁止をする、こういう表示を書き分ける予定で… 従来の人材育成支援事業を組みかえて製造業マンパワー強化支援事業とした一つの柱に、技術的なレベルアップを図るために送り込むケースがあります。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そのまま使って再生していくという点に関してもお聞きしたい。とりあえずそこの点をお聞きしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"当面、当面はそういう民間事業者の活用の中で今回やっていきたいというふうに考えておりますが、そこまで区の施設の整備をやっていく。それから収集した後の売却可能なのかどうなのかということも見て判断していきたいというふうに考えております。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それと１個聞こうと思ったのは、今後お話をどう考えていくかということを、お答えを後ほどお願いしたいと思います。できればやってもらいたいということでずっと要望していた部分なんですけれども、保証料という問題がやはり最初随分お答えに絡んでいました。","respondent":"中山清掃リサイクル課長、市川産業振興課長","answer":"行政負担で、こういうことから、この辺は区としてもいたずらに資源を集めていけば行政の負担が大きくならないような形ということを十分訴えていくような場面はきちんと発言していきたいというふうに考えております。いわゆる一本化資金の件ですけれども、今まで鈴木委員のほうからたびたびご指摘、ご要望をいただいてきた件、最終的に実施の詰めをしております。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"都市型観光推進事業について１点お伺いいたします。その依頼したところの一番の理由、メリットというのは何なのか尋ねました。","respondent":"市川産業振興課長","answer":"一定の調査をしていきたいという考え方からいたしますと、いわゆるシンクタンクのようなところに委託するのではなく、私どもの目的をかなえてくれる事業体に委託したいというふうに考えてあります。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"次に、融資あっせん事業についてお伺いしますが、今、鈴木真澄委員の質問の答弁で、預託金制度を廃止したのは影響がないということですが、最近の融資の動向とか、あと特徴、申し込みに対する融資実行の状況を示すよう求めました。","respondent":"市川産業振興課長","answer":"昨年の４月からの６カ月間、昨年の１０月からここに至るまで、５％ないし１０％下がってあります。そういった状況です。","id":"exchange-033"},{"speaker":"藤原委員","kind":"提案","question":"財政についてちょっとお伺いしたいんですけれども、今回も同様な基金の廃止が提案されていると思いますが、ストレートに理解してよろしいんか尋ねました。","respondent":"市岡企画財政課長","answer":"それからもう一つは、むしろ各事業部と金融機関との折衝の中で融資あっせん等の条件が決められるような金融情勢になったということがあります。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"品川区のこの制度融資ということでお伺いしますが、この制度融資というのがどのくらい活用されているか、わかれば数字的で示していただけますか。","respondent":"市川産業振興課長","answer":"ちなみに、これを５年前の数字と比較いたしますと、件数については５年前の倍以上になってあります。それから、金額にいたしますと５年前に比べて３倍以上の伸びとなっています。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"いわゆる制度融資を申し込んで、かかわってくるのは信用保証協会の保証制度ですが、ここで信用保証協会からノーと言われた事業主の受け皿と、それと、今何かと話題になっておりますが、東京都がつくる新銀行というのは、これからどのような影響を及ぼしてくるか、説明を求めました。","respondent":"市川産業振興課長","answer":"信用保証協会で信用保証を否決された事業者の受け皿ですけれども、これは非常に難しい問題です。せっかく設立される銀行ですから、区内の中小企業の融資環境の改善というか、できるだけ役に立ってもらいたいというふうに願ってあります。","id":"exchange-036"},{"speaker":"武内委員","kind":"質問","question":"それから２５５ページ、それから２５９ページの産業経済費の中で、２６３ページの技術ブランド創出経費についてお伺いをします。初めに２５３ページの廃棄物減量等推進委員経費ですが、またどういうお仕事をされているか、それぞれ説明するよう求めました。","respondent":"中山清掃リサイクル課長","answer":"廃棄物減量等推進委員は条例に基づき設置している組織でございまして、現在約４７０名の方を区長から委嘱しています。行政からのいろんなメッセージについても地域の中で伝えていただく、こういうふうな役割をお願いしているものです。","id":"exchange-037"},{"speaker":"武内委員","kind":"意見","question":"それとももうちょっと増えていくのか、その辺ももし方向性がありましたら、お示しくださいとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"当初６００人ほど委嘱したいということでお願いしたんですけれども、地域のみずからのことと考えていただく、その部分についてきちんと身近な情報交換会等もやっていきたいというふうに考えております。","id":"exchange-038"},{"speaker":"武内委員","kind":"質問・要望","question":"これは要望ということでお願いいたします。各戸収集が来年度末で７万世帯増えるということで、減っているかどうかというのはちょっとわからないんですけれども、いかがでございましょうか。","respondent":"中山清掃リサイクル課長","answer":"これは年に１回、２回なんですけれども、やっております。特に各戸収集によってきちんと出し方のルールを守っていただいたようなところについては改善されているというお声もいただいております。","id":"exchange-039"},{"speaker":"武内委員","kind":"意見","question":"ポリバケツはやめてくれというふうに言われたというふうにもちょっと聞いているんですけれども、それがだめなのか、もしだめでしたら理由をお教えくださいとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"適正な管理ができないのであれば、袋出しのほうがむしろ支障がないんじゃないかという、こういうふうなやりとりの中で話が出たのかもしれません。いずれにしても、必要な容器については、きちんと使っていただいて結構だというふうに認識しております。","id":"exchange-040"},{"speaker":"武内委員","kind":"質問","question":"効率を考えるとどうなんだろうということもちょっと疑問にも思うんですけれども、そういった中で、よくご説明をしっかりお願いしたいと思います。個々の、個々のネットみたいなのがないのかという区に問い合わせが何件かあるらしいんですけれども、そういった問い合わせは来ていますか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"それで、個別の場合のそういうネット等なんですけれども、こういう時代ですので、そういう製品も実は出てきてまいりました。区でそういうものを用立てして配る考えはございませんが、そういう地域、これから考えていきたいというふうに思っております。","id":"exchange-041"},{"speaker":"武内委員","kind":"質問・要望","question":"要望としてお願いいたします。ちょっとここに当てはまるのかどうかわからないんですけれども、一応商店街振興事業の、簡単にちょっと事業概要をお願いいたします。","respondent":"市川産業振興課長","answer":"現在、装飾灯を持ってあります商店街が９９ございまして、装飾灯の数にいたしますと２,５００本ほどあります。その他、それからアーチのある商店街、こういったところにそれぞれ装飾灯なり電灯の１本について定額の補助金を定めまして執行しているものです。","id":"exchange-042"},{"speaker":"武内委員","kind":"質問","question":"同じ振興の中で、こちらの課としてそういった形で商店街にいろいろな対応等、お願い等はされておるんか尋ねました。","respondent":"市川産業振興課長","answer":"この件につきましては、まちづくり事業部の所管課と私ども連携を密にして、商店街の指導に当たってあります。守るべきルールは守った上で、そこで私ども支援すべきものは支援する、こういうスタンスを明確に打ち出していきたいというふうに考えてあります。","id":"exchange-043"},{"speaker":"武内委員","kind":"質問","question":"では、最後になりますけれども、２６３ページの技術ブランド創出、近隣セキュリティシステム開発経費についてお伺いします。先ほど特許を申請したというふうにお伺いしましたけれども、ここに１,１３３万６,０００円の計上をされておりますけれども、説明するよう求めました。","respondent":"市川産業振興課長","answer":"今回のこのセキュリティシステムの開発につきましては、基本的に区とＮＰＯの負担は折半ということで考えてあります。","id":"exchange-044"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、単純にこの倍の金額がこういった経費という形でよろしいでしょうか。そうすると、これは、もしかしたら、もう発表されていると思うんですが、ちょっと私が知らないで、いつごろ完成の予定か尋ねました。","respondent":"市川産業振興課長","answer":"まず通信システムのソフトの開発に着手いたしまして、それをおおむねこの８月までに完了したい。その上で通信ソフトの最終的な設計、開発の完了と機器の開発を行って、ＮＰＯのほうも今なるべく時間の短縮ということで取り組んでいるところです。","id":"exchange-045"},{"speaker":"川西委員","kind":"質問","question":"初めに保健所の事業に関係してお尋ねいたします。恐らく２２９ページから２３１ページにかかるのだろうと思いますけれども、ここにがん検診、恐らく健康診査普及事業に入るんか尋ねました。","respondent":"小林品川区保健センター保健サービス課長","answer":"ほかの医療機関で受けられない方の診断書は受けていこうということで、そのような事業の改善、見直しを行いました。その一般の中小零細企業の健診については引き続き受けていこうということで、人数を少し増やしてそのまま月に２回ずつ各所で行っているところです。","id":"exchange-046"},{"speaker":"川西委員","kind":"質問","question":"保健所でやりますと６,０００円以下で済むというようなことで、費用の点で大変かかるなという経験をいたしました。そういうことで、若い世代の人たちの支出を増やしていくのは区の姿勢かなというふうにちょっと感じたものですから、いかがか尋ねました。","respondent":"小林品川区保健センター保健サービス課長","answer":"２浪以上の方が健康診断書を求められると思うんですが、いろいろな診断書に対する考え方もさまざまですので、現状どおりでさせていただきたいと考えております。","id":"exchange-047"},{"speaker":"川西委員","kind":"質問・要望","question":"こういう新しく資源の回収に参加しようとする人たちに対してのＰＲ活動をどのように行っていかれるのか、お伺いいたします。地域によって違うんでしょうか、なさったらいかがかと思いますが、お答えをいただくよう求めました。","respondent":"中山清掃リサイクル課長","answer":"団体回収量も増えておりますけれども、より各町会や新しくできたマンション等へのＰＲに努めてまいりたいというふうに思います。資源回収の充実等、これから各地域に入る際に、よりわかりやすく説明を丁寧にやっていきたいというふうに考えております。","id":"exchange-048"},{"speaker":"川西委員","kind":"質問","question":"衣類ですが、私たちの資源に出した衣類はどんなふうに行くのかということを、よく主婦の間で質問が出ます。そういう点でのＰＲも。","respondent":"中山清掃リサイクル課長","answer":"拠点回収で古着の回収をしているものがどうなっていくのかというご趣旨の質問かと思いますけれども、私ども古着問屋のほうに回収を売却しています。","id":"exchange-049"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は、２３１ページの区民健診およびがん検診、あと２３３ページの成人歯科検診について伺いたいと思います。検討はできないものか尋ねました。","respondent":"田中健康課長","answer":"私どもで言えば各区それぞれ２３区違いますし、それから区のほうの保健所ですとかでも違いますし、それから受けられる期間も全然違います。４０歳、５５歳とありますので、そういう意味での相互乗り入れは現状ではできないというふうにお答えするしかないと思います。","id":"exchange-050"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、いつも１日中大田区にいるから、そのかわり品川区の内容でやってくださいということはできるんではないですかということを言っているんです。","respondent":"田中健康課長","answer":"事実上、それは無理です。対応できる診療所というのを特定してやってありますので、それから、無理だというふうに申し上げざるを得ないと思います。","id":"exchange-051"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そういう場合にはやりとりをちゃんとやっているわけですから、なぜ健診だけできないのかというのはさっぱりわからない。非常に少ないんですけれども、昨年までの受診率がわかったら教えていただきたいというふうに思います。","respondent":"田中健康課長","answer":"成人歯科検診のほうの対象者数ですけれども、各年齢で把握しておりますと、平成１４年の１月末現在で２万３,９７０名です。そのうち今年度の受診等も７０１件という数字でございまして、例年１,０００件から１,１００件程度ということで、現在予算計上しています。","id":"exchange-052"},{"speaker":"宮崎委員","kind":"質問","question":"今のは成人歯科検診ですか、歯周疾患のほうも合わせてか尋ねました。","respondent":"田中健康課長","answer":"今のは成人歯科検診ですけれども、現状は実は４０歳と５０歳については歯周疾患検診という形で内容をちょっと変えてありますので、それを一緒にした数字です。","id":"exchange-053"},{"speaker":"宮崎委員","kind":"質問","question":"早期発見、区のほうの感想はどうなんでしょうか、そこのところをまずお伺いしたい。そういう動機づけには非常に効果があるというふうに思っておりますが、こういうところでの内容の充実についてもあわせてお伺いしたいと思います。","respondent":"田中健康課長、寺西品川区保健所保健サービス課長","answer":"この６０歳でお受けになる方が非常に多くて、やはり若年層の方というのはどうしても検診を受けられる方の数が少ないのが現状です。当面はそういう意味合いでの若い方というのは… 例えば１本１本、本当は検診をした上で、そこをねらった撮影のほうがいいんじゃないかという意見もあるわけですね。だから、その辺も含めて、今後の検討課題ではないかと思います。","id":"exchange-054"},{"speaker":"宮崎委員","kind":"質問","question":"それとあともう一つは、年齢拡大のところでは、確かに６０歳、いわゆる仕事を定年してから治療を受ける方が非常に多いように私も伺っております。健康診査ですから、この啓蒙も含めてやるわけですから、ここのところの考え方をもう一度お伺いしたいと思います。","respondent":"田中健康課長","answer":"啓蒙といいますか、受診の勧めは一生懸命やらさせていただいてあります。そのころいろいろ健康学習等でいろいろな形の啓蒙等、検診を行っておりますので、そのような形でご理解いただきたいと思います。","id":"exchange-055"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ぜひ、内容の充実をしていただきたいということを求めて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"本多委員","kind":"質問・要望","question":"本会議の代表質問で、伊藤議員が質問をされましたことを踏まえまして、質問をさせてほしいと求めました。その変わったポイントというんですか、その重要的なところの経緯を教えていただきたいのと、その辺について教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"この検討と並行する中で、２３区は工場のある区もない区も相互に協調連携し、新たな清掃工場については必要ないという結論を出したわけです。特別区長会自治研究会第２分科会を中心に区長会での検討を行われた結果として、平成１５年１１月に、区長会におきまして。","id":"exchange-057"},{"speaker":"本多委員","kind":"質問・要望","question":"その検討に当たりましての、臨むに当たっての考え方、方針について教えてほしいと求めました。","respondent":"濱野助役","answer":"品川区は、いずれにしろ当分の間というのをまず短くとらえた上での物事を発想をするというのが品川区の基本として考えております。助役が助役会としてかかわる部分がありませんので、各論としてはそういうことでありますけれども、そういう態度で臨んでいるところであります。","id":"exchange-058"},{"speaker":"本多委員","kind":"質問・要望","question":"清掃一部事務組合の議員ということですから区議会の議長なんですが、それと、やはり答えができないという状態があります。やはり主人は２３区という特別区という立場でありますので、その仕事を全うしているということで、その点について教えてほしいと求めました。","respondent":"中山清掃リサイクル課長、高橋区長","answer":"当分の間ということで、とりあえず清掃一部事務組合の見直しについては検討されておりますが、当然２３区として地域。財政負担の問題、細かい部分のものは詰めておりませんでしたので、今後必要かというふうに認識しております。区長会でほとんど検討をしないで、それはそれとして、２３区がある区もない区も統一的にこの問題を処理していこうというふうな結論になったわけです。","id":"exchange-059"},{"speaker":"本多委員","kind":"質問・要望","question":"切り離していたものですから、どういうお考えがあるのか、お聞かせほしいと求めました。","respondent":"高橋区長","answer":"これから検討に入るわけですが、現在の清掃一部事務組合でいいかというと、いいという区は１区もございませんでした。それぞれこれからの清掃一部事務組合の改革につきましての具体的な問題を助役会で検討に入るわけですが、どのような抜本的な改革をしていくか。","id":"exchange-060"},{"speaker":"本多委員","kind":"意見","question":"今も２３区全体を、工場をとめる調整とかをやっておりますので、そういったことは各区でもう十分できるんじゃないかなと考えています。その辺につきまして、品川区の今までの取り組み等を含めまして、ちょっと感想をお願いしたいと思いますとの意見を述べました。","respondent":"高橋区長","answer":"知事が清掃業務につきましてどのような考えを持っているか、まだ直接聞いてございません。そういうようなことが言われるということは、持てなくなってきた、そのような考えが浸透しているんじゃないのかなという気がしています。","id":"exchange-061"},{"speaker":"大西委員","kind":"質問","question":"私は一つのルールというんですか、傾向と対策、このようなものがあるんじゃないかと思います。つきましては、今、区のほうでその発見に対する何らかの仕組み、こういったものはありますか尋ねました。","respondent":"小林品川区保健センター保健サービス課長、田中健康課長","answer":"「子育ての支援者があるかどうか」といった、そういったことで早期発見、予防という形で取り組んでいるところです。先ほど児童課長から説明がありました品川区児童虐待防止協議会というところで、これを児童相談所とつなぐという意味合いで連絡会を持ってあります。","id":"exchange-062"},{"speaker":"大西委員","kind":"質問","question":"そしてまた非常にテレビなんかで見ると、継母から逆に言えば継父というんですか、この大人が子どもを虐待するというケースが非常に見られるんですね。そして、何らかのそういう方法で行政が虐待を早急に発見するという明確な仕組みをつくるべきじゃないかと思うんですけれども、教えてくれますか。","respondent":"辻田児童課長","answer":"父親と母親を比べた場合には、実父以外の父親が虐待をしているというのが、いわゆる実母以外の母親よりはケースとしては多くなっている。品川、目黒、大田の３区に限って言えば、実母以外の母親の方がいじめをしている、虐待をしているという例は全然ございません。","id":"exchange-063"},{"speaker":"大西委員","kind":"質問・要望","question":"もし答弁される場合は、もう少し丁寧な答弁があってしかるべきじゃないかなと思いますので、これは要望としてお願いいたします。この点に関しての悪質商法の、今品川区における現状、これをちょっと教えていただきたいです。","respondent":"長田区民課長","answer":"屋根が、床下の防湿剤、こういったようなものを売りつけるようなものが大変横行をしています。こういったことが現状で、今年に入ってからの相談件数も、こういった部分の相談がかなり増えてきてあります。","id":"exchange-064"},{"speaker":"大西委員","kind":"質問","question":"手を挙げてということで洗脳しちゃうというんですか、そういう形で、あるところにみんな連れていって。そういう点の把握はなさっておられますか尋ねました。","respondent":"長田区民課長","answer":"今、委員のお尋ねの、駅頭なんかでキャッチセールスですとか、あるいは霊感商法、こういったものがやられているのも事実です。こういったものに対しては、私どもといたしましては、できるだけそういう被害に遭わないようにというようなことで、機会をとらえてＰＲをしています。","id":"exchange-065"},{"speaker":"大西委員","kind":"質問・要望","question":"これも要望ということにとめておきます。現実的には指導助手の数が少な過ぎて、少しこれは人数を増やしてきめ細かなサービスをしてもらえればと思うんですけれども、その辺どうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"嶋委員","kind":"質問・要望","question":"二つ目には２２９ページ、保健事業費、三つ目には ２３３ページ、精神保健費から地域生活支援センター整備についてお伺いします。四つ目には２６１ページ、公衆便所について、それから６番目にはペットボトル回収についてお伺いをいたします。","respondent":"田中健康課長","answer":"今のご質問の件は、区のほうのかかわりといいますか、ちょっとどこの事業かがわかないので、今もう一度お願いしたいと思います。","id":"exchange-067"},{"speaker":"嶋委員","kind":"質問・要望","question":"小児医療の拡充ということでスタートすることでお伺いをしていまして、これは品川区が、質問をさせていただきました。そういう意味で、本当に夜中の、品川区においても夜間休日ということで、診療事業ということで、このことについてお伺いをいたします。","respondent":"田中健康課長","answer":"今お尋ねの件につきましては、品川区のほうには内容的なものがまだ来てございませんので、申しわけありませんです。東京都がひまわりという医療情報で紹介システムを持ってありますので、夜間等はそれで対応することが可能というふうに以前から制度はあります。","id":"exchange-068"},{"speaker":"嶋委員","kind":"質問・要望","question":"小児医療の体制の充実、そういう意味では、近くから本当に小児科がなくなっていくということで、お母さん方が心配していることです。そういう意味で、小児科の確保と人材の確保という意味では、品川区はどのようにお考えか、お聞かせほしいと求めました。","respondent":"田中健康課長","answer":"品川区で小児科を標榜する病院が病院４カ所、診療所１１５カ所というふうになってあります。現在、こういう対応を品川区としては平成１４年１１月から開始したとか、そういう意味でのバックアップをさせていただいているところです。","id":"exchange-069"},{"speaker":"嶋委員","kind":"質問・要望","question":"二つ目の保健事業費についてお伺いをいたします。そういう意味では、平成１６年度の品川区の地域の保健サービスについて、お話を聞かせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう中で、私も一般質問で品川区の死亡は乳がんが１位ですが。今後お考えがあるのかをちょっとお聞かせをいただきたいと考えています。","respondent":"小林品川区保健センター保健サービス課長","answer":"その内訳といたしましては、くも膜下出血が３８、脳内出血が８２、脳梗塞が１８９です。地域の中での、これからは健康づくりプラン２１に基づきまして、さらにそういったことを区全体で推進していこうというふうに考えております。","id":"exchange-071"},{"speaker":"嶋委員","kind":"質問・要望","question":"駅から５分ぐらいですぐわかりやすいところで、本当に和気あいあいと仲よくやっていらしたということで、大変すばらしいなと思いました。今回つくられる、ちょっとわかっている範囲でよろしいですので、内容をお聞かせをほしいと求めました。","respondent":"田中健康課長","answer":"私ども品川区で初めての精神障害者の地域生活支援センターを現在計画しています。それから医療との関係等の相談、指導、助言、こういうものを目指して皆さんの社会復帰をバックアップしたいというふうに考えておるところです。","id":"exchange-072"},{"speaker":"嶋委員","kind":"質問・要望","question":"お考えをお聞かせをほしいと求めましたが、品川埠頭、またコンテナターミナルと大変すばらしい景観の京浜運河を持っております。東京都と連携プレーをしてぜひお願いをしたいなと考えていますが、そういう考えに対して考えをお聞かせをほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"ただいまの質問ですけれども、あそこの地域は埠頭地域ということで、港湾地区に限定されております。その中で、その辺も勘案して、今後の検討課題とさせていただきたいと思います。","id":"exchange-073"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひこのトイレの清掃とか、そういう整備をどのようにされていらっしゃるのか、お伺いをします。ぜひ物を置く場所をつくっていただきたいと考えていますが、その考えについて、お考えを説明するよう求めました。","respondent":"松代道路公園課長","answer":"新浜川橋のところの公衆便所だと承知しておりますけれども、反省しまして、すぐに今後きれいに清掃するように心がけたいと考えています。今後ちょっと検討させていただければと思います。","id":"exchange-074"},{"speaker":"嶋委員","kind":"質問・要望","question":"折り畳みの簡単な３０cmのものですので、ボルトやねじでつけられるものですので、ぜひご検討をいただきたいと考えています。それからあと、項目に公衆便所と書いてありますが、公衆トイレでは表現はいいのか悪いのかをちょっとお聞かせをほしいと求めました。","respondent":"松代道路公園課長","answer":"私どもの品川区公衆便所の設置および管理に関する条例とか、そこの中で公衆便所というようなことで、整理をしています。公衆便所もしくは公衆トイレというところもちょっとあろうかと思いますけれども、現状では公衆便所という形で呼ばせていただいております。","id":"exchange-075"},{"speaker":"嶋委員","kind":"質問・要望","question":"お考えをお聞かせいただきたいことと、それからあと、表から見えてスロープになっていてキャップを入れるところができているところがあるんです。そういうのを、これから品川区にもぜひ配置をしていただきたいと考えていますが、いかがか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"逆にプラスチックとしてのリサイクルができるようになっておりますので、周知はこれからはこれで徹底していきたいというふうに思っております。キャップを外す場所の設置、確かにそういうものがあれば、そういうお店等への持ちかけをぜひやっていきたいと考えています。","id":"exchange-076"},{"speaker":"西本委員","kind":"質問","question":"２３９ページのかかりつけ医機能推進事業と、それから２４７ページの品川区版環境にやさしいシステム、家庭ＩＳＯについてお聞きしたいと思います。事業の内容の変更点等々、今後どういうふうな形で進められていくのか、内容のご紹介をお願いします。","respondent":"田中健康課長","answer":"来年度一番大きな変更といいますか、かかりつけ歯科医制度、いわゆる医と同じような歯科医の区民からのニーズに応じた紹介制度をつくろうです。","id":"exchange-077"},{"speaker":"西本委員","kind":"意見","question":"どういう形で紹介をしていくのか、そこら辺はこれからどういうふうにつくられていくのか、ご説明をお願いいたしますとの意見を述べました。","respondent":"田中健康課長","answer":"受付も区が行い、実態調査をした上で、歯科医師会のほうにいろいろそういう派遣をお願いしようという内容でございました。今回新たに考えておりますのは、受付の段階から委託をして、そういう意味でのシステムを歯科医師会のほうでやっていただこうという考え方です。","id":"exchange-078"},{"speaker":"西本委員","kind":"質問","question":"そのリストの作成、紹介できる医者等のデータ等のシステム、それからいろいろな地域にいろいろな医者がいらっしゃると思うんですね。それは地域の歯科医師の方たちとのやりとりとかというのをこれからどういうふうな形をとっていかれようとしているんか尋ねました。","respondent":"田中健康課長","answer":"検討に向けまして、車いす対応ができるかとか、いろんなアンケートをとる作業を現在始めております。その中に、これから歯科医師会も以前から入っておりますが、より主体的に入っていただくという内容にこれからは考えていきたいと思ってあります。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"歯科になってきますと、なかなかその状況に合わせて、障害をお持ちになっている方の状況に応じて対応がいろいろ変わっていくべきだと。そこら辺を歯科医師会のほうで把握をし、適切な判断がされて、そこら辺はいかがか尋ねました。","respondent":"田中健康課長","answer":"それとも対応ができるか、そういう形の経験とか、対応能力も一応はとってあります。そういうものを含めて、どの部分までを紹介項目として区民のニーズにこたえられるかということは、これから整理をしていくという内容です。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"その辺も考慮していただいて、ぜひ区民のために有効に活用していただけるようにお願いしたいというふうに思っております。次に、学校ＩＳＯ、家庭ＩＳＯという形なんですが、これの内容、それから進め方をちょっとご説明をお願いしたいと思います。","respondent":"上山ＩＳＯ担当課長","answer":"学校ＩＳＯにつきましては平成１６年度から全校で実施をいたしまして、１年間の取り組みを終えた後、そういったことです。平成１５年度につきましては、また継続的な改善につなげていく、そういったことです。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"もう少し詳しくちょっと具体的なお話をいただきたいんですが、このプレス発表資料を見せていただきますと、平成１５年度のモデル校があったと。どういう内容だったのか、どういう取り組みでどういう効果があったので、ちょっともう少し具体的なところを教えてほしいと求めました。","respondent":"上山ＩＳＯ担当課長","answer":"品川版学校ＩＳＯにつきましては、今年７校でモデルを実施いたしました。エネルギー関係につきましては、全校での共通の取り組み事項ということで提案をさせていただいて、平成１６年度に向けて実践を図っていくものです。","id":"exchange-082"},{"speaker":"西本委員","kind":"質問・要望","question":"家庭に帰ってみますと、それだけお金がかからなくなるわけですから非常に目安的になりますし、広がっていくだろう。そこら辺のＰＲと、それから予算が計上されているんですが、どういったところにこれが使われていくのかをちょっと教えてほしいと求めました。","respondent":"上山ＩＳＯ担当課長","answer":"児童にとっても非常に理解されやすいし、４０校全校実施に当たりましても今回のモデル校の実施例を行っていきたいというふうに考えております。同じように、家庭版につきましても、環境家計簿的なことを盛り込みながら検討してまいりたいと思います。","id":"exchange-083"},{"speaker":"原委員","kind":"質問","question":"衛生費のほうは２３９ページに該当するのかなと思うんですが、薬物の乱用防止対策ということについてお伺いをします。商店街のほうの活性化になるんでしょうか、１６３号線絡みで一本橋商店街の中で、その中で生き残ろうとしている商店が何軒かあります。","respondent":"島袋品川区保健所衛生課長、市川産業振興課長","answer":"それからあとは、特別調査班を編成しまして、重点的な監視指導を実施していく。区のほうの取り組みですけれども、いわゆる脱法ドラッグに対するチラシを配って、知識普及を図っているところです。 大崎図書館の事項別の２００万円の内容につきまして、私のほうから説明をします。この２００万円は、先ほど大崎図書館でのビジネス支援の場面で、やはり今同じ情報でも国際化対応という面がかなりウエートを占めると思いますので。","id":"exchange-084"},{"speaker":"原委員","kind":"質問","question":"なぜ大崎図書館で始められるかというちょっと質問に対してお答えがなかったので、どういう形でされようとしているのか、お伺いをします。その辺のところは区としては何か役割ができるかどうかという、何かできるんではないかということなんですが、その辺いかがか尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"脱法ドラッグに関する調査の件ですけれども、区独自でやっているということではございませんけれども、東京都のほうで、最近先ほど委員のおっしゃったインターネットで買えるということで、それは都の研究センターのほうで調査をする、そのようなことをやっております。","id":"exchange-085"},{"speaker":"原委員","kind":"質問・要望","question":"東京都で、特に教育現場の場合は重要な課題を持つわけですので、ぜひそのところを力を入れていただきたいというふうに要望をしておきます。個々のお店の要望等々も聞きながら、今後の中で、個々のお店が寂れてしまわないような施策を打っていただきたいなというふうに思っております。","respondent":"古里品川図書館長","answer":"データベースについては、基本的に利用料は有料ですが、大崎図書館におけるサービスの展開の中では当面無料という形で進めさせていただきたい。その後の使用状況、有料等も視野に入れて検討していかなければならないかなというふうに考えております。","id":"exchange-086"},{"speaker":"原委員","kind":"質問","question":"最後にもう１点お伺いをするんですけれども、今後の中ではいかがでございましょう、あるんか尋ねました。","respondent":"市川産業振興課長","answer":"お尋ねの趣旨、そういうのと同じような観点でどうかというようなご質問の趣旨かと思いますけれども、実際には企業の選定がかなり難しいと思います。","id":"exchange-087"},{"speaker":"菊地委員","kind":"質問・要望","question":"２０％の否決率があるんだというお話がありましたけれども、少ないのか、この辺の見解を少しお話をしていただければなというふうに思います。それと、この融資返済の問題で、実際に産業振興課の窓口に相談に来るというケースがどれぐらいあるものか、その辺もお知らせを願いたいと思います。","respondent":"市川産業振興課長","answer":"いわゆる代位弁済率としては６％です。自分のところの経営にとって都合がよくなるのか、そういう相談は数としてはそんなに多くございませんけれども、散見できる程度の数はあります。","id":"exchange-088"},{"speaker":"菊地委員","kind":"質問","question":"どういう融資の制度がいいのかという、実際に融資そのものを借りる体力のない小さな企業に対する返済期限がものすごく長いようなこの融資というのを考えることはできないものかどうかというのが１点と、この点ではいかがか尋ねました。","respondent":"市川産業振興課長","answer":"返済期間を長くすると、必ずしも利用者にとって有利なわけではございませんで、例えば信用保証の判定のときに不利に働く場面もあります。これが何よりの私どもの実態把握の手だてだというふうに考えてあります。","id":"exchange-089"},{"speaker":"菊地委員","kind":"提案","question":"なかなか提案にはなっていませんけれども、そういう思いで今の融資の問題をお聞きしました。これは２日目でしたでしょうか、他の委員の方もお聞きしていたんですけれども、この辺の考え方をちょっとお聞かせを願いたいと思いますとの意見を述べました。","respondent":"市川産業振興課長","answer":"それから私ども行政にとっても、投じた資本の意味合いからすると、ロスにつながるものだという認識は持ってあります。ただ、個々の相談事例に応じてこれまでも対応してきたところですけれども、ここのところが一つのポイントになるもんだというふうに考えてあります。","id":"exchange-090"},{"speaker":"菊地委員","kind":"質問・要望","question":"一定程度１階の一部は店にしてほしいとか、そういう指導指針的なものを、もし可能であれば考えていただきたいなというふうに思います。一昨年、そこで出入りをしているのかどうかわかりませんけれども、この辺の指導の強化と連携がつくれないのかというのをちょっと説明するよう求めました。","respondent":"島袋品川区保健所衛生課長","answer":"直接私どもは警察権限がありませんけれども、衛生上の指導ということで、２人行きました。今後苦情がありましたら、また連絡をください、そういうような伝え方をやっております。","id":"exchange-091"},{"speaker":"菊地委員","kind":"意見","question":"何よりも住民の皆さんが怖いのは、先ほどの放火の話ですけれども、これによって事故が起きないかというのは心配だと思います。こういう問題が、悪質なケースというのかどうかわかりませんけれども、ぜひ指導の強化をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"木下委員","kind":"質問","question":"途中、その後どういうふうな対策をされるのかということをちょっと聞いておりませんでしたものですから、なぜかといいますと。大阪の家畜保健衛生所に引き取られたのが３日を要したというように、どういう対策をとられるのか、ちょっとお聞きしたいと思います。","respondent":"島袋品川区保健所衛生課長","answer":"そういう情報を把握した場合には、家畜保健衛生所のほうが職員を派遣して、ここが調査をするということになります。","id":"exchange-093"},{"speaker":"木下委員","kind":"質問","question":"こういう場合、例えば警察がそれを引き取った際に、すぐ消毒して回ったですとか、そういうのも紙面に書かれていたんですが、ただ聞いてそれをやるというだけじゃなしに、すぐ対応として、消毒ですとか、そういう何らかの処置というのはおやりになられるんか尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"インフルエンザが陽性だという場合には、当然家畜保健衛生所のほうで消毒等をやります。","id":"exchange-094"},{"speaker":"木下委員","kind":"質問","question":"時間もあることですので、次に移らします。これはカラス対策でもあると、平成１３年度比でカラス被害が半分になるという話を聞いたんですが、ここら辺をちょっとお聞かせ願えますか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"継続的にやっているから、平成１３年度に集積所の中で、要するに被害を受けた場所というのが約４％という数値でございました。こういうふうに年々減ってきているという数値です。","id":"exchange-095"},{"speaker":"木下委員","kind":"質問","question":"前年同期比に比べて１８％増加ですとか、新聞紙は約４４％増加ですとか、いい結果が出ている。持ち去り禁止条例ですとか、そのことについて区の考え方としてはいかが考えていらっしゃるのか、お聞きしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"したがって、この辺はまたあろうかと思いますが、実効性ある対応という形でこういう数字は出ていると思います。したがって、区としても、条例の検討もさることながら、実効ある対応というものをまず先行しようというのが現段階の考えです。","id":"exchange-096"},{"speaker":"木下委員","kind":"質問","question":"実効ある対応をしようということは、持ち去り禁止ということで、それはパトロールですとか、そういうのを行おうだとか、何か強化しようという意味合いか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"これは抜き打ち的に清掃事務所と本課のほうで連絡をとって、連携をとってやったこともあるんですが、これはなかなか毎日やるわけにはいかない。仮に継続的に見回るにしても、そういう行政が直接対応を、こういうことも考えていこうというふうに考えておる次第です。","id":"exchange-097"},{"speaker":"木下委員","kind":"質問・要望","question":"先ほどお話しされたような部分以外にも、やはりこういう条例ということで効果が上がるんだったら、それを前向きに検討してほしいと求めました。１日一生懸命やっても二、そういう方々、弱者の対策等なんかは少しは考えていらっしゃるのか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"抜き去りによって集積場、ステーションが荒らされてしまうであるとか、中には非常に地元の方に対して恫喝的な発言をするようなケースがある。あえて業者であるとか規模の大小だとか、そういう生活の状況によって、その辺を区分けしようという考えは持ってはございません。","id":"exchange-098"},{"speaker":"木下委員","kind":"質問","question":"八ツ山ですかね、北品川のほうの商店街の方々ですか、まちづくり協議会の方々が考えてやっていらっしゃる。区としてはお考えがあるのかどうなのか、またその応援等を考えていらっしゃるのか、ちょっとお聞かせ願えますか尋ねました。","respondent":"市川産業振興課長","answer":"それは一体本来だれの負担でセットするものなのか、そういったことによって、私どもの支援のあり方というのも決まってくると思います。その上で、行政としてどういう支援が可能なのか、こういった検討の手順になろうかと思います。","id":"exchange-099"},{"speaker":"木下委員","kind":"質問","question":"ただ、そういう集客するための大きな仕掛けといいますか、そうするのには、かなり資金的な部分が必要だと思います。音頭取りですとか、そういう部分でご協力していただければなというふうに思いますけれども、そういう点はいかがか尋ねました。","respondent":"市川産業振興課長","answer":"いわゆるソフト面での支援というのは幾つかあると思います。その商店街の底力に相当する商店街の基礎体力、これをまずつけることが必要だと思いまして、各種の支援策を講じているところです。","id":"exchange-100"},{"speaker":"木下委員","kind":"意見","question":"区のほうの考え方はよく理解できました。例えば六本木ヒルズなんかにしても、これからも商店街の活性化といいますか、基礎体力づくりにお力をかしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"},{"speaker":"田中委員","kind":"質問・要望","question":"私は大きく２点、そして２３９ページのかかりつけ医、歯科医の機能推進事業に関連してお聞かせをほしいと求めました。複数商店街のカードを持たずに１枚で対応がとれるというようなことが書いてありますが、改めまして、まずお聞かせをほしいと求めました。","respondent":"市川産業振興課長","answer":"単独にポイントカード事業を実施している商店街にとって、大体４年ないし５年でシステムのリニューアルという問題があります。その調査研究の結果として出てまいりましたのが、今回のＩＣカードシステム、こういった経過があります。","id":"exchange-102"},{"speaker":"田中委員","kind":"質問・要望","question":"まさにポイントのインフレ状態というんでしょうか、３点にしようという、そういったまた一方の懸念もあります。そういったものが今後求められてくるのかなと考えていますが、その点について、それぞれお考えをお聞かせほしいと求めました。","respondent":"市川産業振興課長","answer":"ＩＣカードの機能を活用すれば、複数の商店街、複数の商店街のそれぞれ違ったポイントカード事業の点数を積んでいくことができます。その上で、今委員からご指摘がありましたけれども、これが私ども一つ行政の役割かと認識をしています。","id":"exchange-103"},{"speaker":"田中委員","kind":"質問・要望","question":"ところが、一斉にやってしまったために、結果的には分散してしまって、それほどの成果は上がらなかったんではないかなという思いがあります。そのときに私も一般質問をした記憶がありますが、やはり区はどういうツール、その辺のお考えをお聞かせほしいと求めました。","respondent":"市川産業振興課長","answer":"その商店街はご自身でももちろん努力されるでしょうけれども、そのときの要するに道具立てとして使うようなこと、これも可能かと思います。ただ、そのときに、使うほうと使われたほうの利害なり思惑が一致するかどうか、この辺が今後の検討課題だというふうに認識しています。","id":"exchange-104"},{"speaker":"田中委員","kind":"質問・要望","question":"品川区商店街連合会も中心となって、このＩＣ機能をフルに活用し、まさにこの部分が今後大きなポイントになってこようかなと考えています。区の指導といいますか、ぜひ将来的なことに向けての抱負といいますか、意気込みをお聞かせをほしいと求めました。","respondent":"市川産業振興課長","answer":"大筋は間違ってはいないかと思いますが、行政と、それから品川区商店街連合会がそういう方向に向かって検討し始めたという段階です。今後の検討に当たりましては、今多々ご指摘のあった点も含めて、商店街の活性化につながる有効策として進めてまいりたいと思ってあります。","id":"exchange-105"},{"speaker":"田中委員","kind":"質問・要望","question":"いわゆる重複による副作用というんでしょうか、が心配されるということで、懸念があります。そういったものを解消していく上では、薬歴管理ということに対してどのようにとらえていらっしゃるのか、お聞かせをほしいと求めました。","respondent":"寺西品川区保健所保健サービス課長","answer":"例えば痛みどめと心臓の薬、成分が似ているとかいうことで、今言われたような副作用が出てくる可能性があります。今言われたように薬を一つのかかりつけの薬局を持たれて、区としてどういう仕事をしていくかということに関しては、今後の課題かなと考えています。","id":"exchange-106"},{"speaker":"田中委員","kind":"質問・要望","question":"まずは薬歴管理の必要性を広報していただくというんでしょうか、区民に対してその必要性があるということをお知らせをするという広報活動というんでしょうか、これは要望で質問は終わらします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"山路委員","kind":"質問","question":"３点目は２５４ページ、４点目は２５９ページ、チャレンジマート事業についてお伺いをいたします。平成１６年度の予算には載っていないんですけれども、その辺の衛生試験の機能はどういうふうになっているか、説明していただけますか尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"給水施設監視指導の件数のことですけれども、従来から予算書のほうには件数は載っていなかったです。","id":"exchange-108"},{"speaker":"山路委員","kind":"提案","question":"家庭版ということで、平成１２年の第２回定例会以来、細かく提案をしてまいりました。内容につきましては先ほど西本委員のほうから細かく質問があり、どういうふうに検討されているか、ちょっとお聞かせほしいと求めました。","respondent":"上山ＩＳＯ担当課長","answer":"生徒と家庭への還元をどのように考えているかですけれども、先ほども申し上げましたように継続的な改善ということに大きく特徴を持っております。環境にやさしい家庭づくりを取り組んでいるということで、表彰等を含めました認定証をお配りするということで考えているところです。","id":"exchange-109"},{"speaker":"山路委員","kind":"質問・要望","question":"区の取得にも、情報のネットワーク化をさらに進めて環境に取り組んでいってほしいと求めました。それについてちょっと認識を説明していただけますか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"廃棄物、ごみの減量等と言われておりますけれども、基本的にはもうなくすことを目指す、廃棄物ゼロを重大な使命、目標として、いろいろな取り組みをやっていくという取り組みであるというふうに認識しております。","id":"exchange-110"},{"speaker":"山路委員","kind":"質問・要望","question":"日本におきましても、国立研究機関と名古屋市とか、市町村も参加しているんですね。関東にもごみをなくしていこうという研究構想があるそうですが、それにつきまして、お知りでしたら、ちょっと説明してほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"ゼロエミッションというのは、非常に企業、自治体の中にも目標としてという部分はありますが、組織立ってそういうものが立ち上げられているのは、申しわけございませんが、情報をまだ入手してございません。","id":"exchange-111"},{"speaker":"山路委員","kind":"質問・要望","question":"さらに資源型、ごみを少なくしていくシステムが可能になってくるかと思いますので、研究をしてほしいと求めました。続いて、チャレンジマート事業につきまして説明をしてほしいと求めました。","respondent":"市川産業振興課長","answer":"比較的広い幅で事業内容が決められる制度です。施設改修費１,０００万円、こういったものを補助いたしまして、家賃補助のみ３年間継続いたします。","id":"exchange-112"},{"speaker":"山路委員","kind":"質問","question":"こういう地元で商品が買えて、高齢者ばかりなので、そういうふうにしたい。その地元にない品物を売ってくれる、そこで売ってもらうような調整をできないかという話があったんですが、どのようにお考えか尋ねました。","respondent":"市川産業振興課長","answer":"結論から申し上げると、なかなか難しい問題かと思います。こういったものが非常に関連してまいりますので、私どもその相談に乗っていく、こういう体制にはあります。","id":"exchange-113"},{"speaker":"井上委員","kind":"提案","question":"２４５ページ、そして２４６ページ、２５４ページの廃棄物対策費について伺います。消費者の声を入れて策定することを提案しておりましたけれども、そしてまた、市民との意見交換の時期というのが未定ということになっておりましたとの意見を述べました。","respondent":"島袋品川区保健所衛生課長","answer":"集団給食施設、このようなものとか、それから過去に食中毒を起こした業種につきまして重点的に監視をしていこうという考えです。この中に遺伝子組み換えに関する表示の問題等を重点的に監視項目としていきたいなと考えているところです。","id":"exchange-114"},{"speaker":"井上委員","kind":"質問・要望","question":"意見交換の時期が未定ということで、お答えがなかったんですけれども、ちょっとあとがたくさんありますので、後ほど伺わせてほしいと求めました。平成１８年度末全域に拡大されたときに、この小型プレス車はどのぐらいの見込みをされているのかということを説明するよう求めました。","respondent":"島袋品川区保健所衛生課長、中山清掃リサイクル課長","answer":"例年消費者懇談会というのをやっておりますので、それを今年もやったんですけれども、ちょっとやり方をいろいろ考えて、工夫してやっていきたいと考えています。いわゆる雇い上げの車両の分の各戸収集の対応部分を入れているわけではありますが、今後の効率というのも見えてまいると思います。","id":"exchange-115"},{"speaker":"井上委員","kind":"質問","question":"各戸収集の拡大によって増える分というのは、少し見込みとしてはわかりますか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"約７割というところでこの１０台というのが出ておりますから、これにもう数台加算かなというふうには思われます。","id":"exchange-116"},{"speaker":"井上委員","kind":"質問","question":"平成１３年度の場合には、ふれあいサポートシステムとの連携という事業が各戸収集にはついておりましたけれども、この事業についての連携というのはどうなっているんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"平成１３年度のときにご報告申し上げたのが、これは全域であらかじめ清掃事務所で受け付けて、ご家庭までとりにいきますというのをやりました。この情報を清掃事務所から送っていく、こういう意味の連携ですので、これについては引き続きやってあります。","id":"exchange-117"},{"speaker":"井上委員","kind":"質問","question":"取り組みをされている方から伺う中では、往来にごみが並んでいるということで景観上見苦しいというような声もあるんですね。その中で、２億円の経費を今回１億９,７００万程度あるわけですから、これによるごみの減量の効果をどのように推測されていますか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"モデル実施をやった際に、６ないし８％ほどのごみの減量という数値が出ておりました。ただ、このエリア的な検証というものは確かに課題かと思いますので、いろいろとデータのとり方を工夫してまいりたいと思います。","id":"exchange-118"},{"speaker":"井上委員","kind":"質問・要望","question":"それから、ペットボトルの回収の拡大なんですが、２００４年度１０月からペットボトルの回収を全集積所１万５００カ所で始めます。それで、資源回収で、とりわけペットボトルの資源化コストは一番かかるんですけれども、拡大に踏み切った基本的な考え方を、示すよう求めました。","respondent":"中山清掃リサイクル課長","answer":"現在、ペットボトルの区のかける収集単価が１００円を若干割り込んでくるぐらいになっております。かなり中間処理のコスト等もこの間下げられる見込みも出てまいりましたので、今回もう思い切って全面的に集積所回収を進めようと判断した次第です。","id":"exchange-119"},{"speaker":"井上委員","kind":"質問","question":"もう少し区民の方も知るべきだと思うんですけれども、また梱包機材をどうするのかという問題がもう既に持ち上がっているかと思うんですけれども、またこれにともなう車両雇上費の予算はどのくらいかかっていくと考えていらっしゃるか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"今回の実施は１０月からですので、単純に言えば、年間を通じれば２倍近くかかってくるというふうな予算です。したがって、これは雇い上げではなくて、基本的に委託でやる予定ですので、これが集積所の回収分の総経費というふうに考えられます。","id":"exchange-120"},{"speaker":"井上委員","kind":"質問・要望","question":"自治体が資源回収に頑張れば頑張るほど税金の負担をそこに強いられていくということを、やっぱりもっともっと区民の方々が知ってほしいと思います。しないように決めた自治体もある中で、この流れとしては逆に進んでいるのではないかということに対してどのようにお考えになりますか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"ただすべて単価で考えていくのであれば、やはり一番考えていくべきなのは、望ましい資源回収を充実していくべきかなと思います。したがって、午前中の鈴木真澄委員のご質問にも答えましたとおり、事業者の負担の明確化は別の場面では訴えていきたいというふうに考えております。","id":"exchange-121"},{"speaker":"井上委員","kind":"質問・要望","question":"やっぱり企業がリサイクル費用を負担をする仕組みを徹底することを自治体からさらに要望してほしいと求めました。次はノーレジ袋啓発推進事業について伺います。","respondent":"金井環境課長","answer":"その結果として、ごみの減量と資源の節約につなげていく、こういう基本的な考え方で実施をしているものです。","id":"exchange-122"},{"speaker":"井上委員","kind":"質問・要望","question":"早速事務事業評価がＣということになっておりますけれども、どうしてスタートして２年目でＣなのかという理由をお答えほしいと求めました。見直しの段階では三つ項目がありますが、この三つのうちのどの見直しする事業ということになるのか尋ねました。","respondent":"金井環境課長","answer":"ここでも説明にも書いてあると思いますけれども、１年数カ月ですけれども、そのための見直しをするということでＣというふうになっております。","id":"exchange-123"},{"speaker":"井上委員","kind":"質問・要望","question":"かごに入れればいいようなものがあったんですが、最近それが見当たらなくなったというような気がしているんですね。削減によってＣＯ2がどれだけ削減されたのかということも、子どもたちに知らせるとか、そういった意味でぜひ頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"須貝委員","kind":"質問","question":"２４９ページのリサイクル活動についてと、２６１ページ、産業振興についてお伺いいたしたいと思います。その品川区にとって、ごみの減量対策としては現在最も重要な手法であると思いますが、その辺のご見解をまず説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"例えば建設時からまちづくり事業部のほうと連携をとって、保管の場所、ルールを決めていくような連携をとっているです。","id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"いわゆる抜き取りですか、もう時代の流れとしてはどうなんでしょう、リサイクルも民間事業化に進んでいるんじゃないか。ちょっと環境清掃事業部としてご意見をお伺いしたい。","respondent":"中山清掃リサイクル課長、市川産業振興課長","answer":"これについては、もう区からきちんと依頼をした委託業者である契約業者である、こういうものとのかかわりの中でやっていくべきかと思います。先ほどのちょっとご質問の中で答えるべきだったかもしれませんが… 一般論ですけれども、地域雇用が創出されるという前提は、やはりその地域社会のコンセンサス、これが前提になると考えています。","id":"exchange-126"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういう方向性をもう考えてもいいんじゃないかなということで、考えていただきたいということで要望しておきます。共通商品券ですか、それの原点としまして、商店街の活性化はとりあえずお客さんが来てもらうということが第一だと思うんですね。","respondent":"市川産業振興課長","answer":"この今申し上げたことをいかに年間を通じて継続していくか、施設環境の整備、こういったものがあろうかと思います。そういったことで商店街の活性化ということを考えているつもりです。","id":"exchange-127"},{"speaker":"須貝委員","kind":"意見","question":"最後に、ちょっと後継者の育成について、私の考えもあるんですけれども、どうかなと思いまして、産業振興課の意見をお聞かせ願いたいと思います。その辺をちょっとお考えを説明するよう求めました。","respondent":"市川産業振興課長","answer":"一つの方策として、一般的にこの品川の地というのはビジネスの立地環境としては非常にすぐれた土地であると認識しています。そういった特性を生かして、そういう後継者の育成という場面に使えるものがあれば、今後ひとつ検討させていただきたいと思います。","id":"exchange-128"},{"speaker":"石田委員","kind":"質問","question":"犬と猫の致死処分についてと、あとは飼い方の教室みたいなことを後で伺いますので、資料を調べておいてもらえればありがたいと思います。ここら辺のところで、どうやって広げていくかということを考えていらっしゃると思うんで、そこら辺の考え方を説明するよう求めました。","respondent":"田中健康課長","answer":"各地域に今回モデル実施ということで、ふれあい健康塾という形を定期的な軸となる活動ということで始めさせていただこうと思ってあります。地域の実情に合わせて、これからもいろんな活動がミックスされていきながら、健康づくりも取り組んでいただけるように考えてあります。","id":"exchange-129"},{"speaker":"石田委員","kind":"質問・要望","question":"どんどん後押しをしていってほしいと求めましたが、これをもう一段発展させていくという考えもあると思うんですね。週２回、千葉なんかは２年間実績をとると、そういう形で一体で筋トレも入れていくような考えというのはないんか尋ねました。","respondent":"田中健康課長","answer":"これは以前からご利用の人気が高く、そういう意味ではどんどん伸びておりまして、平成１５年度から１６年度にかけましても２教室を増やそうです。","id":"exchange-130"},{"speaker":"石田委員","kind":"質問・要望","question":"これは要望にしておきます。年に２回ぐらいやっているのかどうかわかりませんが、そこら辺の点をちょっとお聞きしたいのと、説明を求めました。","respondent":"島袋品川区保健所衛生課長","answer":"それで、我々区のほうは、区の獣医師会と協力しまして、犬のしつけ教室を年に３回やってあります。そのときに犬、猫も含めまして、ほかのペットも含めまして相談をしています。","id":"exchange-131"},{"speaker":"石田委員","kind":"確認","question":"ちゃんとそういうところで検証も１回してほしいなと思うのと、この致死処分をどうしてかと、もう時がたつとだめというのがありますね。猫が結構いるというような話を聞いたんだけれども、それはうそか本当かわからないので、そういうのは確認されているのかどうか説明を求めました。","respondent":"島袋品川区保健所衛生課長","answer":"私どものほうで、よく電話で犬とか猫を引き取ってくれないかという相談があります。今、委員のおっしゃった業者云々というのは、ちょっと承っておりません。","id":"exchange-132"},{"speaker":"石田委員","kind":"質問","question":"東京都だけでそれですから、少しそういう飼い方とかそういう教室の中で、大切に育ててくださいよというようなことを言ってほしいと求めました。一般財源で行くなら一般財源で行く、今後ここの出ている項目とかここで使っているものの考え方、どういうふうにしていこうと思われているのか。","respondent":"榎本行財政改革担当課長","answer":"それで、継続的に３年間で終わる事業もありますけれども、それ以外に今後とも継続していかなければいけない考え方に基づくような事業もあります。","id":"exchange-133"},{"speaker":"石田委員","kind":"意見","question":"ここの部分はないから、違うところで全部そういう補完をしていくのか、一つだけとると少なくなっちゃうわけですよ。そこら辺の考え方もどういうふうに考えてられているのかとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"ほかの事業についても幾つか平成１６年度から始まるものもありますので、その事業の必要性というところでは、その必要性のあるものについては継続してやっていくような考えです。","id":"exchange-134"},{"speaker":"石田委員","kind":"意見","question":"１億２,０００万円、１億１,０００万円という形でやっていまして、ここに幾つかある。来年度もこれぐらいの規模で残していこうというお考えなのか、一つずつとったら減っていっちゃうから、そこら辺の点をもう一度改めてとの意見を述べました。","respondent":"市岡企画財政課長","answer":"あるいは戸籍の電算化のように、なかなか踏み切れなかったものを、むしろこちらの計画に合わせてこの制度を使ったという性格があります。","id":"exchange-135"},{"speaker":"山村委員","kind":"質問","question":"そして２３９ページの保健所管理運営費、２５６ページ、中小企業対策費についてお伺いしたいと考えています。そういう意味で、鳥のふんの有害性とかそういうことは、どのようにとらえているのか教えてほしいと求めました。","respondent":"寺西品川区保健所保健サービス課長","answer":"鳥インフルエンザのウイルスは、ふんに含まれることは事実です。ですから、今一般的にこの東京近辺の鳥のふんが同様のウイルスを含んでいるかどうかに関しては難しいところだと思います。","id":"exchange-136"},{"speaker":"山村委員","kind":"質問","question":"ということは、東京のほうまで鳥インフルエンザのカラスが蔓延するようになってきたときに、鳥のふんの処置をある程度していかないと、鳥のふんから人間に感染するという可能性が出てくると思うんですが、その対策とかは今考えられておりますか尋ねました。","respondent":"寺西品川区保健所保健サービス課長","answer":"まだ確証のいける発言ができるような状況にないことは皆さんご承知のとおりだと思います。ただ、今現在でもタイとベトナム以外では全く報告されていない事実から考えて、これから区民のほうに訴えていこうかなと思っているところです。","id":"exchange-137"},{"speaker":"山村委員","kind":"意見","question":"それと、それと、感染症を想定した危機管理マニュアルをつくる予定はあるのかということです。鳥インフルエンザは１９２５年スペイン風邪が、それに対しては、どのように考えていらっしゃるかというのをまず最初にとの意見を述べました。","respondent":"寺西品川区保健所保健サービス課長","answer":"鳥あるいは家禽、アヒルであるとか、そういうものに関しての感染力は非常に強いんですが、いわゆる犬であるとか哺乳類のほかの動物に非常に感染力が高いということは現状証明されていないのではないかなと思います。","id":"exchange-138"},{"speaker":"山村委員","kind":"意見","question":"わかりました。これからは、ＳＡＲＳおよび鳥インフルエンザなどの感染症を想定した危機管理マニュアルというものをつくる予定がありますかどうかをお答えくださいとの意見を述べました。","respondent":"島袋品川区保健所衛生課長","answer":"昨年度、健康危機管理マニュアルというのを保健高齢事業部内でつくっておりまして、いわゆる健康危機管理マニュアルをつくっております。それで、感染症についても、感染症が原因が不明のときは健康危機管理マニュアルで職員は対応するということになってあります。","id":"exchange-139"},{"speaker":"山村委員","kind":"質問","question":"飼い猫の去勢不妊手術の助成なんですけれども、先ほど石田委員の質問にもあったように、野良猫が多いという部分があるような気がするんですね。川崎とかだと１００％助成なんですが、今後増加するような考えはあるのかどうかを教えていただけますか尋ねました。","respondent":"田中健康課長","answer":"飼い主のモラル、いわゆるペットの適正飼養を、より区民の皆さんに理解していただくことが一番大事かなと思ってあります。捨てないということであれば、六年ということなんで、そういうモラルの向上をやはり図ることが大事なことかなというふうに思ってあります。","id":"exchange-140"},{"speaker":"山村委員","kind":"質問","question":"増加するかどうかということを質問させていただいたんですが、さまざまなペットが現在品川区でも飼われていると思いますが、犬以外の動物に関して登録というものをするようには考えられているのかどうかを、答えるよう求めました。","respondent":"島袋品川区保健所衛生課長","answer":"法律で狂犬病予防法というもので定められて、犬の飼い主はある一定期間の間に登録しなければなりません、そういう法律で決められたものです。","id":"exchange-141"},{"speaker":"山村委員","kind":"質問","question":"そうしますと、結構危険な肉食獣系のペットを飼っていても、品川区等ではわからないということなのかもしれないんですが、今後は国がやっていないからというのではなく、何かしら考えて、ある程度、鳥などのペットについても把握するのは必要かと思われるんですが、どうか尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"そういう考えがあるです。すべてを把握するのは難しいだろうと考えております。","id":"exchange-142"},{"speaker":"山村委員","kind":"質問","question":"今後はいろいろと考えて、案を出して練っていただければと思うんですが、次に２３９ページの保健所管理運営費に関してお聞きしたいと考えています。この保健所長に医師免許以外の人をつけてもいいようにするかどうかということに関しては、どのようにお考えか、教えていただければ。","respondent":"青山品川区保健所長","answer":"厚生労働省の保健所長のあり方検討会の中で検討が進められておりまして、それで、本年度中に結論を出すべく最終的な詰めが行われているところです。そして、保健所長の行政能力等を含めまして、それを高めていくという方向で検討を進めていきたいというふうに出しております。","id":"exchange-143"},{"speaker":"南委員","kind":"質問・要望","question":"一つ目は、子どもたちの健康を大気汚染からいかに守るかということで、新たな施策をぜひともつくっていただきたいという立場で質問したいと思います。東京都の医療費の助成制度、あるわけですけれども、この数年間のこの助成を受けていらっしゃる方々の数字を改めてご紹介してほしいと求めました。","respondent":"田中健康課長","answer":"これは東京都の条例で１８歳未満の慢性気管支炎、気管支ぜんそく等の認定の方に医療費の助成がされていることですが、最近の認定件数です。平成１３年度が１,３８０件、平成１４年度が１,３５９件、ちなみに平成１６年２月は１,２９８件というふうになってあります。","id":"exchange-144"},{"speaker":"南委員","kind":"確認","question":"１,２９８件という最終的なところの数はあれですけれども、しかし、１,３００件台、数年こういうふうな状況というふうに言えると思うんですね。いただいている公害の資料を見せていただいて改めて確認したんですけれども、環境課長のほうからちょっと教えてほしいと求めました。","respondent":"金井環境課長","answer":"その地点がちょっとよくわかりませんけれども、八潮に測定局を設置をしておりますけれども、これは一般大気の測定局です。ここは窒素系とＳＰＭも測定しておりますが、環境基準を一部達成したこともありますけれども、現在は達成してございません。","id":"exchange-145"},{"speaker":"南委員","kind":"質問","question":"２点お伺いするということで、２点目をなかなか申し上げなかったんですが、八年前の１９９７年当時に。１月１９日に環境施設組合の方々が品川区を訪問されて、区でどういうふうな見解で変化されたのか、そこを伺います。","respondent":"金井環境課長","answer":"それから検討経過、こういう形で処理をしたいという流れが方向性がかたまっているので、何とかご理解をいただきたいということでございました。これ以上区として法的に明確な拒否する根拠がない以上、拒否できない、こういう立場で了承したです。","id":"exchange-146"},{"speaker":"南委員","kind":"確認","question":"爆発が実際にあるわけですから、こういう危険な状況をどこまで私は品川区としてはきちんと確認されたのか、そこもちょっと伺いたいと思うんです。そして、本当にこの技術は大丈夫なのかというところをどこまで確認されたのか、そこをちょっと伺いたいと思います。","respondent":"金井環境課長、田中健康課長","answer":"基本的にはそうした技術検討委員会で、大阪府なり環境施設組合が検討した結果、これは区がどうのこうのということにはなりません。そちらの施設あるいは技術検討委員会が十分検討し… 私どもは、保健所保健センター等で４カ月から３歳児までは乳幼児健診というのを皆さんにやってあります。","id":"exchange-147"},{"speaker":"南委員","kind":"質問・要望","question":"私は安全確認はとるべきだというふうにお話しし、そしてきたという、そういうことが改めてはっきりしました。その確認をちょっとしたいのと、処理の中間、これについてはどうか尋ねました。","respondent":"松本環境清掃事業部長","answer":"そういう意味では８００度以上の熱で分解処理をして、なおかつあそこの産業廃棄物処理会社の施設は溶融施設を持っています。区民感情を考えると、地域的なものではなくて、私どもは受け入れるべきと考えています。","id":"exchange-148"},{"speaker":"三上委員","kind":"質問","question":"２４６ページですね、それから２３３ページの食品衛生推進員事業になるのか母子保健指導費になるのか、ちょっとお伺いしたいと思います。時間の関係によっては２４７ページの緑の保全事業ということで、お伺いしたいと思います。","respondent":"市川産業振興課長","answer":"ただ、何が確定的な汎用性なのかというのも、全くこれは難しいところが現実あります。そういう経費のシステムということを一緒に考えていかないと、なかなか先に走っていただけるところが出ない、こういう現実があると考えています。","id":"exchange-149"},{"speaker":"三上委員","kind":"質問","question":"ですから、商圏を守ろうとすれば、一緒にはやりたくないという気持ちだって当然起きてくる。そこらあたりをもう一度しっかりと、どういうふうに取り組んでいこうとされるか、お伺いしておきたい。","respondent":"市川産業振興課長","answer":"一つの検討の選択肢として提案するに際しては、そこの差が、例えば武蔵小山の場合にはカードが１５万枚あるいは２０万枚というロットになります。","id":"exchange-150"},{"speaker":"三上委員","kind":"質問","question":"先行して取りかかろうとするところですから、今後十分協議し、やはり喜んで参加していただけるということであるようにお願いしておきたいと思います。ペットボトルの質疑を私もずっと何回かやってまいりましたけれども、現在でも全国平均での回収率というのは４０％程度か尋ねました。","respondent":"中山清掃リサイクル課長","answer":"国の直近のデータはちょっと時間が、すぐ出ればと思いますが、全世界でトップ水準になってきているということで、たしか回収率が５割に達したかというふうな報道があったかと思います。","id":"exchange-151"},{"speaker":"三上委員","kind":"質問","question":"私が以前に質問したときは、平成１２年、拠点回収を今回１万５００カ所でやるという予定でありますよね。数字的な目標値は出ていますけれども、これでいった場合には、どの程度の品川区の回収率というのは上がってくるんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"区の中での発生数という分母がなかなか把握ができませんので、ちょっと今すぐには積算できないかと思います。現在区の資源化率が、区の回収部分で言えば約２割を超えておりますから、それがまた上がってくるのかなというふうに思っております。","id":"exchange-152"},{"speaker":"三上委員","kind":"質問","question":"このプレス発表の資料によると、平成１６年度は７００万ｔと読んだらいいんでしょうか、相当上がるというふうに書いて説明していますよね。今のお話を伺っていると、期待の目標値になっているのではないかなという感じがするんですけれども、どうなんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"それで、品川区のこの目標ですけれども、ここに書いてありますように集積所回収を１０月から全面にやることによって３５０ｔが増える。これが４００ｔ近くになっておりますから、多少その分の影響減があったとしても７００ｔを超えるというふうに見込んでいるものです。","id":"exchange-153"},{"speaker":"三上委員","kind":"質問・要望","question":"どちらにしても、しっかりと取り組んでいっていただきたい、こうお願いしておきたいと思います。それから、公衆便所の件でありますけれども、小破修理というのはどのような修理というのが一番多いんか尋ねました。","respondent":"松代道路公園課長","answer":"公衆便所の小破修繕です。これは主にやはりいたずらによるドアを壊されましたり、詰め物をされましたり、あとはガラスを割られましたり、そういったものが主な修繕項目です。","id":"exchange-154"},{"speaker":"三上委員","kind":"質問","question":"そういった修理ということがほとんどだということであれば、要するに便器そのものの水の関係とかといういたずらというのは、そうはないんでしょうか。特にちょっとお伺いしておきたいのは、今どれぐらい比率的に、具体的な数字が出ればいいんですけれどもいかがか尋ねました。","respondent":"松代道路公園課長","answer":"数字的なものはちょっとつかんでおりませんけれども、従前は便器等もよく壊されました。例えば手洗い、蛇口等のいたずらによる損傷、修繕等は少ないというふうに承知しています。","id":"exchange-155"},{"speaker":"三上委員","kind":"質問","question":"やはり公園を中心にする、どちらかというと公共施設をずっと見ていったときに、古い施設なんかを見ていてもまだ和式というのが相当ありますよね。やはり公衆便所も同じ形態のほうが多いというふうに見ていていいんか尋ねました。","respondent":"松代道路公園課長","answer":"洋式の便所もごくわずかですけれども、設置等々を検討してつけたところもあるんですけれども、ほとんどが和式です。これは、現状のところでは和式のほうがほとんどだというふうに承知しております。","id":"exchange-156"},{"speaker":"三上委員","kind":"質問","question":"ところが基本的には手でやってほしいという、本当は理事者の皆さんにあなたはどういうタイプですかと伺ってもいい話なんですけれども。私も悩むんですけれども、どうか尋ねました。","respondent":"松代道路公園課長","answer":"先ほどの質問の中で和式と洋式便器というところでのちょっと補足で説明しますが、だれでもトイレというものをつくってあります。私どもとしては、なるべく手を使っていただいて負担のないような形で流していただくのが本来の使い方かなというふうに思ってあります。","id":"exchange-157"},{"speaker":"三上委員","kind":"質問","question":"今、言われてきているのは、和式トイレの出荷数というのは全体のもうほぼ１割にも満たなくなってきている。やはり公衆トイレももう一度見直す時期にも来ているんじゃないかな、こういうふうに思えるんですけれども、いかがか尋ねました。","respondent":"松代道路公園課長","answer":"従前から計画的に古いトイレ等は改修をしています。洋式、どういうふうにしていくのか研究課題とさせていただきまして、検討させていただきたいと思います。","id":"exchange-158"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私のほうからは、２４９ページの資源回収に関連して端的にお伺いいたします。それからさまざまな市場等を十二分に調査しながら対処していくべき、つまりはめり張りをつけていくべきと考えますが、いかがか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"基本的には今委員のおっしゃるとおりだと思います。そういう部分で言えば、今おっしゃったような、めり張りをつけての対応というのが基本かと思います。","id":"exchange-159"},{"speaker":"伊藤委員","kind":"質問・要望","question":"何点か確認をさせていただきたいんですが、一つは、その区長会に対する助役会の回答期限はありますでしょうかということを一つお伺いしたい。助役がぜひこの助役会をリードしていただきまして、なるべく早く回答案を区長会に上げていっていただきたいと思うんですが、いかがか尋ねました。","respondent":"濱野助役","answer":"都の職員を平成１８年度から今度受け入れるわけですので、その辺あたりが一番急がれる問題というふうに考えてあります。その他については、結果としては恐らく幾つかに分けて中間報告という形で区長会のほうに上げていくようになろうかと思います。","id":"exchange-160"},{"speaker":"伊藤委員","kind":"質問","question":"それから、２３区は東京都の内部団体であるという発言とか、いろいろ出てきております。いかがでしょうか、そのことに対する区長の感想をぜひお伺いしたいんですが、いかがか尋ねました。","respondent":"高橋区長","answer":"清掃一部事務組合が最少限度どの程度必要なんだろうかというふうなことの検討に、これから入っていくものじゃないかと考えています。これからの清掃一部事務組合また清掃の事業のあり方というものを検討していかなくちゃならないんじゃないかと考えています。","id":"exchange-161"},{"speaker":"伊藤委員","kind":"質問・要望","question":"その立場でぜひ指摘をしていただきたいということをお願いしておきます。ほかの２２区も今の清掃一部事務組合だったらいけないとみんな思っているということですから、それから戦略、いかがか尋ねました。","respondent":"高橋区長","answer":"品川区はかなり過激なものを言い過ぎることもしばしばございまして、２２区で、また品川区は何かあるのと言われることがしばしばあります。だけれども頑張ってまいりたいと考えています。","id":"exchange-162"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/906948?Template=document&Id=828#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":127757,"voices":384}},{"id":"h16-20040312-3","meetingId":"h16-c-budget","date":"2004年3月12日","dateIso":"2004-03-12","committee":"予算特別委員会","time":"午前１０時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を137件整理しています。","topics":[{"id":"topic-01","title":"◯林（宏）委員長 おはようございます。ただいまより予算特別委員会を開会いたします。 第５号議案、平成１６年度品川区一般会計予算","agenda":"◯林（宏）委員長 おはようございます。ただいまより予算特別委員会を開会いたします。 第５号議案、平成１６年度品川区一般会計予算","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"１項土木管理費のうち、２６７ページの、駅周辺等放置自転車対策費についてお伺いをします。そういう現状についてどのようにお考えになり、また、どのような対策を講じられているのでしょうか、お答えをお願いいたします。","respondent":"奈良交通安全担当課長","answer":"多分委員ご指摘の点は、私道上の部分だと思うんですけれども、私道につきましては、基本的には禁止区域はかけておりません。そこをかけた場合に、私道部分を管理している全員の方のご理解が得られれば、禁止区域についても検討はしていきたいというふうに思っております。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"私道に関しまして、私道の周りには４階とか５階建ての意外と階数の少ない集合住宅があります。４階、５階、そこのところの正確なところをお教え願えますか尋ねました。","respondent":"浜脇住環境整備課長","answer":"そういった建物が建った際には、付置義務といいますか、要綱上のお願いをしています。もしかすると、あるいは敷地が１,０００m2以下の場合がそういうのに該当して、設置していないという状況が見られることがあるかもしれません。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"これはどうにか対策を講じてもらわないと、そこの部分をご斟酌の上、今後の放置自転車の巡回のほうをお願いしたいと思います。まちの中のいろいろと困りごと、生活安全ですから、困りごとということに対処する目的も少なからず要素としてあると思います。","respondent":"奈良交通安全担当課長","answer":"ただ、将来的には生活安全サポート隊と、区の撤去活動等をうまく連携を図っていかれればいいなというふうな感じはしております。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"連携が明確になりました。警察行政といいますか、関係機関に対してお手伝いができるのか、どの程度までというのを教えていただけますか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"次、自転車の返還率を簡単にお伺いします。ところが、委託返還という部分で、返還率を上げるにはどのようにしたらいいのか、簡単に教えていただけますか尋ねました。","respondent":"奈良交通安全担当課長","answer":"品川区は昨年は４７.１％ということで、２３区平均から比べますと１０％ぐらい低いという状態が続いております。１１月、１２月の３カ月をとってみましても、これが徐々に２３区内の平均である５８％にどんどん近づけていきたいというふうに思っているところです。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"これからも各委員から放置自転車の問題が出ると思いますが、放置自転車は、品川区のみならず、２３区が抱える問題であります。いろいろと問題のところがありますが、今後とも自転車問題よろしくお願いを申し上げまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"若林委員","kind":"質問・要望","question":"２８３ページの公園関係、２８５ページの大崎駅周辺地区再開発をご質問します。そこら辺の結果をお知らせてほしいと求めました。","respondent":"松代道路公園課長","answer":"平成１６年度から本格的に実施をしたいと考えています。平成１５年度で実施をしている中で、２０件ほどすでにボランティアで活動をしていただいております。","id":"exchange-007"},{"speaker":"若林委員","kind":"確認","question":"９月の世論調査の動向を見て最終の運びになるというふうに理解をしてよろしいでしょうか。ここら辺をどういうふうにされていくのか、道路があるのかないのか、ちょっと確認をします。","respondent":"松代道路公園課長","answer":"先ほど、実施しているボランティアとして団体で登録していただいているのは４件でございまして、今そういったお話をさせていただいている件数です。説明会等で地域の方々、参加された方はぜひボランティアでやりたいというようなお声をいただいております。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問・要望","question":"ぜひ区民の皆様には、３名以上でワンペアということですので、募集をしてほしいと求めました。花壇はないんだけれども、そこに新しく花壇をつけるというようなお考えにあると思っておるんですが、確認をします。","respondent":"松代道路公園課長","answer":"公園に花壇等がない場合の対応ですけれども、四季を通じて花を植えていただくというのは、区民の方も関心をお持ちです。そういった意味では、一画に花壇を設けまして、そういったものを四季を通じて管理していただくという形で考えてあります。","id":"exchange-009"},{"speaker":"若林委員","kind":"質問・要望","question":"その地域のシルバーセンターの方たちに、逆に声をかけながら、「いかがでしょうか」というような方向性もいかがかなと。ですから、以上３点、お考えをお聞きいたします。","respondent":"松代道路公園課長","answer":"もしくは種の支援、そういったもので現在進めているところでございまして、これも引き続き続けていきたいというように考えておるところです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"２７５ページ、目黒線の立体交差事業に伴う地盤沈下の問題をお伺いします。本日夜に地元の説明会があるということですが、先立って何点かお伺いをしたいと思います。","respondent":"中島街路事業担当課長","answer":"それを受けまして、施工者におきまして調査を開始いたしました。原因ですけれども、工事現場の止水壁の一部から漏水が起こったのが原因ということで現時点で考えているところです。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"土留壁からの出水ということですけれども、何日ぐらい水が流れていて、どのくらいの量が流れていたのか、お聞かせほしいと求めました。","respondent":"中島街路事業担当課長","answer":"出水量ですけれども、推定ですけれども、一番多い時点で、１分間に約２００ｌ、ドラム缶１本ぐらいの水が流水していたということを現時点で推定しています。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"どのくらいの期間流れていたかは推定できるんか尋ねました。","respondent":"中島街路事業担当課長","answer":"２月の上旬から２月末ぐらいまで、約１カ月弱というふうに考えてあります。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"専門家に伺ったら、地下水の水位のチェックというのは基本のきであると言われたんですけれども、この辺がどうしてチェックがきちんとできなかったのかというところが大変疑問なんですけれども、その辺については検討されたんか尋ねました。","respondent":"中島街路事業担当課長","answer":"要するに地下水の関係がございまして、そういった測定をするのは基本中の基本、当たり前のことです。それに沿った対応を常にしていますけれども、原因が判明するまでに時間がかかったということで、対応までに少し時間を要してしまったということで。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"あの地域は地盤が大変弱いということは、地域の皆さんは言っていらっしゃるんですけも、そういった面での配慮が欠けていたのではないでしょうか。ずさんな面があったのではないかなと思うんですが、あってはならない事故なので、再発防止の対策はとられているんか尋ねました。","respondent":"中島街路事業担当課長","answer":"管理をしていますけれども、そういった部分では確かに今回直接の工事をしている業者で管理が甘かったというのは事実です。今後二度とこういうことがないようにということで、私ども事業者としても注意を怠りなくやりながら進めていきたいというふうに考えてあります。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"再発防止のために今後努めてほしいと求めました。今後の対応がとても大事だと思うんですが、この間の調査内容と、被害状況、そして家屋調査などがどのくらい行われたか説明を求めました。","respondent":"中島街路事業担当課長","answer":"今回の状況の説明をいたしまして、今後の対応を含めて、説明会のチラシにつきましては。家屋調査を実施してございませんので、今般説明会の後に早急に家屋調査を含めて被害状況の把握も併せてやっていきたいというふうに考えてあります。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"技術的に、東急電鉄などはかなりいろいろノウハウを持っていると思うので、そういうところでできる限りのことをしてほしいと求めました。当面の対策とか、長期的な対策というあたりは、今日の夜に向かってできているんか尋ねました。","respondent":"中島街路事業担当課長","answer":"今回の地盤変状、住民の方が一番不安に思っているところですので、きちっとした原因の説明をして、まずは安心をしていただく。今後の対応を責任を持って事業者としてやっていくということが肝要ではないのかなというふうに考えてあります。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"今日の説明会は分かったんですが、今日参加できなかった方、漏れてしまわれた方への対応も考えていらっしゃるか尋ねました。","respondent":"中島街路事業担当課長","answer":"先ほど申し上げましたけれども、本日の説明会の後に全戸調査に入ります。その中で今日の説明会に参加できなかった方につきましては、改めて個別の説明をさせていただこうというふうに考えてあります。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"意見","question":"品川区がどのような立場をとられているのか、今後どういうふうに進められていくのかとの意見を述べました。","respondent":"藤田都市計画課長","answer":"放射２号線について防災上の観点、そういった形から放射２号線の整備については進めていくべきだろうということで考えてあります。本年３月、こういった方針が固まってくるものですので、そちらのほうで住民の理解を得た上で進めていきたいというふうに考えてあります。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"防災の立場で進めていくというお考えだということですけれども、どうせ計画があっても進まないんじゃないかといったご意見もかなりあるんですね。そういった面で区民の皆さんの声をどう聞いているのかというのが大変重要だと思うんですが、この点はいかがか尋ねました。","respondent":"藤田都市計画課長","answer":"昨年１２月に東京都のほうで広報されて以来、優先整備路線であるというような形で広報、あるいはホームページ上で掲載をしてきてあります。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"意見","question":"この中身を建設委員会で報告されたのが１月２０日なんです。住民の理解を得るということですけれども、この辺の進め方が住民の立場に立っているかどうか大変重要だと思うので、もう一度お答えくださいとの意見を述べました。","respondent":"藤田都市計画課長","answer":"区民の皆様の関心は非常に高い項目だというふうに考えてありますので、そういった面で東京都のプレスが終わる時期に合わせて、私ども個別に建設委員会委員の皆様にはご説明を差し上げたところです。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"どれだけの道路が必要なのかという観点と、そこの住環境をどう守っていったらいいのかというところのバランスだと思うんです。区でできることは一体どういうことなんか尋ねました。","respondent":"藤田都市計画課長","answer":"今回のケースは事業主体が東京都だですけれども、こういった形で全体の優先整備路線が提示されてきてありますので、それらにつきましては、区のほうといたしましても、区民の皆様に十分周知を図っていきたいと考えているところです。","id":"exchange-022"},{"speaker":"大西委員","kind":"質問・要望","question":"２７５ページの道路バリアフリー事業、そして時間がございましたら、２８５ページの東品川海上公園整備についてお尋ねしたいと思います。これは私は何度もご質問を申し上げて、ご答弁もいただき、まちづくり事業部の基本的なコンセプトを教えてほしいと求めました。","respondent":"中谷まちづくり事業部長、奈良交通安全担当課長","answer":"放置自転車対策に対する区の基本的な考え方ですが、区としても放置自転車対策については懸命に取り組んできている。そういうことで、区の中が安全で快適になるように、区としては放置自転車の回収に向けて日々努力していくというのが… 平成１３年度から整備有料化とか、いろいろなこういった対策を進めた結果、朝の時間帯の大井町駅周辺というのは物の見事にきれいになりました。","id":"exchange-023"},{"speaker":"大西委員","kind":"質問","question":"私は、不法駐輪対策については、早急なる根本的な解決を図っていくべきだと考えています。２６７ページの下のほうに、具体的にはこの会合というのは何回ほど開かれ、どういうふうな議論になっているかを説明するよう求めました。","respondent":"奈良交通安全担当課長","answer":"そういった協議会を設置しまして、駐輪問題、お互いに共通の認識を持っていこう。そういった面で協議会の中でお互いに話し合って、いい方向に持っていこうということで、今回協議会を立ち上げるものです。","id":"exchange-024"},{"speaker":"大西委員","kind":"質問","question":"これは私からすると、先般の決算特別委員会でも質問をしたところですけれども、これは未必の故意に当たるんじゃないかということをお尋ねしました。私は未必の故意を相当認めるのではないかなと思ったんですけれども、この辺、部長どんなものか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"そして対応を図っているわけですので、委員ご指摘のことについては当たらないと、このように考えているところです。","id":"exchange-025"},{"speaker":"大西委員","kind":"質問","question":"夕方非常にたくさん自転車があるという認識を区がされている。では、夕方に対しては平日どのような手だてをとられているんか尋ねました。","respondent":"奈良交通安全担当課長","answer":"夕方の撤去活動につきましては、従来は午後４時までやっていたんですけれども、４月以降からについては午後６時まで延長をいたします。それを１時間延長して、午後６時までということで、撤去活動を強化してまいります。","id":"exchange-026"},{"speaker":"大西委員","kind":"質問・要望","question":"そういう点で、ぜひ名実ともに一流としての対応をしてほしい。東品川海上公園整備について、ここに出ておりますが、この件に関してちょっとお話を説明するよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"大西委員","kind":"意見","question":"失礼しました。東品川海上公園整備について、具体的にはどういう中身を整備するのかを聞かせてくださいとの意見を述べました。","respondent":"岩田管理工事課長","answer":"最終整備は平成１８年度をもってすべての東品川海上公園の整備が終わる予定になっております。約半分程度の整備が平成１７年度に一部できる予定ですので、その部分の詳細設計の経費を計上させてもらっているものです。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"地籍調査自体今度初めての予算が計上されてきて、我々自民党としては政策要望の中でここ数年来要望しておりました。平成１５年度３分の２ぐらい完了予定というふうに聞いていたんですが、今年度で終わっていくのかどうか、２点お答えをお願いします。","respondent":"市岡企画財政課長、岩田管理工事課長","answer":"あるいは今後の参加をさらに呼びかけていったらいいかということで、いろいろ考えまして、この記念式典にご招待をすることにいたしました。まちづくり事業部のほうでささやかな記念品もご用意いたしましたので… 地籍調査事業として、新たな事業を立ち上げましたので、ここに吸収させてもらったです。これはすべて国庫補助対象事業になりますので、残りの三級基準点の未整備約６８ポイント、これを全部平成１６年度で実施しようというものです。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"地籍調査のほうについてお伺いします。どういう難しさがあるのか、いろいろ絡んでくると思いますが、その辺についてご説明をほしいと求めました。","respondent":"岩田管理工事課長","answer":"これには膨大な労力が今後かかってまいります。三級基準点だけではあまりにも遠過ぎますので、調査ができませんので、もっと細かいメッシュで四級基準点も合わせて整備していくというものです。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"５年おきとか、１０年という話も、現実的に品川区ではどのぐらいの年数がかかるのか。莫大な費用になると思うんですが、その辺はどのぐらいになってくるのかなということで、お答えをほしいと求めました。","respondent":"岩田管理工事課長","answer":"総事業費ですけれども、概算で約７０億円程度はかかるだろう。ここで何年ということはなかなか難しいんですけれども、３０年を一つの目安にして事業化計画を立てていきたいと考えております。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"３０年であがればいいという状況だと思うんですけれども、長い期間になると思いますけれども、徐々に進めていっていただきたいなと思います。２カ所ほど、品川シーサイドの有料駐輪場と、天王洲アイルの有料駐輪場、現在の使用率というのはどのぐらいになっているかなという点をお聞きしたい。","respondent":"奈良交通安全担当課長、片田建築課長","answer":"利用率ですけれども、天王洲アイルにつきましては３５％、品川シーサイドにつきましては２０％弱ぐらいです。木造住宅耐震診断の専門機関というお話ですけれども、私どもで今検討しているのは、社団法人の東京都建築事務所協会品川支部という機関があります。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それから、木造耐震診断は品川支部２７社ということで、うまく使ってほしいと求めました。その中で、逆に診断の結果によって改修しなければいけなくなったとき、そこをどのように結びつけていくのかについてお答えをほしいと求めました。","respondent":"藤田都市計画課長、片田建築課長","answer":"なかなか細かい分析等は難しいので、数値的なものはございませんけれども、売り上げ自体は伸びているというふうに聞いてあります。店舗側の努力と… 結果として悪い、いいということではなくて、どの辺を改修したらいいかといったようなところをアドバイスできればということも考えてあります。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"言えない部分あると思うんですけれども、逆に言うと、品川区は株主として利用をどう考えるのかなというのをお答えをほしいと求めました。もう１点、相談から、最後の補強工事まで一貫してうまく使ってほしいと求めました。","respondent":"市岡企画財政課長","answer":"なかなか辛いところでありますが、職員の旅費につきましては、一番合理的で最も安いところをとるというのが原則ですので、願わくば、お台場等に出かけて、個人としても、職員の皆さんにせいぜい利用していただきたい、こういう苦しいところですが、よろしくお願いいたします。","id":"exchange-034"},{"speaker":"本田委員","kind":"質問・要望","question":"さらに、１３ｍの水深を１５ｍに深くして、２０フィートのコンテナを８,０００個積むことのできる巨大なコンテナ船が横付けできると。都市計画といいますか、臨海部のまちづくりに係わりますので、まずこの特徴点をご説明ほしいと求めました。","respondent":"藤田都市計画課長","answer":"第７次東京港の港湾計画についてですけれども、委員ご指摘のとおり、概ね２０年間を見据えた形で、東京港で実現すべき政策について示したものです。","id":"exchange-035"},{"speaker":"本田委員","kind":"質問","question":"ここでお尋ねしておきます。かつて、交通安全の面からも現状を改善する必要があると思うんですが、まずこの点をお尋ねします。","respondent":"上野都市開発課長","answer":"１月１日を除く３６４日、２４時間作業を進めているところですけれども、なかなか荷物が捌き切れない。あるいは都市計画上の２８号線ということで都道ですけれども、今検討をしているところというふうに聞いてありますので、よろしくお願いいたします。","id":"exchange-036"},{"speaker":"本田委員","kind":"質問","question":"現状の改善を急いで図るように、大きな事故等が起きてからでは遅いですから、お願いをしておきたいと思います。勝島運河、これは品川区にとりましてはどういう具体化の方向が今後打ち出されていこうとしているのか、お尋ねしたいと思います。","respondent":"上野都市開発課長","answer":"歳入のときの山路委員にもお答えしていますけれども、協議会なるものを地元区とともども立ち上げて、具体的な検討をこれから進めていくといったところです。","id":"exchange-037"},{"speaker":"本田委員","kind":"意見","question":"親水性の護岸を、殺風景な護岸に花を植えて、地域の活性化に使うということで大変ご努力をされております。その辺はまだ検討をされていないのか、これからの課題なのか、お尋ねしますとの意見を述べました。","respondent":"上野都市開発課長","answer":"具体的な緩和の内容等につきましても、平成１６年度以降そういった検討をこれからやっていくです。今はどういった課題があるか、今委員ご指摘のような課題があるということを認識しているという段階です。","id":"exchange-038"},{"speaker":"本田委員","kind":"意見","question":"第７次の基本計画は、東京港の２０年後のあるべき姿を明確にしながら、それに向けてそれぞれまちづくりを進めていく。今いろいろと計画の概要をご答弁いただきましたけれども、今後実施計画づくりの中で区の意見が反映されますように期待をして、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"武内委員","kind":"質問","question":"２６７ページの駅周辺等放置自転車対策費、２７１ページの街路樹整備費、２７５ページの道路バリアフリー事業をお伺いしたいと思います。取りに来ない、そういった民間のマンションの敷地内の自転車というのはどちらのほうで撤去していただけるか、説明するよう求めました。","respondent":"奈良交通安全担当課長","answer":"今委員お話の、民間のマンションの駐輪場に放置された自転車につきましては、基本的にはマンションの管理する管理者の方から処分していただくというのが基本原則です。","id":"exchange-040"},{"speaker":"武内委員","kind":"質問","question":"その際、例えば撤去すると言っても、捨てる場合、八潮とか不動前のほうの保管所のほうに持っていってもらうことは、有料であればできるんか尋ねました。","respondent":"奈良交通安全担当課長","answer":"もし持ち主の方がいれば、それは持ち主の方が正規の廃棄物として５００円を払っていただいて、処分してもらう。数年も経っているということであれば、マンションの管理人の方に費用を負担していただいて処分をしていただくというのが基本原則です。","id":"exchange-041"},{"speaker":"武内委員","kind":"質問","question":"そこのマンションに係わりのない、例えば酔っぱらいがどこかで自転車を乗り捨てて行ったようなケースの場合はどのように対処したらいいか尋ねました。","respondent":"奈良交通安全担当課長","answer":"それはその方の自転車なのか、そういう場合には地元の交番等にお届けいただいて、盗難被害にかかっていないのかどうか確認をしていただく。もし盗難被害であれば、当然それは警察のほうの扱いになるです。","id":"exchange-042"},{"speaker":"武内委員","kind":"質問","question":"スクールゾーンについてお伺いしたいんですが゛この安全対策ということで、午前８時から午前９時の通学時間帯に、その辺の見解を説明するよう求めました。","respondent":"奈良交通安全担当課長","answer":"スクールゾーンは区内に相当の数がありますけれども、スクールゾーンの入口部分に協力される方がいれば、パイプ柵を置いていただいている。もしご協力していただけない方につきましては、現在はそういったものは置いておりません。","id":"exchange-043"},{"speaker":"武内委員","kind":"質問・要望","question":"なぜですかという話を聞いたら、どうしても通学時間というのは通勤時間にも重なるものですから、車がどけて通っていくわけです。実際問題やっても無駄だということで、地域によっても違うと思うんですが、そういった場合に何か対応できるようなことがありますか尋ねました。","respondent":"奈良交通安全担当課長","answer":"それを取り払って通行する、確信犯だと思うんですが、そういう方は確かにいらっしゃいます。私どものほうもそういった場所が分かれば、そういった場所がありますれば、私のほうから地元の警察のほうに要望してまいりたいと考えています。","id":"exchange-044"},{"speaker":"武内委員","kind":"質問","question":"続きまして、２７１ページの街路樹整備費についてお伺いします。これの害虫駆除委託等ということで、消毒をやられる際に近隣の民家等に周知をされているようでしたら、どのような形でされているか説明するよう求めました。","respondent":"松代道路公園課長","answer":"私どもの街路樹を管理する上で害虫等が出てまいります。公園を利用される方には、その場でその付近には入れないような形もとりまして、十分な安全性を確保して害虫駆除を実施ているところです。","id":"exchange-045"},{"speaker":"武内委員","kind":"質問","question":"街路樹は苦情がきた場合にやるということですけれども、公園のほうは定期的にやっていらっしゃるんか尋ねました。","respondent":"松代道路公園課長","answer":"毛虫等が発生して、通報をいただいて、すぐに対応するという発生主義をとっております。これは街路樹も公園も同様です。","id":"exchange-046"},{"speaker":"武内委員","kind":"質問","question":"その際には何週間か前から掲示板に告知をされてやっているんです。その際に地域の方に何の連絡もないものですから、そういう声が寄せられて、そういった苦情等というのは区のほうにはきていますか尋ねました。","respondent":"松代道路公園課長","answer":"これは農薬使用者すべての者が農薬が飛散することを防止するために必要な措置な講じるよう努めなければならないというものを規定したものです。保健所、保健センター、環境衛生担当というところがそういった相談に応じるというように聞いてあります。","id":"exchange-047"},{"speaker":"武内委員","kind":"質問・要望","question":"それも、そういったことをご検討いただければというふうに、これは要望ということでお願いいたします。２７５ページの道路バリアフリー事業ということで、横断歩道は２cm段差というんですか、その辺は何か基準みたいなものがあるんか尋ねました。","respondent":"岩田管理工事課長","answer":"前にもお答えしたと思うんですけれども、品川区は平成６年頃からこつこつとバリアフリー、これを試行的に行っております。いよいよ品川区のやり方で車椅子にとってやさしいゼロcm段差を堂々とやることができる時代がやっとついてきたという状態です。","id":"exchange-048"},{"speaker":"武内委員","kind":"意見","question":"先日板橋駅か何かでちょっと出ておりましたけれども、一部段差があって、３分の１ぐらいをバリアフリーで車椅子等が通れるようなそういった段差のがありまして、私も見てきたんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"石田委員","kind":"質問・要望","question":"公平、その商店街にはほかの意味での助成金は払わないというような政策を打ってほしいと思いますが、パーセントの調査の実態を教えていただきたい。ところが、ちょっとお話を伺っていくと、相談件数は減っていないということであります。","respondent":"岩田管理工事課長、片田建築課長、藤田都市計画課長","answer":"個々の商店街にも説明をして、きちっと申請を出していただくように、これから働きかけをしていく予定です。その中で… 私のほうからは、建築確認の相談についての手数料等についてご説明をさせていただきたいと思います。一応検討をする余地があるということで考えております… ファミリータイプの確保等ができないというようなことで条例を定めて、地区計画を定め、その条例で規制をしていくというようなことを始めてあります。","id":"exchange-050"},{"speaker":"石田委員","kind":"質問・要望","question":"それから、建築確認のほうですが、そこら辺のところは認定でも何でもそういうことで徴収できる部分はしっかり徴収してほしいと求めました。要綱も指針もあるわけですから、私は必要だと思うので、その点の考え方をもう一度説明を求めました。","respondent":"浜脇住環境整備課長","answer":"私が所管してこれまでやってまいりまして、住環境をやっていただいて、それが結果として良好なまちづくりに寄与しています。あるまちづくりの中で、品川区全域の中でかけるということは、そういった問題から現状ではそういったものは検討をしていないという状況です。","id":"exchange-051"},{"speaker":"石田委員","kind":"質問・要望","question":"そういう形の中でなかなかそこの部分が誘えないという現実もあるわけです。その点をもう１段進んでやっていただきたいというのは、要望にして、これでやめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"菊地委員","kind":"質問・要望","question":"ＪＲ広町地区の開発についてお尋ねをしたいのと、もう１点、紛争調整事務費についてお伺いをしてまいりたいと思います。もう１点、開発の種地として購入した７,５００m2の土地をいつ頃、どれぐらいの値段で購入をしたのかも教えてほしいと求めました。","respondent":"上野都市開発課長、市岡企画財政課長","answer":"まずＪＲとの協議の進捗状況ですが、開発理念の検討ですとか、課題の整理といったところについて協議をしてきているところです。それから、範囲につきましては… 原っぱ公園は平成４年、５年、６年にかけて買っておりまして、総額が１７１億円余です。","id":"exchange-053"},{"speaker":"菊地委員","kind":"意見","question":"理念というような話もありましたけれども、実際に１年間かけて協議をされてきたんですけれども、それだけなのかという気がするんです。現在の位置づけですとか、目的とそう変わっていないというように思うんですけれども、もう少し詳しいところはどうなんでしょうとの意見を述べました。","respondent":"上野都市開発課長","answer":"その協議を進めるにあたりましては、なかなか具体的なところまでの話を進める段階にはまだ至っていないといったところです。複合機能開発を行っていくとか、広場、緑の環境をつくっていくとかといった考え方は継承しているものというふうに考えてあります。","id":"exchange-054"},{"speaker":"菊地委員","kind":"質問","question":"まちづくり事業部次長が当時の桜井委員に説明をされていますけれども、ＪＲの敷地の開発でもって大井町の活性化につなげると。品川区の中心核というのが、これからの協議の中でどうなるかわからないよという立場なのかどうか、ちょっとそこをもう一つお伺いをしたいと思います。","respondent":"上野都市開発課長","answer":"現在の具体的な開発の検討の対象区域の中には現庁舎の敷地は入ってございませんけれども、将来の課題として庁舎のあり方も検討をしていくです。","id":"exchange-055"},{"speaker":"菊地委員","kind":"質問・要望","question":"これが例えば大崎駅東口第３地区に１００億円ぐらいの補助金が投入されますけれども、こういう場をぜひ設けていただきたいというふうに思います。もう１点ですけれども、性格上どんなものにでも転用していくということが可能なものなのかどうか、ちょっとそこをお聞かせほしいと求めました。","respondent":"上野都市開発課長","answer":"種地の性格ですけれども、これはまちづくり事業用地として取得したものですから、将来のまちづくりに備えるといった性格の土地です。","id":"exchange-056"},{"speaker":"菊地委員","kind":"質問","question":"再開発の種地、例えば旧イトーヨーカドーの裏が今駐輪場になっていますけれども、あそこは昔７億円程度で買ったということですよね。あの土地はあくまでも再開発のためのもので、転用できないという話なんでしょうか、ちょっとそこをお願いいたします。","respondent":"上野都市開発課長","answer":"先ほど将来の開発のためにというふうに申し上げましたけれども、現在は１０年間は原っぱ公園として利用する。今暫定的に駐車場として当面整備するといった状況にありますけれども、将来の開発用地として取得したものであるという性格には変わりございません。","id":"exchange-057"},{"speaker":"菊地委員","kind":"質問・要望","question":"もう少し広く区民を交えた、商店街、あるいは実際にこのアパートには多くの皆さんが住んでいらっしゃるわけですから。その内容をお話をしていただきたいんですけれども、どの程度の規模のものが対象になっていくのか、この辺も含めてお知らせを願いたいと思います。","respondent":"浜脇住環境整備課長","answer":"今回の改正したときに検討したものですと、中高層の建築に絡むものにつきましては、解体についても一緒に説明をするようにということで、現在検討をしているところでございまして、７月の条例改正に向けてそれらを整理してまいりたいというふうに考えているところてあります。","id":"exchange-058"},{"speaker":"菊地委員","kind":"質問","question":"あるいはＳＲＣの建物であろうと、とにかく後にマンションが計画をされるものについては、その対象だということなんでしょうか。前のことはわかりませんという言い逃れがよくありますけれども、そうしたものが対象になっていくのかどうか、そこを説明するよう求めました。","respondent":"浜脇住環境整備課長","answer":"先ほどの条例の改正ですけれども、４月１日に改正いたしまして、施行が７月１日ですので、その間にいろいろな提起をしたいです。今の件ですけれども、将来何に使うかわからないというものについては、今の検討の中では含まれていないような検討をしています。","id":"exchange-059"},{"speaker":"菊地委員","kind":"質問・要望","question":"今もお話ししましたように、前段の改築によるほこりとか、騒音が業者の大概の口実になるわけですよね。ここはこれからつくっていくということですから、ぜひこの辺は十分に考えて盛り込んでいただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"嶋委員","kind":"質問・要望","question":"２６７ページ、２７５ページの道路バリアフリー事業に関連して、大井競馬場駅周辺についてお伺いいたします。二つ目には、２８３ページ、公園・児童遊園維持管理費についてお伺いをいたします。","respondent":"藤田都市計画課長","answer":"りんかい線の全線開業が平成１４年１２月ですので、平成１３年度の乗降につきましては１日の平均乗降が約３万８,０００人です。平成１５年、１２月までのデータの平均ですけれども、４万２,０００人というふうに聞いてあります。","id":"exchange-061"},{"speaker":"嶋委員","kind":"質問・要望","question":"約５,０００名ということで、これは調べる時間帯もさまざまなので、平均として受け止めします。５,０００名ですが、青物横丁駅から品川シーサイド駅周辺までの動線としてこれからどのようにお考えになるかをお聞かせほしいと求めました。","respondent":"上野都市開発課長","answer":"その中身がどういった中身かと申しますと、現在概ね道路のほうはでき上がっておりますけれども、あと５ｍほど道路が広がる予定になってあります。歩道拡幅も含めた道路整備を行うということで、東京都の道路ですけれども、確認しています。","id":"exchange-062"},{"speaker":"嶋委員","kind":"確認","question":"そこから出てくる歩行者を確認することが厳しいということで、バス停留所のところにタクシーがそのまま何台か並んでいるということです。品川シーサイド駅をつくる段階のときに、タクシー乗り場の確保というのをどのように考えていらっしゃったのか、ちょっとお聞きをしたいと思います。","respondent":"松代道路公園課長、上野都市開発課長","answer":"安全対策、そういったものが必要ということで、私どもも認識しています。そういったもので何かできないか、そういったことをお話をして、今協議をしています。 将来のものとして考えていたものは、タクシーのベイとして考えてございましたけれども、今ご指摘のジャスコ側のところについては計画の中で特に位置づけはございませんでした。","id":"exchange-063"},{"speaker":"嶋委員","kind":"質問","question":"その中で、自転車があそこを通るということもありまして、自転車道路ということは決めることはないかと思うんです。正しい言葉があるかどうかわかりませんが、自転車を走る人は何となくこっち、大井競馬場通りの歩道に関してちょっとお聞きをしたいと思います。","respondent":"松代道路公園課長","answer":"私ども今できておりますのは、看板等を設置しまして、注意を促すというようなことをしております。今日の提案とも、少し流れ等も含めまして、検討をさせていただければと思います。","id":"exchange-064"},{"speaker":"嶋委員","kind":"質問・要望","question":"仕切り線というソフトな部分で自然と人が流れを自分たちでどっちかを選んでいくという形にぜひしてほしいと求めました。それから、次に、２８３ページの、公園・児童遊園の維持管理費、まず最初に、公園と児童遊園の仕切りみたいものをお知らせほしいと求めました。","respondent":"岩田管理工事課長","answer":"子どもたちの遊ぶ場の確保というところから出発して、品川区の中でも児童遊園につきましては別の条例をつくって管理をしております。同じというのは事実でございまして、私ども管理する側においても制限とか、そういった違いというのは特にございません。","id":"exchange-065"},{"speaker":"嶋委員","kind":"質問・要望","question":"1)公園でしかなかったものですから、私は１番地区公園と呼ばせていただいておりますが、皆様がゆっくりとされるところです。あそこを通ると、必ず「すいません、今何時ですか」という声をかけられますので、ぜひそこにも時計の設置をしてほしいと求めました。","respondent":"松代道路公園課長","answer":"１点目の時計の設置です。加えまして、八潮の公園ですけれども、これは都営住宅が敷地内に設けた公園だというふうに認識しています。","id":"exchange-066"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひお願いをして、児童遊園、私のほうに要望があったのは、区立浜川児童遊園でございました。地域の皆様のご要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"原委員","kind":"質問・要望","question":"今回安全対策に１,８００万円、啓発費に９８０万円取って、お伺いをします。これでどのぐらいの平米を買収しようとしていらっしゃるのか、ちょっとお伺いします。","respondent":"奈良交通安全担当課長、中島街路事業担当課長","answer":"こういう乗り方にしましょうという、リーフレットをカラー刷りで、これを概ね５万部作成をしております。今月中には各自転車店、それから、二つの保管所、それから、自転車等を扱っているスーパー… １点目の用地費についてのお尋ねですけれども、３億１,０００万円で、約５０m2の用地買収を計画しています。東京浴場から補助１６３号線の出口のところ、２カ所道路整備をしてございまして、この２カ所の道路整備の事業費です。","id":"exchange-068"},{"speaker":"原委員","kind":"質問","question":"これをどう取り締まったらいいのかというのが大事なんで、どう取り締まっていこうか考えていらっしゃるかどうかお伺いいたします。土地を買う場合は相手があることですから確かに更正減額されるかもしれませんけれども。","respondent":"奈良交通安全担当課長、中島街路事業担当課長","answer":"交通安全啓発費の中で、自転車利用者への啓発活動につきましては、先ほど申し上げましたリーフレット代で３７万５,０００円をとっております。品川区としましても、こういった自転車のマナーについては… 先ほど５０m2と言いましたけれども、先般もご説明をさせていただきましたけれども、用地といたしましては約１７０m2ぐらいの土地代です。","id":"exchange-069"},{"speaker":"原委員","kind":"質問・要望","question":"あそこで止まってしまうということは、当初の計画ではおそらくなかったんだろうと思うんですけれども、その辺のところの考え方を教えていただきたい。そういう何かを訴えていかないと、いつまで経っても同じ状況が続くんではないかと思うんですが、いかがでございましょうか。","respondent":"中島街路事業担当課長、藤田都市計画課長、奈良交通安全担当課長","answer":"ただ、この間もお話し申し上げましたけれども、今残っている、買収できないところにつきましては、超困難物件です。もう１点、補助２０５号線で… 補助２０５号線につきましては、原踏切の先がどこの道路にぶつかるかと言いますと、補助２９号線とぶつかる予定になってあります。… 今委員からご指摘をいただきましたイエローカードにつきましても、これは一つの方法だと思います。","id":"exchange-070"},{"speaker":"木下委員","kind":"質問・要望","question":"品川区が７７０haをその適用地域に指定と書いてあるんですけれども、指定された地域というのはどこら辺の地域なのか教えてほしいと求めました。こういう考えがあるのかどうなのか、その部分についてお答え願えますか尋ねました。","respondent":"片田建築課長","answer":"３月２日付の新聞記事のほうからご説明いたしますと、品川区ですと、整備地域として指定しているところは約７７０haほどあります。区の考え方としてご説明させていただいた経緯がありますけれども、具体的には昨年の３月、一応できるようになったという状況があります。","id":"exchange-071"},{"speaker":"木下委員","kind":"質問","question":"金融公庫と提携して、１０年間は金利が２.５％、１１年目から３５年目は３.５％、これは普通の住宅金融公庫の融資で受けられる融資と全然変わらないから、どういうメリットがあるかというのをお聞きしたんです。","respondent":"片田建築課長","answer":"今回の場合は敷地面積が７０m2以上であればよろしいとか、一定程度隣地の空きを５０cm以上設けるとか、準耐火構造とするような構造要件が付けられてあります。","id":"exchange-072"},{"speaker":"木下委員","kind":"質問","question":"それと、さっきもう一つ、墨田区、中野区、荒川区の一部では準耐火構造以外の建築以外は建設できないように規制すると。それは品川区のほうも規制されるというふうな考えでよろしいんか尋ねました。","respondent":"片田建築課長","answer":"品川区においてもそういう制度を検討するにあたって、制度としてはこれまでの防火構造と言われるものができづらくなるといったような状況です。今、現況としての地域についての検討をこれから検討していきますといったような内容です。","id":"exchange-073"},{"speaker":"木下委員","kind":"質問","question":"そういうところは品川区内はいっぱいありますので、防災上の観点からも、そういうのを促進していただければというふうに思っております。２番目の項目として、効果が上がっているのか、お教え願えますか尋ねました。","respondent":"浜脇住環境整備課長","answer":"昭和５２年から指針をつくりまして、これまで指導をしています。その中ではワンルームマンションの３階建てで、建築計画の説明でありますとか、配慮したものを設置するように指導をしておりまして。","id":"exchange-074"},{"speaker":"木下委員","kind":"質問","question":"先ほどの質問に加えて、効果が上がっているのかどうなのか、後でまたお知らせほしいと求めました。文京区のような、例えば管理人を置かなければならないですとか、もうちょっと要綱を厳しくするような考え等はありますか尋ねました。","respondent":"浜脇住環境整備課長","answer":"周辺への自動車とか、自転車の駐輪場等も指針の中では設けまして、指導してまいりました。それから、５０戸以上のワンルームにつきましても、管理人を置くように、中でも設けておりまして、管理人がいるワンルームもあります。","id":"exchange-075"},{"speaker":"木下委員","kind":"質問・要望","question":"時間もございませんので、委員の要望として、そういう声がありますので、これからも厳しく指導をしていただくようにお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"西本委員","kind":"質問","question":"公園管理ですが、公園を区民の方が借りるときと、区主催、共催も含めて、いろいろ使われる場合とで、使い方の規定というのはあるんでしょうか。こういう場合に使ってはいけないというところでの制約といいますか、それは両者間での違いがあるのか尋ねました。","respondent":"松代道路公園課長","answer":"公園等はなるべくお子さんを中心として、学校が終わった放課後などにはなるべく団体利用を避けて、お子さんに優先的に使っていただく。そういったものがありますので、そういったものの制限をしています。","id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"その辺はある程度分かっているんですが、例えば公園の中での火でありますとか、それからお金のやりとりでありますとか、そこら辺の違いというのはどうなんか尋ねました。","respondent":"松代道路公園課長","answer":"もちろん今委員がおっしゃいましたように、火を使うということはできません。一般的には普通の使い方をされれば、そんなに制約はかからないものですけれども、条例の中でそういったものを明記しています。","id":"exchange-078"},{"speaker":"西本委員","kind":"質問","question":"一番初めの質問ですが、制限に対して、区主催でいろいろ行事をされる場合と、区民の方が借りて利用される場合とでの違いはあるのか尋ねました。","respondent":"松代道路公園課長","answer":"町会行事とか、地域の行事、そういったものがあります。そのほかにも、今申し上げましたようなリサイクルの観点からフリーマーケットとか、そういったものもあります。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問・要望","question":"しかしながら、私が係わった中で、区民の方たちに利用していただきたいという行事をしたときに、２,０００人弱の方が集まります。は実績を見ていただくとか、ということで、その辺のお考えはいかがか尋ねました。","respondent":"松代道路公園課長","answer":"そういったときには、今委員のおっしゃったような使い方をされております。ほかの利用者の安全とか、実際使われるときには、ある程度地域の中で責任を持っていただくということでのお約束で使っていただいているのが現実です。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"あまりにも広げてしまうと管理も大変と思いますので、そこら辺は団体等の話をきちんとしていただいて、できるだけ要望に応じる。これはどういう内容なのか、もしも今までの実績があるのであれば、どういう実績があるのか教えてほしいと求めました。","respondent":"浜脇住環境整備課長","answer":"これまでトータルいたしますと、専門家の派遣を１１６回ほどやって、ある意味では定着をしている事業というふうになってあります。区民の方々が自主的に地域特性に応じたまちづくりを進める際に、五、ここのところ多く使われているものです。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問","question":"実績がかなりあるというお話でした。私も気がつかなかった部分がありまして、区民の皆さんへの周知はそこら辺はどういうような活動をされているんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"当然品川区のまちづくり事業部のホームページにも載せてありますし、そういうときにも、こういう制度がありますということを広くやっています。","id":"exchange-082"},{"speaker":"西本委員","kind":"質問","question":"先ほども委員のほうからお話があったように、ホームページというのはまだ特定の方の利用になってしまうところがあると思います。今後もっとほかの媒体を使うとかというご検討はあるか尋ねました。","respondent":"浜脇住環境整備課長","answer":"あるいは自分たちのまちづくりをしていこうとか、そういったときがあったら、私どもが出かけて行ってＰＲをさせてもらう。私か、あるいは職員が行って、こういうものをＰＲさせてもらえればありがたいと思ってあります。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"なるべくいい制度があるということは広く伝えてほしいと求めました。４カ所ということですが、今後どういう形でこれを広げていこうとされているのか、その辺をお聞きしたいと思います。","respondent":"奈良交通安全担当課長","answer":"ヒヤリ地図は平成１３年から始めた事業ですけれども、区内４カ所、各警察署１カ所ずつ、計４カ所ということでやっていたんですが、これが順調に進行しておりまして、ちょっと計画変更をしまして、５年の２０カ所で、現在終わる予定にしております。","id":"exchange-084"},{"speaker":"西本委員","kind":"質問・要望","question":"これから２０カ所増えるということで、かなり網羅的になるのではないかなというふうに思うんですが、このつくり方ですが、ここが危ないとか、いろいろ注意事項とかあるかと思うんですが、そこはどういう形でこれをつくっておられるのか、作成の方法を教えてほしいと求めました。","respondent":"奈良交通安全担当課長","answer":"そういう方々に常日頃この辺はヒヤッとするよという地点を選び抜いていただいて、地点に落として、それぞれ関係先に配布をして活用していただいているというものです。","id":"exchange-085"},{"speaker":"西本委員","kind":"質問・要望","question":"要望になりますが、地図ができたというところで、その地図をもとに安全対策というのが当然出てこようかと思います。そこのところの改善といいますか、リンクの仕方をお聞きして、終わりたいと思います。","respondent":"奈良交通安全担当課長","answer":"十分その点を配慮しまして、今後とも交通安全関係も十分やっていきたいと思います。","id":"exchange-086"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、２８３ページ、運動施設改修工事、しながわ中央公園１点に絞ってお伺いをしたいと思います。再度人工芝に戻すんだというご決定であれば、私は理解しますが、その点からお考え方をお聞かせほしいと求めました。","respondent":"岩田管理工事課長","answer":"政策変更というような大げさなこととは考えておりませんで、しながわ中央公園の目的というのは、そのための手段の一つだったわけです。お金をかけて人工芝をし、利用制限をかけて天然芝でいくということは区民のニーズに合わないだろうということで、このような変更になったです。","id":"exchange-087"},{"speaker":"田中委員","kind":"質問・要望","question":"私の問題意識の２点目としまして、公共施設の利用のあり方という部分ですが、ご案内のとおり、公共施設というのは全区民の共有の財産であります。公共施設の利用のあり方という観点で、このような結果になっていることをどう捉えていらっしゃるのか、お聞かせほしいと求めました。","respondent":"岩田管理工事課長","answer":"私どもで考えましたのは、貸し出す方法等の制度として公平性がきちっと担保されているのかどうかというのが重要だと思います。結果として、たまたま申し込んでいただけたのが、残念ながらお隣の学校しかなかったということでございまして、私どもは問題はないと考えています。","id":"exchange-088"},{"speaker":"田中委員","kind":"質問・要望","question":"品川区自身としても公共施設の緑化対策が求められ、現に実行もされております。要は、今回のしながわ中央公園の天然芝を人工芝に変えるということをどう評価されているのか、お聞かせほしいと求めました。","respondent":"岩田管理工事課長","answer":"千葉などは何校かありますし、２３区の中でもちょっとやったところがあるようですけれども、なかなか大変なようです。そういうところを教育委員会のほうも現地を見てきているようですので、私どもとすれば、そちらのご判断にお任せしたいと考えています。","id":"exchange-089"},{"speaker":"田中委員","kind":"質問・要望","question":"法治国家ですから、指針等々があるもとで、さまざまな事業がなされております。我々議会が関与できる部分というのは、議決が必要ですから、条例に対しては関与ができます。","respondent":"岩田管理工事課長","answer":"公園条例に関しては、昨年の第１回定例会に条例でかけさせていただいたときにも、学校優先枠についてはきちっとご説明をさせていただきました。その審議の過程を見させていただいて、細かい手続規定を規則で定めさせていただいた、こういうことです。","id":"exchange-090"},{"speaker":"田中委員","kind":"質問・要望","question":"要綱が本来の事業の内容を大きく左右するものもたくさん含まれますので、これは議会側の要望として強く受け止めていただきたいと考えています。予算が決まっても、執行の部分ではまだ時間がありますので、ご配慮いただけたらと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"藤田委員","kind":"質問","question":"２月２８日に植樹祭が行われまして、３月３０日開園式を迎えるにあたりまして、今工事が着々と進められております。お聞きしたいのは、その辺をお伺いしたいのと、その辺ちょっとお伺いしたいと思います。","respondent":"岩田管理工事課長、松代道路公園課長","answer":"現在しながわ中央公園正門といいますか、区役所側の入口ができるんですが、そこを入って右手の植え込みの中に銘板をつくります。５００円の一般寄附と、未来永劫残すということで、今工事を進めております。 犬の散歩の件です。しながわ中央公園も含めまして、現在のところ原則禁止という形をとってあります。","id":"exchange-092"},{"speaker":"藤田委員","kind":"質問","question":"ですから、きれいに管理されていけばいいんですけれども、当然そういうのを予想してこういう公園というのはつくっているのかどうか。ですから、２０cmぐらいでもいいですよ、低いものをずっとやれば必ずいたずらをされません。","respondent":"岩田管理工事課長","answer":"せっかく役所の前の公園ですので、何かされましたら、すぐにきれいにしてまいりたいと考えています。芝桜については、少し検討をさせていただきたいと思います。","id":"exchange-093"},{"speaker":"藤田委員","kind":"質問・要望","question":"楠の木でしょうか、４本、５本とずっと残っていますね、高木も植えましたね。申し込まないで、土曜、日曜にふらっと、どの団体も使っていない場合は一般区民が行って、少し走ろうかなと、こういう場合はできるんか尋ねました。","respondent":"岩田管理工事課長","answer":"巣箱のことについては、いろいろご意見もあるようですので、これは検討課題とさせていただきたいと思います。使っていなければ、自由に入っていただいて、これはもちろん無料で使っていただくことになっております。","id":"exchange-094"},{"speaker":"宮崎委員","kind":"質問・要望","question":"昭和５６年の建築基準法の改正前ということですけれども、もしつかんでいたら、これが分かったら教えていただきたい。当初、今回は地域の限定が外してありますけれども、そこら辺の考え方についてお伺いしたいと思います。","respondent":"片田建築課長","answer":"この約半数ぐらい、件数でいきますと２万３,０００棟ぐらいが木造住宅で、昭和５６年以前に建築された建物かということで一応認識しています。これは、メニューとしてはあるところですが、区としてはまだこれは検討課題として挙げているところです。","id":"exchange-095"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今、危険地域を外した理由というふうに伺いたかったんですけれども、第４回定例会の一般質問でも私はこの問題を取り上げてお伺いしたんですけれども。診断で４０棟というふうになっておりまして、どういう方にどのくらい利用してほしいというふうなことを考えているのか、どうか尋ねました。","respondent":"片田建築課長","answer":"私どもは今回初めての事業の見込みですので、他区の支援制度の状況を含めて今回４０棟というものを一応想定したものです。それと、利用者の対象についても、これは特に固定するわけでございませんで、区内の建物をお持ちの方を対象としているものです。","id":"exchange-096"},{"speaker":"宮崎委員","kind":"質問","question":"実はここは借地なものですから、返さなければいけないということで、非常に心配しております。そこの調査はどういうふうに考えているか、あるいはもう一つ、制度の周知徹底をどういうふうにお考えか尋ねました。","respondent":"片田建築課長","answer":"一つ、今回の制度と合わせて私ども耐震支援のパンフレットを策定して、区民の方に広くお知らせしていきたいということで考えております。ただ、その中で、区民全般を対象としていくということで考えてありますので、これはご理解いただきたいと考えています。","id":"exchange-097"},{"speaker":"宮崎委員","kind":"質問","question":"今資金力がなくても、何とか制度を使えるような、そういうことも考えられるんじゃないかというふうに思いますけれども、どうでしょうか。２３区のところで、そういうことも含めて、配慮はできないものかどうかお伺いしたいと思います。","respondent":"片田建築課長","answer":"ただ、品川区としては広く区民の方にまず理解をしていただいて、実施していただく、その一つのメニューとして、今回提案させていただいたものです。","id":"exchange-098"},{"speaker":"宮崎委員","kind":"質問・要望","question":"この制度は新年度から始まるというわけですから、これは中身を見ながらということになってくるかと思うんですけれども、特に社会的弱者といわれる方々とか、あるいは今資金力がない方、そういう方々のところにも思いを寄せながら、この制度を運用していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"山村委員","kind":"質問・要望","question":"それに伴いまして、駐輪場のほうをＪＲに強く要望していただければと思うんですが、それについてのお考えをお聞かせほしいと求めました。ＪＲ側に要望をさらにしていただき、周辺の道路環境を整備して、どうにかならないでしょうかということをお聞かせほしいと求めました。","respondent":"奈良交通安全担当課長","answer":"その中でも、推測すると、２５万から２６万ぐらい区内には自転車があるのではないのかなというふうには推測はしております。だから、これは大変な作業になりますので、これについては今後の研究課題というふうにさせていただきたいというふうに思っております。","id":"exchange-100"},{"speaker":"山村委員","kind":"意見","question":"動態調査のほうですが、特に自転車の駐輪問題が起きているところなどは動態調査をしていただいて、的確な政策をとっていただければと考えています。それに関して、自転車対策をまちづくり対策の中でどのように位置づけているかということのお考えを聞かせてほしいと求めました。","respondent":"中谷まちづくり事業部長","answer":"そして自転車専用道を併せてつくるという方向はありますが、これにつきましても、区内ではなかなか難しい。こういうものにつきましては、警察等と協力しながら図っていかなければいけない、このように考えているところです。","id":"exchange-101"},{"speaker":"山村委員","kind":"質問・要望","question":"そのような方向でぜひ頑張っていただければと考えています。次に、こちらの融資助成内容を教えていただきたいのとともに、できないのかということを教えてほしいと求めました。","respondent":"田村住宅課長","answer":"冒頭企画財政課長から説明がありましたけれども、環境共生住宅についても、住宅修築資金の融資と併用か可能という形の見直しを実施いたしました。","id":"exchange-102"},{"speaker":"山村委員","kind":"質問","question":"リフォームで鍵を一つではなくて二つにするですとか、窓に鉄格子を入れるとか、そういうことも融資の対象になっていると考えてよろしいんか尋ねました。","respondent":"田村住宅課長","answer":"鉄格子を入れるというのが、ちょっと。ピッキング対応で、既存のリフォームの範疇で対応できると、そのように考えております。","id":"exchange-103"},{"speaker":"山村委員","kind":"意見","question":"そういう意味で対処できるわけでしたら、防犯対策のほうも助成できますようなことをもう少し前面に打ち出していただいてもよろしいかと思いますので、どうかこれからも頑張ってくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-104"},{"speaker":"本多委員","kind":"質問","question":"２８４ページの都市開発費について、都市開発に関連する都市軸の基盤整備を進めるという意味で質問をしたいと思います。その以前になるべく具体的な道路の位置というんでしょうか、机上で構わないと思うんですが、区内全域を見てどのような感じか尋ねました。","respondent":"上野都市開発課長","answer":"今までの通常の考え方というか、進め方といたしましては、その中で再開発事業を施行していくといったのが比較的多いかと思います。地元の方々へ案をお示しして、その内容等についてご説明をして、計画決定をしているといった状況にあります。","id":"exchange-105"},{"speaker":"本多委員","kind":"質問・要望","question":"具体的に決まらないと協議ができないという部分もあると思いますので、なるべく早めに判断材料にするという意味でお願いしたいなと思うんです。時限立法ですから、１０年間といって長いようなイメージがありますが、１０年間の時限立法との絡みについて教えてほしいと求めました。","respondent":"上野都市開発課長","answer":"これにつきましては開発事業を進めている事業者などを通じて地元に対してご説明していますけれども、先ほどの都市再生の１０年との絡みで申しますと。ご説明を申し上げて、その中で協議が進むような形で説明をしていきたいというふうに考えてあります。","id":"exchange-106"},{"speaker":"本多委員","kind":"意見","question":"測量を進めるにあたりましては、道路の拡幅するにあたりましては、原則道路の中心線から拡幅する、中心線から基準にするんだと思うんですが、必ずしもそうでないと思いますので、そういった意味で早め早めの情報があれば。","respondent":"上野都市開発課長","answer":"施行範囲がどこになるのか、道路をどこに位置づけるのかというもののご説明を地元の方々に計画決定の手続の中で行うことによって、詳細等を十分ご説明していきたいというふうに考えてあります。","id":"exchange-107"},{"speaker":"堺委員","kind":"質問・要望","question":"ちょっと確認で、確認で大変恐縮ですが、もう一度お尋ねをします。今回このように７１０万円の予算が計上されたわけですので、こういう強い要望がありますので、その辺についてのご見解を説明するよう求めました。","respondent":"中島街路事業担当課長、岩田管理工事課長、上川内生涯学習課長","answer":"１点目の補助１６３号線の完成年度ですけれども、本事業につきましては平成１４年４月から着工してございまして、７年間の事業期間です。したがいまして… 委員のご趣旨に沿ってできるだけ早めに完成するよう努力してまいりますが、ねじをまいて、早くできるように努力してまいります。その開放回数が２７３回あります。","id":"exchange-108"},{"speaker":"堺委員","kind":"質問・要望","question":"この完成目途はいつになるんでしょうか。使っていないときは無料開放で２８３とか、あるいは土曜、日曜の一般の利用実績が出れば教えてほしいと求めました。","respondent":"上野都市開発課長、上川内生涯学習課長","answer":"１点目の明電舎の整備の完成時期ですけれども、本年秋頃着工いたしまして、平成１９年の秋の遅い時期に竣工予定というふうになってあります。 土曜、日曜と夜間は分かれていなくて、数字はわかりません。","id":"exchange-109"},{"speaker":"堺委員","kind":"質問・要望","question":"第２とか、あるいは国際自動車の先に行きますと大井工場乗り越し線歩道橋というんですか、ここは特に狭いですよね。その辺も含めてちょっとご見解をお聞かせほしいと求めました。","respondent":"中島街路事業担当課長、岩田管理工事課長","answer":"１点目の百反坂下から補助２６号線までの間ですけれども、あるいは緊急性等を勘案して今回の事業になったということで、今やっている事業が一定程度目処が見えた段階でまた進めていきたいです。 実は利用制限はかけておりまして、一般の区民の方が利用されるであろう夏休み期間中とか、春休みとか、冬休みは学校優先枠に制限をかけております。","id":"exchange-110"},{"speaker":"川西委員","kind":"質問・要望","question":"これだけの大きな公園ですから、所管課のほうで全部設計して委託してしまうということはまずないでしょう。そういう点について、設計委託に到るまでの段取りを教えてほしいと求めました。","respondent":"岩田管理工事課長","answer":"ただし、当時下水道局が設置しております下水道ポンプ場の屋上も区がお借りして庭園とする予定だったんですが、そこへの車椅子対応のスロープが。機械的な昇降施設等で対応するかどうか、若干基本計画の内容が変わってまいりますので、そういうものです。","id":"exchange-111"},{"speaker":"川西委員","kind":"質問・要望","question":"若干基本計画の修正部分もあり得るということですから、どこでどういうふうに影響のない程度に意見が入れられるか、よろしくお願いします。ですから、取り入れてもらいたいぐらいの希望は持っていますけれども、気を付けていただきたい。","respondent":"岩田管理工事課長","answer":"ご案内のとおり、公共溝渠は、従来国有財産ですけれども、昨年をもちまして、ほとんどの公共溝渠については区の土地になりました。不要になるものについては積極的に売却をしていくということで、現在払い下げのご希望のあるところの方との詰めの作業をしておるところです。","id":"exchange-112"},{"speaker":"川西委員","kind":"質問・要望","question":"そういうものについては、これはしようがないですから、ちゃんと賃料をいただくとか、買い取っていただくとかという方法が必要だと思います。ですから、では、残った公共溝渠部分は区がどうするのかということをしっかり平成１６年度に進めてほしいと求めました。","respondent":"岩田管理工事課長","answer":"ただ、今は中断をしているようですけれども、今回の中央環状の工事ヤードの関係が出てまいりました。それから、東京都のほうの中央環状の換気塔の計画等を勘案しながら、どうするかを決めてまいりたいと思います。","id":"exchange-113"},{"speaker":"川西委員","kind":"質問・要望","question":"大体状況は分かるんですけれども、開発といいますか、危険物の作業部門は東京都の外に出ました。ですから、開発計画がもうほとんど終わりに近いというふうに思いますので、よく調査をしていただきたいと、要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"須貝委員","kind":"質問","question":"２９１ページ、建築行政費と、２８２ページ、公園管理費について、質問をします。本来なら、やはり商店街の中は１階部分に関しては商店を建ててくださいと、その辺についてご見解を説明するよう求めました。","respondent":"浜脇住環境整備課長","answer":"そういった意味では、あの頃ちゃんと私どもがやっておれば、そういった商店街の支援が検討できたのかなと考えています。そういった意味では残念だと思いますけれども、現実的にはこういうふうになっているというのが実情です。","id":"exchange-115"},{"speaker":"須貝委員","kind":"質問","question":"まちづくり事業部としてもちょっとお聞きしたいんですけれども、商店街づくり、まちづくりをしてきたわけですね。片一方は商店街を応援してきて、こういうふうに建っていってしまうということに対しまして、まちづくり事業部の見解を説明するよう求めました。","respondent":"中谷まちづくり事業部長","answer":"商店街の振興を進めている中で、産業振興課とも連携を図りながら、そういう意見交換をまずはすることが大切なのかなと。産業振興課のほうと十分連携を図りながら進めていきたい、このように考えております。","id":"exchange-116"},{"speaker":"須貝委員","kind":"質問・要望","question":"３６５日の中で、トラックが必要ならば、ラインを引いておけばいいんです。何か事故があったら、かえって汚点が残るのではないかなというふうに私は思うんですけれども、ご見解を説明するよう求めました。","respondent":"岩田管理工事課長","answer":"そして人工芝と、そういう構造になりますので、基礎がしっかりいたします。そこがきちっと段差のないように、つっかかったりなんかしないような形で設計をするようにしてまいりたいと思います。","id":"exchange-117"},{"speaker":"須貝委員","kind":"意見","question":"できれば、そこら辺もできるだけ障害のない、違和感のないような施行をしていただくとありがたいなと思います。今のままだったら、必ずけが人が出てくると思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-118"},{"speaker":"松澤委員","kind":"質問","question":"２９１ページ、６款土木費、５項建築費、１目建築行政費、何人かの委員から質疑がありましたけれども、建築紛争に関連して質問をしたいと思います。品川区ワンルーム形式と集合建築物に関する指導指針、品川区みどりの条例、この四つに流れている精神とか心についてお教え願いたいと思います。","respondent":"中谷まちづくり事業部長","answer":"あるいは環境開発指導要綱等の考え方についてですが、安全、快適なまちづくりというのを進めておるわけです。各施策を整合性をとりながら進めるですが、これらまちづくりを進めていく上で、このようなものです。","id":"exchange-119"},{"speaker":"松澤委員","kind":"質問","question":"これは今の建築基準の改正前ですから、２０ｍを超える高い建物は隣地との斜線もあるんですよという中で、大きな敷地がないと建てられない。それについて建築基準法の改正の目的をお教え願いたいと思います。","respondent":"片田建築課長","answer":"それを一つのメニューとして、こういう考え方もあると。ただ、いろいろなメニューを設けた中で、まちづくりの一つの支援としてつくってきたということで認識しております。","id":"exchange-120"},{"speaker":"松澤委員","kind":"質問・要望","question":"斜線があったから、そんな小さい建物ができなかったんですから。建築確認も通っているから合法になります。","respondent":"片田建築課長","answer":"安全上の基準で設けているのは、建築基準法の委任条例という形で、東京都の建築安全条例があります。その中で地域にあったということで、ほかの都道府県とは別に東京都独自で条例を定めまして、安全上の基準を別途設けているといったようなことです。","id":"exchange-121"},{"speaker":"松澤委員","kind":"質問","question":"違反も何もしていないわけですから、合法的です。建築基準法は坪数を書いてないものですから、あるいは指導指針、すぐ変える気持ちがおありか尋ねました。","respondent":"浜脇住環境整備課長","answer":"この指導要綱が大方１００件ぐらい開発指導要綱で協定を結ぶんですが、その中で１５項目ぐらいいろいろな要望を出してやっていただいているわけです。ほかの１４項目については、指針を変えたほうがいいというふうには、私どもは現在は捉えてございません。","id":"exchange-122"},{"speaker":"松澤委員","kind":"質問・要望","question":"法律が改正になって、できたばかりですから、どこの区でもいろいろな問題があるんでしょう。先ほどうちの政調会長も質問をしましたけれども、２３区もどんどん改正している。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"高星委員","kind":"質問・要望","question":"いろいろとスケジュールがあるものですから、端的にお聞きしますので、端的に明快なご回答をお願いいたします。あるいは都道が対象なのか、区道も含むのか、あるいは青空駐車についてはどうなのかということをちょっとお聞かせほしいと求めました。","respondent":"市岡企画財政課長、矢部下水道河川課長、奈良交通安全担当課長、藤田都市計画課長","answer":"それぞれ各事業部、その目的を失わず、なおかつ大事な公有財産の一層の活用を高めるような努力をしてまいりたいというふうに考えてあります。説明会だけでも５回開いて工事を進めております。平成１７年の雨期までには完成させたいと考えています。交通量の多いところ、あるいはバイクの違法駐輪が多い路線につきまして、警視庁と警察署が協議して決定をしているものです。１２時間… 平成１５年１２月１２日から１月１３日まで縦覧を行いまして、その中の７割から８割方が品川区のほうからの意見であったと。","id":"exchange-124"},{"speaker":"高星委員","kind":"質問・要望","question":"これは品川区が実施母体でないですから、何とも言えないけれども、しかるべきところに大きな声を上げていっていただきたいというふうに思います。結果として、新しくできたマンションの１階部分のかなりの平米数を保育園の一部として区が受け取ったじゃないか尋ねました。","respondent":"本間総務部長、奈良交通安全担当課長","answer":"その事業の公益性等々十分近隣の皆様にご説明をし、円滑に事業推進を図るという、基本的な考え方は変わりございません。今後もこういうことで対応をしていきたい、かよう考えているところです。 各地域に応じて緊急的な部分のあるところについては優先的に鍵付の指定路線をしておりますけれども、これは警視庁の方針としては、徐々に拡大をしていく方向というふうに聞いております。","id":"exchange-125"},{"speaker":"高星委員","kind":"質問・要望","question":"ですから、もう間もなく日照ゼロになってしまう。だから、しかるべき首脳部会議等々でもできることならやっていただきたいなというふうに、これは要望したいと思います。","respondent":"奈良交通安全担当課長","answer":"苦労話と言われてもあれですけれども、私は２年間在籍しておりますけれども、品川区というのは職員も非常に地域住民の方に目を向けて仕事をしている。","id":"exchange-126"},{"speaker":"沢田委員","kind":"確認","question":"建築確認がおりても、住宅が１日丸々日影になってしまった場合には、品川区の中高層棟の紛争予防条例があるわけです。あるいは代替措置、あるいは削るということはやらないものなのかどうなのか、ちょっと考え方をお尋ねします。","respondent":"岩田管理工事課長","answer":"したがって、受忍限度を越えるような騒音、振動、影響を与えない範囲で工事を行うし、設計も行う。これが公共工事です。","id":"exchange-127"},{"speaker":"沢田委員","kind":"質問","question":"３階と、７時間の日影を受けるというのは、私は受忍限度をとうに越えている中身だと思います。もう少し詳しく、都営浅草線のエスカレーターができたということなども含めて、教えてもらえればありがたいと思います。","respondent":"上野都市開発課長","answer":"すでに今年の１月に着工をいたしてございまして、工事そのものが調整していますけれども、平成１７年秋頃に供用開始予定となっています。それから、東急電鉄とのバリアフリー化の計画につきましては、先ほどご説明したように、協議中です。","id":"exchange-128"},{"speaker":"沢田委員","kind":"提案","question":"約５億円かかるという話を聞いたんですけれども、まだ進んでいないようだということなので、もう少し詳しく教えていただきたい。具体的な問題を一つ提案したいと思うんですが、たくさんの施設が次々と出てくるとの意見を述べました。","respondent":"上野都市開発課長、市岡企画財政課長","answer":"１点目の、平成１５年度中に着手して、平成１６年度に供用したいという考えがあるというお考えを伺っておりましたけれども。区としての考え方、そういったものも明確にしながら、申し入れをしていきたいというふうに考えてあります。 五反田駅周辺につきましては、今回まちのサインの書き替えということで、東口、西口それぞれ書き替えを行うものです。","id":"exchange-129"},{"speaker":"沢田委員","kind":"提案","question":"改めて、今日言って明日ということではないんですけれども、ぜひ提案の趣旨を汲んでいただいて、取り組んでほしいと求めました。２点目は、この問題はその後どうなったか、経過を教えてほしいと求めました。","respondent":"奈良交通安全担当課長","answer":"いわゆる横断歩道を設置してもらいたいというお話については、警察のほうの見解が平成１９年度にアンダーパスが開通をしますので、今も変わっていないです。","id":"exchange-130"},{"speaker":"沢田委員","kind":"質問・要望","question":"再度お尋ねしたいんですけれども、２３０ｍの間に三つも信号ができたら危ないからというんだけれども、これは交通を優先した考え方ですね。どうも納得いかない、腑に落ちないというふうに思いますけれども、その見解も含めて、今後の対応の仕方をお答え願えるとありがたいんです。","respondent":"奈良交通安全担当課長","answer":"４月以降に信号がついた段階で考えるというお話については、委員のご指摘を踏まえて警察のほうには要望をしてまいりたいと思います。そうすれば５分も１０分もかからないんですから、これは基本的な考え方だと思いますので、ご理解のほどよろしくお願いいたします。","id":"exchange-131"},{"speaker":"沢田委員","kind":"質問・要望","question":"こういう構造の道路にしたいけれどもどうかという話があれば、まだ納得できるんでしょうけれども、皆さんは納得していないんですね。ですから、その点で後追いになりますけれども、区としてできるだけのことはやっていただきたい、このように思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"三上委員","kind":"提案","question":"車が通るなどということはとても無理だというような状況があるわけですから、ぜひ区のご努力をほしいと求めましたが、いかがでしょうか。ですから、現実何棟あって、そのうち戸数が何戸で、現在閉鎖されているところが何戸あるのかというのを、数字だけでもお教えほしいと求めました。","respondent":"矢部下水道河川課長、中島街路事業担当課長、田村住宅課長","answer":"道路公園課長を含め、まちづくり事業部のほうでその辺の情報をもう少し整理をしまして、検討をします。そういうことで、まちづくり事業部の中で検討をしま… 不動前駅高架下の環状６号線側、約１,０００m2のところに東急電鉄系列のストアができるというふうな計画があるということは聞いてあります。… 昭和３３年に建設しまして、戸数が５４棟ということで、空きが何戸あるかというのは現在のところ把握しておりません。","id":"exchange-133"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、そこの１戸の方については、そこをつぶしてもいいじゃないか。そこらあたりをちょっとやりとりやっていただけないか、こうお願いするんですが、いかがか尋ねました。","respondent":"田村住宅課長","answer":"今、三上委員のほうからご指摘がありましたので、都営住宅ではありますが、そういう現況があるということでしたら、私どものほうから住宅局の所管のほうに伝えて、早急に対応するなり、調査してもらうというふうに考えております。","id":"exchange-134"},{"speaker":"三上委員","kind":"意見","question":"最後に、近隣住民の方も大変心配しておりますので、そういった意味にあってはぜひ早急に東京都のほうと話し合いを進めていってほしいと求めましたので、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-135"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、りんかい線のどこ行きが何時出発するという掲示板、これが実は入口から３分経たないと見えない状況にあるわけです。ですから、エスカレーターの途中でもいいから、例えばどこ行きが何時に出るとか、電光掲示板を付けたらいかがでしょうかということをお伺いしたい。","respondent":"奈良交通安全担当課長、藤田都市計画課長","answer":"大井水神公園のホームレスの関係ですけれども、これも以前道路公園課と協力しながら、一旦は排除したケースもあります。住み込んでいるといいますか、区と警察で連携を図りながら… 私もとりあえず走っていっておこうかなというのが、毎回思っているところです。そういったこともありますので、改めまして、りんかい線のほうにはそういった要望があるということを伝えてまいりたいというふうに考えてあります。","id":"exchange-136"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、ぜひお願いしたいのは、改めて大井水神公園に対するホームレスの皆さんに対する対処の仕方をもう一つはっきりした答弁をお願いしたい。大きなことでなくて、ぜひそれは細かいところから対処していってくださることを、こちらのほうは要望しておきます。","respondent":"松代道路公園課長","answer":"私ども数年前から大井水神公園のホームレスに全力を上げて対応してまいりました。今ご指摘を受けたような点、反省をしまして、先ほど申しましたように、連携を図って、再度適正な管理をするように努めてまいります。","id":"exchange-137"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/906948?Template=document&Id=830#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":113575,"voices":345}}]);
